_DESCRIPTIONS = json.loads('{"260854":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Professional Services<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p></p><p><span>This role requires the candidate to have the opportunity to develop massively scalable solutions to solve complex data and AI problems using Cloudera technology. This role is a client facing opportunity that combines consulting skills with deep technical design and development in the Data and AI space. This role will present the successful candidate the opportunity to work across multiple industries and large customer organizations.</span></p><p></p><p>This role is not eligible for Immigration Sponsorship or relocation.</p><p></p><h2>As a Solutions Architect, you will<span>:</span></h2><ul><li><p><span>Design innovative, scalable solutions tailored to customer business needs using Cloudera Data Services, leveraging proven reference architectures and industry best practices.</span></p></li><li><p><span>Serve as a trusted technical advisor, helping customers maximize the value of Cloudera&#39;s Anywhere Cloud and Data Services portfolio.</span></p></li><li><p><span>Partner closely with Product Management, Engineering, and cross-functional teams to ensure customers experience a unified Cloudera vision and seamless engagement.</span></p></li><li><p><span>Champion customer success by translating field feedback into actionable product enhancements and influencing the product roadmap.</span></p></li><li><p><span>Lead customers through the design, deployment, and optimization of Anywhere Cloud and Data Services, ensuring reliable, secure, and high-performing implementations.</span></p></li><li><p><span>Introduce best practices, automation, and troubleshooting methodologies to streamline deployments, upgrades, and ongoing operations.</span></p></li><li><p><span>Analyze complex distributed production environments, identify performance bottlenecks, and recommend architectural improvements to enhance scalability, reliability, and efficiency.</span></p></li><li><p><span>Support customers throughout their technical journey by identifying new use cases, solving complex challenges, and driving successful adoption of Cloudera technologies.</span></p></li><li><p><span>Collaborate with domain experts, data scientists, AI practitioners, and engineering teams to design and implement innovative AI and data-driven solutions.</span></p></li><li><p><span>Represent Cloudera as a technical thought leader by participating in conferences, webinars, meetups, blogs, and other community engagement initiatives, sharing expertise and promoting industry best practices.</span></p></li></ul><p></p><p><b>We are excited if you have (Required Experience):</b></p><ul><li><p><span>8&#43; years of backend development experience with strong expertise in</span> <span>Python and Go programming languages.\\u00a0</span></p></li><li><p><span>Bachelor\\u2019s degree in Computer Science, Engineering, Information Systems, Business, or a related field or equivalent practical experiences</span></p></li><li><p><span>Familiarity with NVIDIA GPU technologies</span></p></li><li><p><span>Hands-on knowledge of the data ecosystem, including AI/ML, data warehousing, data engineering, and data-in-motion technologies</span></p></li><li><p><span>Experience with Amazon AWS, Microsoft Azure, and/or Google Cloud, including relevant skills and certifications</span></p></li><li><p><span>Experience with designing Kubernetes APIs, CRDs &amp; Controllers with emphasis on backward compatibility.</span></p></li><li><p><span>Experience building the utilities, providing solutions, and reference architectures.</span></p></li><li><p><span>Strong troubleshooting skills and experience resolving complex issues in Kubernetes, networking, and storage.</span></p></li><li><p><span>Experience working in the Cloud Native Computing Foundation (CNCF) community\\u00a0</span></p></li><li><p><span>Ability to go deep into technology and complex distributed systems.\\u00a0</span></p></li><li><p><span>Self-driven and motivated, with a strong sense of ownership and craftsmanship</span></p></li><li><p><span>Strong written and verbal communication skills</span></p></li></ul><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-AC1</p><p>#LI-HYBRID</p>","260992":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>HR<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Entry level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p><span>As the HR Services Specialist, you will play a key role in delivering exceptional employee service and ensuring operational excellence across HR services. You\\u2019ll serve as a key resource for employee inquiries, manage the HR ticketing system, and contribute to cross-functional initiatives that enhance the overall employee experience. This role is a great fit if you\\u2019re a service-oriented HR professional with strong knowledge of immigration processes and a passion for delivering high-quality, people-focused solutions.</span></p><p></p><p><b><b>As the HR Services Specialist\\u00a0 you will:</b></b></p><p></p><p><b><b>Employee Experience &amp; HR Service Delivery</b></b></p><ul><li><p><span>Act as a primary HR contact, ensuring timely, high-quality support through ticketing systems.</span></p></li><li><p><span>Drive efficient resolution of employee inquiries across benefits, payroll, policies, and systems.</span></p></li><li><p><span>Maintain service excellence by overseeing ticket triage and escalation pathways.</span></p></li><li><p><span>Serve as the primary resource for immigration-related inquiries from employees, HRBPs, and managers, providing clear guidance and support</span></p></li></ul><p></p><p><b><b>HR Process Optimization &amp; Projects</b></b></p><ul><li><p><span>Contribute to cross-functional HR initiatives to streamline operations and elevate employee experience.</span></p></li><li><p><span>Drive policy development, process documentation, and self-service enablement.</span></p></li><li><p><span>Assist in optimizing onboarding, offboarding, and data management workflows.</span></p></li><li><p><span>Continuously looking to improve processes and creating efficiencies</span></p></li></ul><p></p><p><b><b>Stakeholder &amp; Systems Collaboration</b></b></p><ul><li><p><span>Partner with HR, IT, and business teams to ensure seamless, tech-enabled service delivery.</span></p></li><li><p><span>Leverage HR systems (e.g., Workday) and collaboration tools to manage data and drive insights.</span></p></li><li><p><span>Uphold data integrity and privacy standards across all employee records and processes.</span></p></li><li><p><span>Work closely with immigration partners, managing cases and updating employees on any relevant immigration changes\\u00a0</span></p></li></ul><p></p><p><b><b>We\\u2019re excited about you if you have:</b></b></p><ul><li><p><span>Bachelor\\u2019s degree in Human Resources, Business Administration, or related field</span></p></li><li><p><span>3&#43; years of experience in HR Services, Operations, or a similar role</span></p></li><li><p><span>Hands-on experience with HR ticketing systems (e.g., HappyFox, ServiceNow)</span></p></li><li><p><span>Proficient in HRIS platforms; Workday experience strongly preferred</span></p></li><li><p><span>Excellent communication skills with the ability to support employees at all levels</span></p></li><li><p><span>Highly organized and detail-oriented, with strong multitasking skills in fast-paced environments</span></p></li><li><p><span>Collaborative mindset with experience working across global teams and time zones</span></p></li><li><p><span>Strong understanding of HR policies, compliance, and best practices</span></p></li><li><p><span>Trusted to handle sensitive information with discretion and professionalism</span></p></li><li><p><span>Skilled in process improvement, problem-solving, and cross-functional collaboration</span></p></li><li><p><span>Ability to build strong partnerships with internal stakeholders and external vendors</span></p></li><li><p><span>Proficient in creating and using presentations and spreadsheets (e.g., Google Slides, Sheets, Excel)</span></p></li></ul><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-AW1</p><p>#LI-Hybrid</p>","251446":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>The Cloudera Product Engineering Team is seeking a talented Staff Software Development Engineer to drive continuous improvement in our Data Platform. You will play a critical role in the development, testing, and delivery of high-quality features for the CDP platform, specifically focusing on the Cloudera REST Catalog and Cloudera Lakehouse Optimizer.</span></p><p></p><p><span>As a Staff Software Engineer, you will work on complex issues requiring in-depth evaluation of variable factors. You will exercise independent judgment in selecting methods and techniques to obtain results, and you will be expected to lead, mentor, and guide a group of junior engineers while ensuring project milestones are met.</span></p><p></p><p><b>As a Staff Software Engineer you will:\\u00a0</b></p><ul><li><p><span>Design and develop features in Cloudera Iceberg REST Catalog and Cloudera Lakehouse Optimizer product areas.</span></p></li><li><p><span>Develop comprehensive strategies for automated testing (incorporating negative, regression, and end-to-end testing) and performance testing. Leverage AI/tools where applicable to write new tests for existing and new features.</span></p></li><li><p><span>Build advanced automated testing frameworks, tools, and suites in Python (pytest), Shell, or Java (TestNG/JUnit) to ensure upgradeability, scalability, and stability.</span></p></li><li><p><span>Design, automate, and execute tests that ensure product reliability under stress, effective failure recovery, and seamless version upgrades with minimal downtime. Verify horizontal/vertical scaling behavior.</span></p></li><li><p><span>Work with documentation team to create or enhance product documentation. Author blogs on product features or best practices to promote adoption and awareness</span></p></li><li><p><span>Partner closely with Dev/PM teams to ensure code testability, build necessary test hooks, and define project schedules and resource allocation models for successful delivery.</span></p></li><li><p><span>Lead, mentor, and guide junior engineers. Advocate for engineering best practices, quality standards, and continuous resilience validation within CI/CD pipelines (Jenkins).</span></p></li><li><p><span>Engage with customers, seek their feedback and enhance product usability and visibility. Debug system-level deployment issues, conduct root cause analysis, and resolve failures. </span></p></li></ul><p></p><p><b>We are excited about you if you have (Required Experience):\\u00a0</b></p><ul><li><p><span>7&#43; years of related experience.</span></p></li><li><p>Strong knowledge in at least one of: Java or C&#43;&#43;.</p></li><li><p>Hands-on experience with Unix/Linux and DevOps technologies (Docker, Kubernetes, Ansible, Jenkins, Github, Maven).</p></li><li><p>Strong knowledge of QA methodology, test case/plan creation, and automation framework debugging.</p></li><li><p>Working knowledge of AWS/Azure/GCP cloud environments.</p></li><li><p>Experience with upgrades, scalability in distributed systems, and Airflow frameworks.</p></li><li><p>General knowledge of large-scale distributed systems and/or data management systems.</p></li><li><p><span>Excellent communication and collaboration skills. Proven ability to work from broad specifications to independently resolve challenging design/enhancement issues and troubleshoot production failures.</span></p></li></ul><p></p><p><b><span>You may also have:</span></b></p><p></p><ul><li><p><span>Working knowledge of the Hadoop ecosystem.</span></p></li><li><p><span>Experience with Generative AI applications.</span></p></li><li><p><span>Demonstrated history of leading a group of engineers to deliver on a complex project plan.</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-EO1</p><p>#LI-HYBRID</p>","260981":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><h1>Job Title: Staff Software Engineer in Test - Anywhere Cloud - Performance and Scale</h1><h2>Team Overview</h2><p><span>Ready to take cloud innovation to the next level? Join Cloudera\\u2019s Anywhere Cloud team and help deliver a true \\u201cbuild your own pipeline, bring your own engine\\u201d experience. enabling data and AI workloads to run anywhere, without friction or vendor lock-in.</span></p><p><span>We take the best of the public cloud- cost efficiency, scalability, elasticity, and agility and extend it to wherever data lives: public clouds, private data centers, and even the edge. Powered by Kubernetes, our hybrid architecture separates compute and storage, giving customers maximum flexibility and optimized infrastructure usage.</span></p><h2>The Role</h2><p><span>As a </span>Staff Software Engineer in Test<span> you will architect automation framework and tools that validates a highly distributed, multi-cluster control plane from performance and resilience point of view. You will own the test strategy for AWC\\u2014validating it both as an application installed via Taikun and as a platform that orchestrates other clusters. You will define how we verify Zero-Trust security models, API-first contracts, and cross-cluster resource management.</span></p><h2>Key Responsibilities</h2><ul><li><p>Test Architecture Leadership:<span> Design, architect, and scale comprehensive automated performance frameworks capable of validating the core control plane, cluster provisioning, and multi-cluster engine deployments under massive load.</span></p></li><li><p>Baseline:<span> Create baseline test suites for measuring performance from release to release.</span></p></li><li><p>Data Layer &amp; Metastore Scale Testing:<span> Build high-concurrency test suites for the containerized metadata and storage layers to ensure they meet strict enterprise-grade targets for vast table limits, high operations per second, and concurrent client support with extremely low read latency.</span></p></li><li><p>Mentorship &amp; Optimization:<span> Profile performance bottlenecks in microservices, analyze underlying infrastructure resource utilization, provide architectural optimization recommendations to engineering teams, and mentor junior and mid-level test engineers on distributed systems performance testing.</span></p></li><li><p>Cross-Functional Collaboration:<span> Partner with the Taikun (Kubernetes) and Foundational Services teams to integrate their components (Cert Manager, DBs, Logging) into the AWC test matrix.</span></p></li></ul><p></p><p>Requirements</p><ul><li><p>Experience:<span> 8&#43; years of professional Software in Test (SDET), Performance Engineering, or Quality Engineering experience, with a proven track record as a Staff/Lead Engineer (IC4) building large-scale performance testing frameworks for distributed cloud-native platforms.</span></p></li><li><p>Performance Engineering Mastery:<span> Deep expertise in building custom load generators and using industry-standard tools (e.g., JMeter, Gatling, Locust, k6) to validate throughput, latency, and concurrency limits across REST, gRPC, and database connections.</span></p></li><li><p>Kubernetes &amp; Infrastructure:<span> Deep, hands-on expertise in Kubernetes scaling limits, profiling node/pod resource bottlenecks, evaluating Service Mesh (Istio ambient mode) overhead, and benchmarking storage IOPS (Ceph, S3 object storage).</span></p></li><li><p>Programming Languages:<span> Expert-level coding proficiency in Go (Golang), Python, or Java to build robust performance test frameworks and custom Kubernetes operators for stress testing.</span></p></li><li><p>Engine &amp; Data SME:<span> Advanced understanding of modern compute/streaming engine performance characteristics (Spark memory tuning, Kafka throughput, Flink state backends) and Lakehouse scale limitations (Apache Iceberg).</span></p></li><li><p>Observability &amp; Profiling:<span> Advanced knowledge of integrating and utilizing observability stacks (Prometheus, Grafana, OpenTelemetry) to monitor p95/p99 latencies, track resource utilization, and identify memory leaks or CPU bottlenecks during soak tests</span></p></li></ul><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p>","260805":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales Operations<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p></p><p><span>The EMEA Field Operations Team is a high-visibility, high-impact function, acting as strategic advisors to the SVP of EMEA Sales and the regional leadership team. We drive the go-to-market (GTM) strategy and execution for the region, optimizing coverage and quota models in line with finance and revenue budgets. We manage the operational rhythm for the region\\u2014including forecasting, pipeline reviews, renewal workflow optimization, and QBRs. We are obsessed with data\\u2014standardizing, automating, and converting complex data sets into actionable insights that power data-driven decisions.</span></p><p></p><h3></h3><p><span>We are looking for a super analyst and proactive business partner to join the team.</span></p><p><span>This role blends a high level of proactive business partnership with astute data analysis skills. You will manage everything from territory planning, operational excellence, data infrastructure ownership, and financial/operational modelling. You won&#39;t just pull data; you will connect the dots between the metrics, performance drivers and strategy, crafting the narrative for leadership.</span></p><p><span>If you thrive in a fast-paced environment and love turning complex data sets into compelling narratives that trigger business action, this might be the role for you</span></p><p></p><p></p><p><b><b>As a Senior Analyst, EMEA Field Operations, you will:</b></b></p><p></p><ul><li><p><b><b>Regional Business Partnership:</b><span> </span></b><span>Serve as the trusted, proactive Field Operations partner to the META regional leadership team. You will not just report on performance\\u2014you will actively diagnose business health, anticipate blind spots, and deliver targeted interventions that empower the sales team to maximize pipeline conversion and exceed revenue goals.</span></p></li><li><p><b><b>GTM &amp; Territory Optimization:</b><span> </span></b><span>Lead the go-to-market planning cycle for the META region, optimizing territory coverage, quota allocation, and resource mapping.</span></p></li><li><p><b><b>The Operational Rhythm:</b><span> </span></b><span>Own and optimize the operational cadences for weekly forecasting, pipeline health checks, and quarterly business reviews (QBRs), ensuring accuracy and consistency across IC and manager levels.</span></p></li><li><p><b><b>Data Storytelling &amp; Analytics:</b><span> </span></b><span>Design, modify, and maintain advanced business assets and dashboards. Extract key metrics to provide insightful commentary that drives the sales narrative across all regular operational reviews.</span></p></li><li><p><b><b>Executive Insights:</b><span> </span></b><span>Synthesize complex datasets into concise, high-impact narratives to support the annual GTM exercise and executive level presentations and QBRs.</span></p></li><li><p><b><b>Process Improvement &amp; Scale:</b><span> </span></b><span>Identify systemic roadblocks and leverage data automation to streamline day-to-day operations, moving the team toward proactive, AI-driven insights</span><b><span>.</span></b></p></li><li><p><b><b>Cross-Functional Collaboration:</b><span> </span></b><span>Partner daily with the broader GTM Operations team, Deal Desk, HR, Finance, and Marketing to align regional execution with overall company strategic drivers.</span></p></li></ul><p></p><p></p><p><b><b>We are excited about you if you bring:</b></b></p><p></p><ul><li><p><b><b>Experience:</b><span> </span></b><span>5&#43; years of experience in Sales Operations, Revenue Operations, or a highly analytical business partnership role, with a deep understanding of enterprise sales cycles, commercial execution, and forecasting models.</span></p></li><li><p><b><b>The &#34;Super Analyst&#34; Mindset:</b><span> </span></b><span>Innate business curiosity with a proven ability to dig beneath the surface of large, disparate datasets to independently uncover root causes, emerging trends, and strategic opportunities.</span></p></li><li><p><b><b>Elite Presentation &amp; Narrative Design:</b><span> </span></b><span>Obsessed with building high-impact visual slides (Google Slides or PowerPoint) that convert complex data into crisp, executive-ready stories designed to drive alignment and trigger action.</span></p></li><li><p><b><b>Technical Skillset:</b><span>\\u00a0</span></b></p><ul><li><p><span>Proven mastery of advanced data modeling in Google Sheets or Microsoft Excel is required.</span></p></li><li><p><span>Demonstrated success scoping operational requirements, mapping data flows, and collaborating with central BI teams to build and scale automated dashboards and data assets.</span></p></li><li><p><span>Forward-thinking approach to AI integration: Comfortable coming with us on the journey to leverage modern AI tools and LLMs to optimize day-to-day processes, streamline data interpretation, and accelerate analytical workflows.</span></p></li><li><p><span>Strong working proficiency in Salesforce.com (SFDC), Clari, Tableau, or Anaplan is a distinct advantage.</span></p></li></ul></li></ul><p></p><ul><li><p><b><b>Thrives in Velocity:</b><span> </span></b><span>A self-starter who demonstrates accountability, balances competing high-priority demands, and maintains meticulous attention to detail in a fast-paced environment.</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><div>#LI-AW1</div><div><div><div><div><div><div><div><div><div><p>#LI-Hybrid</p></div></div></div></div></div></div></div></div></div>","260958":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Corp. Strategy<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Director<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><b>Customer Pricing Director</b><span><b> </b>is accountable for the overall coordination, strategic alignment, and success of large deal commercial structuring and field pricing execution. This role focuses on managing strategic, complex deals, developing repeatable commercial programs, and driving high-growth outcomes alongside account teams. Engagements cover high-stakes, complex customer opportunities and programmatic commercial initiatives across the enterprise.</span></p><p></p><p><span>Serving as a strategic partner and commercial force multiplier for field sales, this function requires an extremely proactive, customer-centric, and analytical leader who will ensure both optimal deal structuring and seamless pricing execution in the field.</span></p><p></p><h2><b><b>As a Customer Pricing Director you will:</b></b></h2><ul><li><p>Commercial Deal Structuring:<span> Plan and execute programmatic large deal commercial structuring for strategic accounts, working closely with Pricing Strategy, Value Management, and Sales leadership to drive growth through complex but scalable deal design.</span></p></li><li><p>Field Execution &amp; Feedback Loop:<span> Drive true pricing execution with the field, gathering and analyzing customer-centric monetization feedback from live deals to continuously optimize commercial frameworks and track financial impact.</span></p></li><li><p>Deal Team Collaboration:<span> Sit &#34;in the room&#34; with account teams to manage complex deal dynamics, align cross-functional dependencies, and help structure the commercial side of high-stakes opportunities.</span></p></li><li><p>Repeatable Program Building:<span> Proactively translate unique, complex deal structures into repeatable commercial programs and frameworks\\u2014imperative for scaling field adoption as market dynamics shift.</span></p></li><li><p>Cross-Functional Alignment:<span> Facilitate deep engagement between the field, Pricing Strategy, and Value Management to ensure corporate consistency, strategic alignment, and value-backed commercial models.</span></p></li></ul><p></p><h2><b><b>We\\u2019re excited about you if you have:</b></b></h2><ul><li><p><span>6-8&#43; years of experience in Commercial Deal Structuring, Deal Desk, Pricing Strategy, Value Management, Sales Operations, or Strategic Account Management.</span></p></li><li><p><span>Prior experience in high-growth B2B tech, SaaS, or digital services environments managing large, complex, multi-product enterprise deals is highly preferred.</span></p></li><li><p><span>Deep understanding of custom deal structuring, value-based pricing models, discounting frameworks, and contractual commercial levers.</span></p></li><li><p><span>Skillful at translating complex corporate pricing strategies into clear, actionable, and customer-centric commercial options for field sales teams to minimize friction.</span></p></li><li><p><span>Proven mastery of large deal governance, commercial coaching, and programmatic field execution processes.</span></p></li><li><p><span>Strong capability to interpret complex customer deal data, profitability metrics, and value-realization models to drive growth-oriented decisions.</span></p></li><li><p><span>Experience defining KPIs and tracking mechanisms to evaluate the long-term health, profitability, and repeatability of strategic commercial programs.</span></p></li><li><p><span>Proficiency in leveraging CPQ systems, CRM platforms (like Salesforce), Excel, and financial modeling tools to structure and track large enterprise deals.</span></p></li><li><p><span>Demonstrated history of being &#34;in the room&#34; to successfully co-pilot high-stakes, multi-million dollar commercial deal negotiations from inception to execution.</span></p></li><li><p><span>Sharp collaborative skills to bridge the gap between abstract pricing strategy and real-world field sales execution.</span></p></li></ul><p></p><p><b><b>This role is not eligible for immigration sponsorship.\\u00a0</b></b></p><p></p><p><b><span>The anticipated annual base salary range for this position is:</span></b></p><p><span>Illinois: $157,000- 175,000</span></p><p><span>Colorado: $157,000- 175,000</span></p><p></p><p><span>Individual compensation within the published range is determined by the candidate&#39;s skills, experience, qualifications, and primary work location. In addition to base pay, sales roles are eligible for Cloudera&#39;s commission plan, while non-sales roles are eligible for the corporate incentive plan. All employees receive a comprehensive benefits package.\\u00a0</span></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI - Remote</p><p>#LI-MH2</p>","260948":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Cloudera Solutions Engineers are the technical leaders in the sales account team. We\\u2019re a close-knit community and truly enthusiastic about our work, which gives us the opportunity to grow our personal reputation both internally and externally in the data community. We are responsible for securing the technical win in each sales opportunity and for building an ongoing relationship with our customers to ensure their business success with Cloudera technologies</span></p><p></p><p><b><b>As a Senior Solutions Engineer you will:</b></b></p><ul><li><p><span>Own the technical sales process from introductory meetings (net new sales) through post-sales (customer satisfaction, upselling, and subscription renewals)</span></p></li><li><p><span>Supporting the technical needs of customers includes discovering new use cases for Cloudera\\u2019s technology</span></p></li><li><p><span>Designing solutions for your customers\\u2019 needs using Cloudera technologies, based on reference architectures and common patterns</span></p></li><li><p><span>Demonstrating Cloudera products in a way that inspires your customers to say \\u201cyes\\u201d to Cloudera</span></p></li><li><p><span>Partnering with your Account Managers to show your customers the true value of a Cloudera solution and drive successful sales</span></p></li><li><p><span>Presenting product roadmap and vision to inspire your customers to think bigger</span></p></li><li><p><span>Interfacing with other Cloudera teams to ensure your customers hear one Cloudera voice\\u00a0</span></p></li><li><p><span>Advocating for your customers\\u2019 needs to Product Management and Engineering</span></p></li><li><p><span>Participating in external publicity and evangelism (conferences, meetups, webinars, blogs)</span></p></li><li><p><span>Achievements are aligned to a team goal with annual sales targets, as well as to your participation in knowledge exchange with peers and the wider community.</span></p></li></ul><p></p><p><b><b>We&#39;re excited about you if you have:</b></b></p><ul><li><p><span>A passion for using technology to make a difference in people and organizations. We\\u2019ll supply some amazing tools to help you with this and you\\u2019ll provide the connection to use cases, which make it real for your customers</span></p></li><li><p><span>A minimum of 5 years experience in a customer-facing role, ideally in a pre-sales context</span></p></li><li><p><span>The ability to create and give technical presentations and demonstrations</span></p></li><li><p><span>Experience with some of the following technologies:</span></p><ul><li><p><span>Big Data, Data Warehousing, or Relational Databases with In-depth knowledge SQL \\u2013 query optimization and data model design.</span></p></li><li><p><span>One or more of the three major cloud service providers (AWS, Azure or GCP). Formal certification is not required but would be a great thing to have</span></p></li><li><p><span>Data Engineering, Data Science or Machine Learning&amp;AI</span></p></li><li><p><span>Knowledge of distributed systems, ETL and ETL workflows.</span></p></li><li><p><span>Operations, Security and Data Governance within the enterprise</span></p></li></ul></li><li><p><span>Unix or Linux</span></p></li><li><p><span>Experience in Development experience with Java / OO programming or Python.\\u00a0</span></p></li><li><p><span>Experience in using tools like Docker and Kubernetes would be a great thing to have.</span></p></li><li><p><span>Experience gathering and understanding customer business requirements</span></p></li><li><p><span>Excellent written and verbal communication</span></p></li><li><p><span>Problem-solving skills</span></p></li><li><p><span>A willingness to learn, a curiosity to discover, and a drive to make your customers successful</span></p></li><li><p><span>Fluent in French and English.</span></p></li></ul><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-Remote</p><p>#LI-ND3</p>","260988":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Finance &amp; Corp. Services<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Entry level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><b><u>Accounts Receivable Specialist</u></b></p><p></p><p><i>Cloudera is looking for an experienced and highly motivated individual to join the Accounts Receivable team.</i></p><p><i>Job location: Cork, Ireland (Hybrid)</i></p><p></p><p><i>Reporting line: Team Lead Accounts Receivable</i></p><p></p><p><span>This role will include responsibility for collections and invoicing and month end tasks. Main focus will be on following up regularly as needed to secure timely payment, while building relationships with customers and internal stakeholders assigned to the account, cross functionally. The role also includes completion of other tasks which the Accounts Receivable team is responsible for, including billing, customer data management and month end tasks.</span></p><p></p><p><b><u>As an Accounts Receivable Specialist you will:</u></b></p><p></p><ul><li><p><span>Reconciliation of customer accounts and provision of Statements of Account.</span></p></li><li><p><span>Review the AR subledger daily, issue payment reminders both ahead of invoice due date and as needed if invoice becomes overdue.</span></p></li><li><p><span>Contact customers via telephone and email to resolve any billing related questions, requests or issues. Follow a suitable approach depending on the nature of the query or issue, and the type of account / region.\\u00a0</span></p></li><li><p><span>Work cross-functionally with Order Management, Sales Ops, and Sales to resolve queries or issues in relation to open invoices.</span></p></li><li><p><span>Assist management with specific processes in place for severely aged debt, including review of Tesorio notes and liaising with internal teams on agreed actions.\\u00a0</span></p></li><li><p><span>Generate invoices in Netsuite and submit to customers through various means.</span></p></li><li><p><span>Review customer contracts and vendor agreements to align AR practices with negotiated terms.</span></p></li><li><p><span>Manage and fulfill specific customer portal requirements where necessary.</span></p></li><li><p><span>Complete customer portal sign up request in co-ordination with the customer forms team.</span></p></li><li><p><span>Data Management - review and approve new customer accounts in NetSuite.</span></p></li><li><p><span>Follow policy and procedures for approval, creation and application of credit notes. Work with the Treasury team on any agreed refunds.\\u00a0</span></p></li><li><p><span>Participate in the month-end close process.\\u00a0</span></p></li><li><p><span>Support audit tasks as needed.</span></p></li><li><p><span>Help with ad-hoc tasks as determined by the Team Lead / Sr. Manager.</span></p></li><li><p><span>Ensure all tasks are performed according to Cloudera policies and guidelines.</span></p></li></ul><p></p><p></p><p><b><u>We&#39;re excited about you if you have:</u></b></p><ul><li><p><span>Invoicing and credit memo / returns experience.</span></p></li><li><p><span>Familiar with basic contractual documents and contractual provisions related to billing and payment rights.</span></p></li><li><p><span>Excellent communication skills to liaise with external and internal customers; comfortable reaching out and communicating in person, over the phone and web conference.</span></p></li><li><p><span>Proactive attitude, both in relation to the role and process / system improvements.</span></p></li><li><p><span>Problem-solving skills.</span></p></li><li><p><span>Foreign language is a plus.</span></p></li><li><p><span>Ability to prioritize and multitask.</span></p></li><li><p><span>Minimum 2-3 years accounts receivable billing and collections experience.</span></p></li><li><p><span>Bachelor&#39;s degree in a related field or equivalent experience</span></p></li><li><p><span>NetSuite experience is an advantage.</span></p></li><li><p><span>Proficient with Excel / Google Sheets.\\u00a0</span></p></li></ul><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-ND3</p><p>#LI-Hybrid</p>","260867":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Product Mgmt.<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>Cloudera is seeking an experienced and visionary Senior Product Manager for Anywhere Cloud (AWC) to own platform &amp; AI features\\u00a0 across hybrid and multi-cloud environments. This Role will be responsible for ensuring the Anywhere Cloud Platform is well integrated into the modern AI ecosystem. This role is within the fast paced Anywhere Cloud team driving new innovation.<br />\\u00a0</p><p><b>As a Senior Product Manager you will\\u2026</b></p><ul><li><p><span>Define and drive the product roadmap for platform &amp; AI features on the Anywhere Cloud platform.\\u00a0</span></p></li><li><p><span>Translate complex customer needs and market opportunities into detailed product requirements, user stories, and acceptance criteria for engineering teams.</span></p></li><li><p><span>Collaborate closely with engineering, design, and other cross-functional teams to ensure successful product development, delivery and customer satisfaction.</span></p></li><li><p><span>Lead the entire product lifecycle from concept to launch and post-launch optimization, ensuring high-quality, scalable, and secure product offerings.</span></p></li><li><p><span>Champion product adoption and customer success through strong advocacy, thought leadership, and engagement with key customers and partners.</span></p></li><li><p><span>Monitor and analyze product performance metrics, identifying areas for improvement and driving continuous product enhancements.</span></p></li><li><p><span>Stay abreast of industry trends, technologies, and best practices security and data.</span></p></li></ul><p></p><p><b>We are excited if you have\\u2026</b></p><ul><li><p><span>Bachelor&#39;s degree in Computer Science, Engineering, or a related technical field. MBA or advanced degree is a plus.</span></p></li><li><p><span>5&#43; years of experience in product management, with a strong focus on security and data platforms.</span></p></li><li><p><span>Proven track record of successfully defining, launching, and managing enterprise-grade software products in a fast-paced environment.</span></p></li><li><p><span>Deep understanding of security,\\u00a0</span></p></li><li><p><span>Experience with cloud platforms (AWS, Azure, GCP) and hybrid cloud environments.</span></p></li><li><p><span>Excellent communication, presentation, and interpersonal skills, with the ability to articulate complex technical concepts to diverse audiences.</span></p></li><li><p><span>Demonstrated ability to work cross-functional and influence stakeholders at all levels.</span></p></li><li><p><span>Strategic thinker with a strong business acumen and a customer-centric approach.</span></p></li><li><p><span>Experience with Agile development methodologies.</span></p></li></ul><p></p><p><b>You may also have\\u2026</b></p><ul><li><p><span>Familiarity with open-source security, compute &amp; data technologies such as Kubernetes, SSL/TLS, OAuth/OIDC, SAML, AI inference, LLM routing, Agent skills/tools, etc.</span></p></li><li><p><span>Experience with regulated industries and data compliance (e.g., GDPR, CCPA, \\u00a0FedRAMP.).</span></p></li></ul><p></p><p>This role is not eligible for immigration sponsorship.</p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-CP1</p><p>#LI-HYBRID</p>","260924":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Professional Services<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>The <b>Leading Emergent Engineering Taskforce</b> (LEET) is a new, agile operational unit designed to execute on Cloudera\\u2019s most critical strategic initiatives. Operating as an &#34;empowered pod,&#34; we bridge the gap between abstract requirements and real-world execution, tackling both complex customer integrations and high-impact internal engineering projects. We move with the velocity of a startup while leveraging the massive scale of the Cloudera Data Platform.</p><p>As a Staff Software Engineer, you are the primary Product Builder of the taskforce. You own the end-to-end implementation of features\\u2014from the database schema to the user interface.<br />\\u00a0</p><p>We are looking for an engineer with strong product instincts who can move fast without breaking things. You will collaborate closely with the Applied Engineers to transform abstract requirements into tangible, interactive applications for both internal developer platforms and external B2B initiatives. You will architect the user experience of our data tools, ensuring that the complexity of petabyte-scale data is presented with clarity and precision.<br />\\u00a0</p><p><b>As a Staff Software Engineer you will:</b></p><ul><li><b>End-to-End Execution: </b>Independently determine the best implementation approach for assigned features. You will write high-performance Java code for the API layer, and should feel comfortable navigating between the persistence and front-end aspects of a solution, ensuring seamless integration.</li><li><b>Rapid Prototyping: </b>Transform whiteboard sketches and mock-ups into working software with high velocity. You enable the taskforce to put working code in front of customers early, validating assumptions through interaction rather than documentation.</li><li><b>API Design: </b>Design and implement robust APIs that decouple the frontend from our heavy backend systems, ensuring that user interfaces remain responsive even when the underlying clusters are under load.</li><li><b>Product Ownership:</b> Think beyond the code. You will prioritise &#34;Time to Value&#34; and user experience, pushing back on over-engineering when a simpler solution delivers the customer outcome faster.<br />\\u00a0</li></ul><p><b>We\\u2019re excited about you if you have:</b></p><ul><li><b>Experience:</b> 6&#43; years of multi-faceted software development experience.</li><li><b>Backend Competence:</b> Strong working knowledge of <b>Java</b> for backend service development. You understand how to write efficient API endpoints and interact with databases.</li><li><b>Good grasp of Unix-like operating systems:</b> Linux and MacOS are especially valuable.</li><li><b>Kubernetes and Containerisation:</b> You know how to containerise services, and how to manage them.</li><li><b>Data Fluency:</b> You are comfortable writing SQL and interacting with data platforms. You understand that a pretty UI is useless if the underlying query takes 30 seconds to run.<br />\\u00a0</li></ul><p><b>You may also have:</b></p><ul><li>Visual Design Sensibility: While you are an engineer, you possess a solid grasp of UI/UX principles. You can build interfaces that are intuitive and accessible without needing a designer to specify every pixel.</li><li>Experience with advanced data visualisation techniques for rendering large datasets.</li><li>Background in building internal tools, developer platforms, or B2B SaaS applications.</li><li>Other languages welcome: Rust, Go, Python.</li></ul><p></p><p>This role is not eligible for immigration sponsorship.</p><p>This is a hybrid role, requiring 2 days per week in our Cork office.</p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-RB1</p><p>#LI-Hybrid</p>","260335":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Corp. Strategy<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>As a <b>Business Value Manager</b>, you operate at the intersection of business value, AI platform architectures, and deal strategy. You partner with account teams and customer executives to translate complex data and AI capabilities into quantified economic outcomes, shaping investment decisions, influencing deal structures, and enabling enterprises to transition toward AI-native operating models. <b>This is an individual contributor role. </b></p><p></p><p><b>As the Business Value Manager you will:\\u00a0</b></p><ul><li><p>Drive ARR growth by embedding quantified, forward-looking value narratives into deal strategy, linking AI platform architectures and emerging AI operating models to revenue uplift, cost optimization, and risk reduction.</p></li><li><p>Engage C-suite stakeholders to shape enterprise AI and data strategies, positioning Cloudera within broader shifts toward platform consolidation, hybrid architectures, and AI-enabled business models.</p></li><li><p>Build and present CFO-grade business cases (TCO, ROI, NPV, IRR), incorporating evolving cost dynamics such as inference workloads, utilization patterns, and long-term AI operating economics.</p></li><li><p>Lead value discovery engagements to map current-state environments to future-state AI-native architectures, with explicit quantification of value drivers, investment trade-offs, and execution pathways.</p></li><li><p>Support complex, multi-year deal cycles through commercial structuring, scenario modeling, and competitive positioning against cloud-native and emerging AI platform alternatives.</p></li><li><p>Align solution design with commercial objectives by partnering with Sales, Solutions Engineering, and Product, ensuring architectures are optimized for performance, scalability, and durable economic efficiency in AI-driven environments.</p></li><li><p>Represent Cloudera in executive forums, articulating perspectives on enterprise AI economics, architectural trade-offs, and the long-term implications of AI adoption on cost structures and operating models.</p></li><li><p>Leverage AI tools and automation, including LLMs and agentic workflows, to scale analysis, accelerate insight generation, and industrialize repeatable assets such as TCO models and scenario simulators.</p></li></ul><p></p><p><b>We\\u2019re excited about you if you have: (Minimum Qualifications):</b></p><ul><li><p>5\\u20137&#43; years in strategy consulting, value engineering, or equivalent customer-facing roles</p></li><li><p>Strong commercial and financial acumen, including advanced financial modeling (DCF, NPV, IRR) and the ability to link technology decisions to P&amp;L, balance sheet, and cash flow outcomes</p></li><li><p>Demonstrated ability to influence enterprise deal cycles, including shaping deal strategy, positioning, and commercial outcomes</p></li><li><p>Solid understanding of modern data platforms, distributed systems, and AI/ML workloads, including data pipelines, model deployment, and infrastructure trade-offs</p></li><li><p>Ability to quantitatively reason about evolving cost drivers in AI and data environments, including compute, storage, and workload patterns</p></li><li><p>Hands-on experience using AI tools (e.g., LLMs, automation frameworks) to support analysis, modeling, and content generation</p></li><li><p>Strong executive presence with the ability to engage and influence CIO, CFO, CDO, and senior business stakeholders</p></li><li><p>Proven experience working closely with Sales teams in complex, high-value enterprise deals</p></li><li><p>Excellent communication skills, with the ability to distill complex technical and financial concepts into clear, actionable insights</p></li><li><p>High ownership mindset, with the ability to operate independently in ambiguous, high-growth environments</p></li></ul><p></p><p><b>You may also have: (Preferred Qualifications):\\u00a0</b></p><ul><li><p>Post-MBA experience, particularly within a top-tier management consulting firm or equivalent environment</p></li><li><p>Experience designing or deploying enterprise AI or data platform architectures in production environments</p></li><li><p>Deep expertise in one or more industries such as Financial Services, Manufacturing, Consumer Goods, or Telecommunication</p></li><li><p>Experience building scalable value engineering assets such as TCO calculators, benchmarking models, or scenario simulators</p></li><li><p>Familiarity with hybrid and on-prem AI deployments, including cost and performance trade-offs versus public cloud</p></li></ul><p><span>\\u00a0</span></p><p><b><span>This role is not eligible for immigration sponsorship</span></b></p><p></p><p><b><span>The anticipated annual base salary range for this position is: </span></b></p><p><span>Illinois: $116K - 150K </span></p><p></p><p><span>Individual compensation within the published range is determined by the candidate&#39;s skills, experience, qualifications, and primary work location. In addition to base pay, sales roles are eligible for Cloudera&#39;s commission plan, while non-sales roles are eligible for the corporate incentive plan. All employees receive a comprehensive benefits package.\\u00a0</span></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-MH2</p><p>#LI-remote</p>","251484":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>The Data Platform Pillar is the bedrock of Cloudera\\u2019s technology, where we design and build the core components that let our customers store, manage, and process data with unmatched scalability, security, and performance. </span><br /><br /><span>We are looking for passionate Software Engineers to join our Hungary-based team, focusing on the development of Cloudera&#39;s Streaming Analytics products, including Apache Flink, SQL Stream Builder, and related stream processing components. Flink is a general-purpose distributed data processing technology known for its low latency, high throughput, massive scalability, and high reliability. SQL Stream Builder offers customers a powerful, SQL-oriented interface for developing and deploying large-scale stream processing jobs on Flink. As a Software Engineer, you will collaborate with engineers and stakeholders across Hungary, the United States, and other global locations.</span></p><p></p><p><b><b>As a Staff Software Engineer you will:</b></b></p><ul><li><p><span>Develop deep proficiency in Apache Flink and the Cloudera products built on this technology.</span></p></li><li><p><span>Informally manage technical projects, priorities, and resources, and plan work for other team members to ensure effective project delivery.</span></p></li><li><p><span>Design, implement, test and release new features and enhancements for the Cloudera Streaming Analytics product suite, supporting both on-premise and cloud deployments.</span></p></li><li><p><span>Contribute to a cross-functional software development team, covering all aspects of software product delivery to ensure high-quality, secure, and maintainable software.</span></p></li><li><p><span>Collaborate with product management, engineering, support, UX, and documentation teams to deliver projects.</span></p></li><li><p><span>Provide support to our field team and customers, facilitating product adoption, smooth implementation and troubleshooting of use cases.</span></p></li></ul><p></p><p><b><b>We\\u2019re excited about you if you have:\\u00a0</b></b></p><ul><li><p><span>Bachelor\\u2019s degree in Computer Science or equivalent, and 6&#43; years of experience; OR Master\\u2019s degree and 4-6 years of experience; OR PhD and 2-4 years of experience</span></p></li><li><p><span>Experience with Apache Flink, Spark and/or Kafka</span></p></li><li><p><span>Proven experience in building scalable, robust distributed software systems.</span></p></li><li><p><span>Strong Java skills and proficiency across the Java ecosystem.</span></p></li><li><p><span>Strong understanding of software design and architecture principles.</span></p></li><li><p><span>Experience with delivery pipeline tools, CI/CD solutions, and automated testing.</span></p></li><li><p><span>Self-driven and highly motivated, with a strong sense of ownership and craftsmanship.</span></p></li><li><p><span>Strong written and verbal English and communication skills.</span></p></li></ul><p></p><p><b><b>You may also have:</b></b></p><ul><li><p><span>Experience with Cloud technologies (AWS, Azure, GCP)</span></p></li><li><p>Demonstrated history of leading a group of engineers to deliver on a complex project plan</p></li><li><p><span>Experience with containerization orchestration technologies: Kubernetes, Docker</span></p></li><li><p><span>Experience with Python and/or Javascript</span></p></li></ul><p></p><p><b>This role is not eligible for immigration sponsorship or relocation.</b><br />\\u00a0</p><p><b><b>Why this role matters: </b></b><br /><br /><b><span>You will tackle complex distributed systems challenges, crafting the foundational software for the control and data planes that powers CDP and keeps it running at massive scale. Working at the forefront of hybrid and multi-cloud technology, you will empower data scientists, engineers, and analysts with the tools and infrastructure they need for advanced analytics and modeling.</span></b></p><p></p><p><b><span>\\u00a0Collaboration is key, you will work alongside brilliant minds across product, data science, and engineering to drive innovation, standardize best practices, and shape the future of enterprise AI and data platforms. This is your chance to build the future of data and see your work make a global impact.</span></b></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><div><div><div><div><div><div><div><div><div><p>#LI-HYBRID</p><h2>#LI-AC1<br />\\u00a0</h2></div></div></div></div></div></div></div></div></div>","260879":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><div><div>Job Description</div></div><div><div><div><div><div><div><div><div><div><p>Cloudera Sales empowers the world&#39;s largest enterprises across every industry to use data to solve some of the most complex challenges that<a href=\\"https://www.cloudera.com/about/customers/regions-bank.html\\" target=\\"_blank\\"> <u>impact businesses,</u></a><a href=\\"https://www.youtube.com/watch?v&#61;DroVKhAUvss\\" target=\\"_blank\\"> <u>communities</u></a> and<a href=\\"https://www.cloudera.com/about/customers/discovery-health.html\\" target=\\"_blank\\"> <u>lives</u></a>. We have a platform that delivers incredible Data and Analytics technology across On- Prem, Public Cloud, and in a Hybrid model. We\\u2019re at an exciting point in our transformation as we successfully execute on our strategy.\\u00a0</p><p></p><p>As part of the Sales team, you will have autonomy to engage with leading enterprise customers, prospects and partners. You will help foster long term, sustainable, and mutually rewarding relationships. This is your opportunity to be part of something intellectually stimulating, fast paced, transform a customer\\u2019s business, and earn financial rewards along the way.\\u00a0</p><p></p><p>As the Key Account Director you will:</p><ul><li><p>Own the overall account relationship, in order to drive net-new revenue in the account and ensure customer success\\u00a0</p></li><li><p>Build consensus and develop relationships at multiple levels: executive sponsors, decision-makers, influencers</p></li><li><p>Align Cloudera domain products and service experts to key customer stakeholders, while maintaining account oversight</p></li><li><p>Lead large scale sales cycles and transactions</p></li><li><p>Meet regularly with the account to generate new Cloudera demand and net-new pipeline\\u00a0</p></li><li><p>Forecast the business, lead the internal team, and communicate key updates\\u00a0</p></li><li><p>Exceed quarterly and annual goals for new software subscription and cloud consumption</p></li></ul><p></p><p>We\\u2019re excited about you if you have:</p><ul><li><p>Minimum 10&#43; years of exceeding enterprise software sales targets</p></li><li><p>Minimum 5&#43; years of experience selling to financial services vertical, in particular, with accounts such as American Express, MasterCard, Visa, Discover, Capital One, London Stock Exchange.\\u00a0</p></li><li><p>AI proficient, understanding of the impact AI will have on businesses\\u00a0</p></li><li><p>Data management, Data Analytics, Data Engineering, Data Warehousing experience\\u00a0</p></li><li><p>Containers, Kubernetes, data infrastructure, public cloud infrastructure technology experience</p></li><li><p>Four year degree (Bachelor&#39;s) from accredited university required</p></li><li><p>Ability to travel\\u00a0</p></li></ul><p></p><p>\\u200b<b>This role is not eligible for immigration sponsorship </b></p></div></div></div></div></div></div></div></div></div><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-remote</p><p>#KB-1</p>","260821":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Entry level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Cloudera is seeking an energetic, innovative BDR with a flair for developing new business and identifying and selling to customer needs. You&#39;ll join our relationship-driven team and take charge of developing detailed sales/marketing plans and maximizing sales opportunities to drive results and inspire productivity and teamwork. You will rely on your experience and good judgment to proactively build and exponentially grow accounts and drive year-over-year growth in line with the revenue goals.\\u00a0</span></p><p><br /><b><b>As a Business Development Representative you will:</b></b></p><ul><li><p><span>Develop and execute a strategic and comprehensive business plan for your territory, including identifying core customers, mapping the benefits of Cloudera solutions to the business requirements.\\u00a0</span></p></li><li><p><span>Strive to understand the customer\\u2019s organizational structure and work to achieve alignment.\\u00a0</span></p></li><li><p><span>Take full responsibility for accurate forecasting, regular quarterly revenue delivery, and facilitation of sales enablement and regulate the implementation of agreed account and business plans.\\u00a0</span></p></li><li><p><span>Furthermore, you\\u2019ll coach partners, accessing resources within Cloudera to support them on specific opportunities, with the goal of building sufficient capacity to meet customers\\u2019 demand for Cloudera\\u2019s-related services and skills.\\u00a0</span></p></li><li><p><span>Other responsibilities include but are not limited to the following:\\u00a0</span></p><ul><li><p><span>Develop detailed sales/marketing plans and sales forecasts</span></p></li><li><p><span>Manage time and work flow and create effective call plans</span></p></li><li><p><span>Monitor competition and respond immediately and appropriately</span></p></li><li><p><span>Build an exhaustive network and generate prolific referrals</span></p></li></ul></li></ul><p><b><b>We\\u2019re excited about you if you have:</b></b></p><ul><li><p><span>3-6\\u00a0years of successful Business Development\\u00a0</span></p></li><li><p><span>You are an aggressive self-starter who compels others to get on board.\\u00a0</span></p></li><li><p><span>Innovative vision and foresight to anticipate and create new opportunities</span></p></li><li><p><span>You communicate an inspired and optimistic vision and win over colleagues, customers and business partners alike with your articulate negotiating skills.\\u00a0</span></p></li><li><p><span>You are known for your strong hunting capabilities and strategic operating skills, and you\\u2019re constantly on the lookout for prospective deals and new business opportunities.\\u00a0</span></p></li><li><p><span>You thrive in an independent mode but also value collaboration.\\u00a0</span></p></li><li><p><span>In addition, you have deep understanding of the business and technical contexts in which key accounts are situated</span></p></li><li><p><span>Four year degree (Bachelor&#39;s) from accredited university required</span></p></li><li><p><span>Ability to travel domestically and internationally\\u00a0</span></p></li><li><p><span>This role is not eligible for immigration sponsorship </span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-KB1</p><p>#LI-Hybrid</p>","260915":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span style=\\"font-size:14px\\">As a </span><b><span style=\\"font-size:14px\\">Staff DevOps Platform Engineer</span></b><span style=\\"font-size:14px\\"><b> </b>at Cloudera, you will play a pivotal role in advancing our Kubernetes-based hybrid cloud platform offerings.</span></p><p><span>In this role, you will act as a </span>Platform Generalist<span> working across functions such as Site Reliability (SRE), Release Engineering, and Production Engineering. You will work closely with our product and backend teams to define platform standards for the product and to continually improve the experience for our developers and customers.</span></p><p>This role is not eligible for Immigration Sponsorship or Relocation.</p><p></p><p>As a Staff DevOps Platform Engineer, you will:</p><ul><li><p><span>Improve reliability and scalability of the platform</span></p></li><li><p><span>Build systems to manage platform infrastructure and applications</span></p></li><li><p><span>Strong focus on declarative Infrastructure-as-Code (IAC) practices</span></p></li><li><p><span>Contribute to CI/CD processes, testing frameworks, and deployment processes</span></p></li><li><p><span>Collaborate with cross-functional teams to ensure smooth platform integration</span></p></li><li><p><span>Optimize existing systems &amp; eliminate toil through simplification and automation</span></p></li><li><p><span>Monitor availability, latency and overall service health</span></p></li><li><p><span>Practice sustainable incident response and blameless postmortems</span></p></li><li><p><span>Participate in an on-call rotation</span></p></li></ul><p></p><p><b>We\\u2019re excited about you if you have:</b></p><ul><li><p><span>Have 8&#43; years industry experience in SRE, DevOps or related role</span></p></li><li><p><span>Enjoy collaborating and are a strong communicator</span></p></li><li><p><span>Strong Linux and systems administration experience</span></p></li><li><p><span>Experience with Cloud architectures on AWS, GCP, Azure and/or OpenStack</span></p></li><li><p><span>Experience with microservices architectures on Kubernetes</span></p></li><li><p><span>Experience with observability, logging and monitoring tools</span></p></li><li><p><span>Experience with Terraform/OpenTofu and related technologies</span></p></li></ul><p></p><p><b>You may also have:</b></p><ul><li><p><span>Experience with CI/CD tools, such as Flux CD and Argo CD</span></p></li><li><p><span>Experience with GitOps and Git-based automation</span></p></li><li><p><span>Programming experience in Python, Go or similar languages</span></p></li><li><p><span>Experience with compliance programs such as SOC, FedRAMP, HITRUST CSF</span></p></li><li><p><span>Experience with database systems, including Postgres and MySQL</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-HYBRID</p><p>#LI-AC1</p>","260616":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>Solutions Engineer</p><p></p><p>Cloudera is seeking a <b>Solutions Engineer </b>to come join our team. You will utilize your strong technical, business competencies and customer service skills to provide the highest level of business and technical consultation to sales teams, prospects and customers to support sales goals.</p><p></p><p><b><b>As a Solutions Engineer you will:</b></b></p><ul><li><p>Deep understanding of AI concepts and best practices</p></li><li><p>Provide advice in customer use cases discovery and requirements workshops</p></li><li><p>Ability to troubleshoot data science workloads</p></li><li><p>Actively participate within the Cloudera community</p></li><li><p>Create and deliver customer-centric solution designs</p></li><li><p>Present roadmap, vision, proposed architectures and business outcomes to technical teams</p></li><li><p>Responsible for defining technical selling approach for accounts</p></li><li><p>Regularly participate in account penetration / success strategy planning, working with sales counterparts and solutions engineering management</p></li><li><p>Understand the core differentiators across the competitive landscape</p></li><li><p>Understand the technology ecosystem</p></li><li><p>Transform customer feedback into actionable product roadmap items</p></li><li><p>A share of evangelism activities (blogs, meetups, industry events)\\u00a0\\u00a0</p></li><li><p>Mentor associates, participate in creation and maintenance of enablement materials across the team</p></li><li><p>Participate in contribution to internal and external knowledge repositories</p></li></ul><p></p><p><b><b>We\\u2019re excited about you if you have:</b></b></p><ul><li><p>Hands-on experience with the full lifecycle of AI models - from development and testing to production deployment, monitoring, and retraining/versioning</p></li><li><p>You have strong experience with AI ecosystems (Agentic AI, Ethical AI solutions, Generative AI solutions and AI Development Tools like Cursor, CoPilot and Claude).</p></li><li><p>AI and/or Data Science use-case development</p></li><li><p>You have an interest in Data Science and understand the difference between Data Engineering and Applied Science</p></li><li><p>You have experience as a Solutions Engineer / Pre-Sales Solutions Architecture as a field of practice (an ability to listen to customer requirements, whiteboard and propose solution architectures, and be hands-on with the tech) to design, build, and demonstrate real business value</p></li><li><p>3-5 &#43; years of professional work experience in a similar position</p></li><li><p>Enterprise Software and Big Data experience</p></li><li><p>Demonstrated understanding of the challenges in operations, Security and Data Governance within the enterprise</p></li><li><p>Bachelor\\u2019s Degree in a Technical Field</p></li><li><p>You are on good terms with Infrastructure (Hardware, Storage, Network), Java/.NET, and SQL.</p></li><li><p>You have strong Linux skills</p></li><li><p>Demonstrated Strong Written and verbal Communication skills</p></li><li><p>Demonstrated problem solving and analytical skills</p></li></ul><p></p><p><b><b>You may also have:</b></b></p><ul><li><p>Demonstrated knowledge of Big Data Ecosystem (HDFS &amp; YARN, Spark, Impala, KUDU, Solr etc ), can talk to the benefits of a centralized architecture for both data management and data access</p></li><li><p>Streaming experience (Nifi, Kafka, Flink, Spark, etc.)</p></li><li><p>NoSQL experience (HBase, Cassandra, MongoDB, etc.)</p></li><li><p>EDW experience \\u2013 Teradata, Netezza, GreenPlum, Exadata</p></li><li><p>Data Science and ML experience \\u2013 (R, Python, Deep Learning Frameworks etc.)</p></li><li><p>Integration Products experience (Talend, DataStage, Informatica BDM, Qlik, Tableau, Zoomdata, IBM, Oracle, etc.)</p></li><li><p>You thrive in a changing environment</p></li><li><p>Four year degree (Bachelor&#39;s) from accredited university required</p></li><li><p>Ability to travel domestically and internationally</p></li></ul><p></p><p><b>This role is not eligible for immigration sponsorship</b></p><p></p><p>The anticipated annual base salary range for this position is:</p><p><span>Massachusetts: $150,000 - $185,000</span></p><p><span>New York: $150,000 - $185,000</span></p><p><span>Connecticut</span>: <span>$150,000 - $185,000</span></p><p></p><p><span>Individual compensation within the published range is determined by the candidate&#39;s skills, experience, qualifications, and primary work location. In addition to base pay, sales roles are eligible for Cloudera&#39;s commission plan, while non-sales roles are eligible for the corporate incentive plan. All employees receive a comprehensive benefits package. </span></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-MH2</p><p>#LI-Remote</p>","251502":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Professional Services<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>The </span>Leading Emergent Engineering Taskforce (LEET)<span> is a new, agile operational unit designed to execute on Cloudera\\u2019s most critical strategic initiatives. Operating as an &#34;empowered pod,&#34; we bridge the gap between abstract requirements and real-world execution, tackling both complex customer integrations and high-impact internal engineering projects. We move with the velocity of a startup while leveraging the massive scale of the Cloudera Data Platform.</span></p><p></p><p><span>As the </span>Staff Software Engineer<span>, you are the </span>Guardian of Resilience<span>. You ensure the system maintains stability under massive production loads.</span></p><p></p><p><span>We are seeking a principled systems engineer dedicated to transforming rapid prototypes into robust, production-grade services. You will apply advanced engineering concepts to ensure our internal and external strategic initiatives survive contact with reality, bridging the gap between legacy Big Data architectures and modern Cloud-Native reliability. You will use Java as a primary vehicle, but you will apply distributed systems principles that transcend any single language or framework.</span></p><p></p><h2>As a Staff Software Engineer you will:</h2><ul><li><p>Engineering for Scale<span>: Design and implement high-performance backend services that can withstand massive throughput. You will focus on the fundamental constraints of the system\\u2014latency, memory models, and I/O efficiency\\u2014to ensure our solutions scale linearly.</span></p></li><li><p>Distributed State Management<span>: Own the challenge of data integrity. You will solve difficult problems regarding distributed consistency, leader election, and state persistence, choosing the right storage patterns based on first principles rather than default configurations.</span></p></li><li><p>Resilience &amp; Observability<span>: Build systems that fail gracefully. You will implement advanced patterns for circuit breaking, backpressure, and resource isolation to prevent system overload and cascading failures.</span></p></li><li><p>Cloud-Native Architecture<span>: Apply the principles of immutable infrastructure and container orchestration. You will ensure that our stateful applications can run reliably in dynamic environments (like Kubernetes), handling the complexities of networking and persistent storage.</span></p></li><li><p>Technical Rigour<span>: Solve &#34;unusually complex&#34; problems where standard documentation does not exist. You will analyse JVM internals, garbage collection pauses, and thread contention to optimise the critical path of our data pipelines.</span></p></li></ul><p></p><h2>We\\u2019re excited about you if you have:</h2><ul><li><p>Experience<span>: 8&#43; years of backend engineering experience with a focus on data-intensive applications or distributed systems.</span></p></li><li><p>Ability to produce high-performance, high-quality code in at least one of the following languages: Java, Scala, or Go; Python experience is a plus.</p></li><li><p>Systems Thinking<span>: A strong grasp of distributed systems theory (CAP theorem, consensus algorithms, eventual consistency). You understand the trade-offs between availability and consistency in a partitioned network.</span></p></li><li><p>Container Fluency<span>: Strong understanding of modern orchestration principles (e.g., Kubernetes). You know how to design applications that survive pod evictions and network partitions.</span></p></li><li><p>Versatility<span>: While Java is our core, you possess a &#34;polyglot curiosity.&#34; You are comfortable reading and debugging code in other languages when the problem demands it.</span></p></li><li><p>Autonomy:<span> Ability to work within general parameters and without appreciable direction, determining courses of action necessary to obtain desired results.</span></p></li></ul><p></p><h2>You may also have:</h2><ul><li><p><span>Experience contributing to or modifying open-source data engines (e.g., Apache Hadoop, Spark, or similar).</span></p></li><li><p><span>Deep understanding of database internals (how indexes, planners, and storage engines actually work).</span></p></li><li><p><span>Experience refactoring monolithic legacy systems into microservices or serverless architectures.</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-RC1</p>","261026":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales Operations<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>As a Senior Sales Operations Analyst, you will play a critical, dual-functioning role encompassing both <b>commercial and operational responsibilities</b> across all sales at Cloudera. The ideal candidate will be self-motivated, highly detailed, and thorough, possessing the ability to ask the right questions and propose strong commercial and operational advice to the field.</p><p></p><p>This is an excellent opportunity to gain valuable experience on the operational backbone of a fast-growing sales team. This is a dynamic role that directly impacts the company&#39;s ability to achieve Sales and Revenue objectives. Your demonstrated ability to execute in this role will open pathways to owning a greater level of responsibility in Sales Operations, Deal Desk, and related teams.</p><p></p><p><b>As a Senior Sales Operations Analyst, you will:</b></p><h3></h3><ul><li><p><b>Commercial Structuring &amp; Quote Approval:</b> Work alongside Deal Desk Managers in managing the commercial aspects of Stage 1 to Stage 6 customers. Review, advise on, and approve quotes, efficiently handling quote volumes for your assigned regions.</p></li><li><p><b>Strategic Field Advisory:</b> Partner closely with the sales teams to ask the right questions, troubleshoot issues, and propose strong commercial and operational advice to ensure deals are structured effectively and compliantly.</p></li><li><p><b>Order Management &amp; Processing:</b> Process orders and sales operations tickets in the CRM system. Maintain a superior level of accuracy, consistency, and work quality, particularly involving order management and execution.</p></li><li><p><b>Deal Calculations:</b> Support the quoting and deal calculations process based on established policies and procedures. Perform complex deal calculations across new business, expansions, and account run rates.</p></li><li><p><b>Cross-Functional Support:</b> Communicate with sales teams to clear up missing information or inconsistencies on orders; provide continuous cross-functional operational support specific to order management.</p></li><li><p><b>Training &amp; Enablement:</b> Deliver effective communication and training to sales, renewals, consulting, and training teams on all quote-to-cash processes and policies.</p></li><li><p><b>Customer Service:</b> Respond to sales inquiries and/or questions relating to orders, order fulfillment, confirmations, and general customer service questions.</p></li><li><p><b>Systems Expertise &amp; Troubleshooting:</b> Build proficient expertise in the CRM system and related tools, adding value, scale, and speed to the selling process in the creation of quotes and orders. Troubleshoot issues and recommend fixes to processes and workflows.</p></li><li><p><b>Quoting Tool Point of Contact:</b> Act as the primary liaison for quote creation issues and collaborate with the Field Systems team for technical issues and enhancements.</p></li><li><p><b>New Product Introductions:</b> Assist Sales Operations with rolling out new products, working collaboratively with Product Marketing, Finance, and other teams on new pricing and packaging.</p></li><li><p><b>Data Integrity:</b> Manage data in Salesforce.com and related tools, including auditing and resolving data integrity issues.</p></li><li><p><b>Reporting:</b> Develop reports and dashboards in the CRM in support of sales visibility.</p></li><li><p><b>Policy Implementation:</b> Work closely with the Finance and Legal teams to execute, build, implement, and apply required policies and processes.</p></li><li><p><b>Process Improvement:</b> Actively contribute to the continuing improvement and refinement of Sales Operations support, Deal Desk alignment, and quote-to-cash processes alongside local and global operations teams.</p></li></ul><p></p><p><b>We\\u2019re excited about you if you have:</b></p><ul><li><p><b>Education:</b> BA/BS or equivalent degree required.</p></li><li><p><b>Experience:</b> Minimum 7 years\\u2019 operational and/or commercial experience. Experience in dynamic software and subscription companies is highly desired.</p></li><li><p><b>Language Skills:</b> Language proficiency in <b>Korean</b> and/or <b>Japanese</b> is a distinct advantage to collaborate with the regional teams.</p></li><li><p><b>Systems Knowledge:</b> Salesforce.com and CPQ experience preferred, or equivalent robust systems experience.</p></li><li><p><b>Commercial Acumen:</b> Proven ability to partner with sales, ask insightful questions, and deliver detailed, strong commercial and operational recommendations.</p></li><li><p><b>Work Ethic:</b> Self-motivated, able to work independently as well as contribute strongly to a team. High level of accountability; willing to take ownership and solve problems.</p></li><li><p><b>Agility:</b> Ability to multi-task, quickly change pace on a moment\\u2019s notice, juggle multiple responsibilities, and manage a high volume of transactions.</p></li><li><p><b>Communication:</b> Strong communicator who places a high value on customer service and cross-functional collaboration.</p></li><li><p><b>Execution:</b> Dedication to excellent customer service, timeliness, thoroughness, and the ability to perform flawlessly under tight deadlines.</p></li><li><p><b>Culture Fit:</b> Team player who understands that success rests on helping others to be successful. Passionate about Cloudera and our opportunity, and driven to succeed.</p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-ZY1</p>","261024":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Professional Services<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>Strategic Customer Success Manager\\u2019s (CSM\\u2019s) are charged with driving Success Plans through operating as a trusted advisor and customer advocate to drive successful outcomes for our highest profile customers.\\u00a0</p><p></p><p>You will act as a direct liaison between Cloudera and the customer on their Cloudera journey, ensuring that all facets of the customer product adoption journey take place, planning, preparing and driving the execution of the plan in accordance with the customer-agreed timeline. You will pull the customer above the line to enable them to fulfill success initiatives within their business.\\u00a0</p><p>Acting as the customer\\u2019s trusted Cloudera advisor and advocate, CSMs manage a system of checks and balances between the company and the customer, understanding our customer\\u2019s needs, aligning the appropriate Cloudera resources (Engineering, Product Management, Support or Services). This will include assisting with critical escalation management to ensure their Cloudera interactions, business objectives and product adoption is a success.\\u00a0</p><p></p><p>You are comfortable working across business, technical, and senior management in a customer facing role, and you are confident and articulate in communication with stakeholders.\\u00a0</p><p></p><p>A key aspect to success in the role is persistence: forming a relationship of trust with the customer, anticipating issues, acting with agility and flexibility in the face of any situation that may arise.\\u00a0</p><p></p><p><b>As a Customer Success Manager you will:</b></p><ul><li>Exemplify strong customer facing skills and stakeholder management\\u00a0</li><li>Take ownership for the customer\\u2019s product adoption of Cloudera products and Success Plan\\u00a0</li><li>Have experience operating on-site with large enterprise customers\\u00a0</li><li>Liaise and facilitate with key internal and external stakeholders\\u00a0</li><li>Have clear and concise communication skills\\u00a0</li><li>Take an Ownership mentality over your customers and work\\u00a0</li><li>Be comfortable with program, project management</li><li>Demonstrate best practices and ability in managing stakeholder escalations to mutually agreeable outcomes\\u00a0</li><li>Develop &amp; leverage reports, dashboards, and data to summarise customer engagements and statuses, both to internal audiences as well as back to your customers.\\u00a0</li><li>Analyse customer activity and data across the Cloudera organisation, including from Sales, Support, Professional Services, &amp; Training to identify trends, gaps, or issues from and <span>communicating/actioning</span> those to stakeholders (internal and external).\\u00a0</li></ul><p></p><p><b>We\\u2019re excited about you if you have:</b></p><ul><li>Fluent English, other languages a plus</li><li>Experience with large scale data platforms\\u00a0</li><li>Experience with software implementation and upgrade management\\u00a0</li><li>Strong technology background either in a technical or business capacity\\u00a0</li><li>Familiarity with project lifecycle management and the complexities around project delivery.</li><li>Understanding of data management concepts\\u00a0</li><li>Understanding of ITIL concepts\\u00a0</li><li>Experience with an RDBMS (Oracle, MySQL, Teradata, etc)\\u00a0</li><li>Understanding of networking concepts\\u00a0</li><li>Industry vertical experience including FSI, Telecommunications, Manufacturing or Government a plus</li><li>\\u00a05 or more years relevant experience.</li><li>Degree level of education with high attainment or equivalent experience in a related field.</li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-ZY1</p>","260795":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</p><div><div><div><div><div><div><div><div><div><p></p><p>The Security Officer (SO) is responsible for the day-to-day management of protective security within Cloudera A/NZ to ensure compliance with the regulations and INFOSEC requirements of the Australian Federal and State Government agencies but with the potential to extend to the commercial sector. The SO reports to the A/NZ Vice President and operates under the delegated authority of the Chief Security Officer (CSO) to manage various security activities, including personnel security, physical security, and security training, report incidents and establish the governance framework to ensure Cloudera A/NZ complies with federal government industry security programs requirements, frameworks and memberships.</p><p></p><p>The Security Officer takes ownership and will be a proactive problem solver with strong communication skills and attention to detail.</p><p></p><p><b>As a Security Officer you will:</b></p><ul><li><p>Government Compliance &amp; Memberships: Manage and maintain Cloudera A/NZ\\u2019s eligibility, applications, and ongoing compliance for federal government industry security programs.</p></li><li><p>Framework Architecture: Develop, implement, and maintain security policies and procedures aligned with Australian protective security and information security frameworks.</p></li><li><p>Governance &amp; Incident Response: Oversee internal security registers (including foreign travel notifications and security briefings), facilitate mandatory staff security awareness training, and manage local security incident reporting.</p></li><li><p>Market Growth Enablement: Identify evolving government information security requirements, working collaboratively with local teams to ensure Cloudera meets the prerequisites for major government procurement panels.</p></li><li><p>Security Operations Coordination: Act as the central point of contact for the local leadership team on security operations. Provide high-level operational support on highly sensitive and confidential matters, coordinating documentation for internal and external stakeholders.</p></li></ul><p></p><p><b>We\\u2019re excited about you if you have:</b></p><ul><li><p>Citizenship &amp; Clearance: Must be an Australian citizen. Due to the nature of the government frameworks involved, candidates must have the immediate ability to have their background checked.</p></li><li><p>Security Expertise: Proven experience in protective security governance and compliance management, ideally within a government, defense, or highly regulated technology environment.</p></li><li><p>Framework Knowledge: Deep familiarity with Australian government protective security guidelines, information security manuals, and risk management frameworks.</p></li><li><p>Operational Excellence: Exceptional communication skills with the ability to handle highly sensitive, confidential material with total discretion.</p></li></ul><p></p><p><b>You may also have:</b></p><ul><li><p>Experience guiding organizations through formal government security accreditation processes.</p></li><li><p>Strong self-initiative and a proactive problem-solving mindset suited for a fast-paced tech environment.</p></li></ul></div></div></div></div></div></div></div></div></div><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-ZY1</p>","260511":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><b>About Cloudera</b></p><p><span>We are on a mission to make data and analytics easy and accessible to everyone. The work we do empowers any organization\\u2014from the world&#39;s largest enterprises to small nonprofits\\u2014to use data to solve some of the most complex challenges that impact businesses, communities, and lives.</span></p><p></p><p><span>At Cloudera, we are </span>Customer Driven &amp; People First<span>. We believe in the power of our people because when we bring together bold ideas, collaboration, and purpose, we do not just imagine the future\\u2014we help build it.</span></p><p>The Role</p><p><span>This position\\u00a0 will serve as a customer-facing, hands-on technologist with a track record of success. You will be the technical authority for Cloudera\\u2019s </span>Enterprise AI<span> portfolio, bridging the gap between complex data architectures and actionable AI business outcomes.</span></p><p><span>In this senior individual contributor role, you will own the technical sales strategy for the industry\\u2019s only platform bringing AI to data anywhere. You will not only demonstrate technology but also inspire customers to think bigger about their AI roadmap, ensuring they understand the value of the </span>Open Data Lakehouse<span> and </span>Unified Data Fabric<span>.</span></p><p></p><p><b>As a Solutions Engineer \\u2013 Artificial Intelligence, you will:</b></p><ul><li><p>Innovation Lifecycle<span> - develop advanced techniques, solutions, and methodologies for customer core business process adoption</span></p></li><li><p>Research Engineering<span> - assist domain experts, scientists, data scientists and technical engineers to develop AI Solutions to meet organizational objectives to include\\u00a0</span></p></li><li><p>Computational Engineering<span> - work with clients to define objectives to curate data, algorithms, and outcomes; setup training pipelines, large-scale customer experiments, and evaluate models for production deployment</span></p></li><li><p>Research Consultation<span> - consult with research scientists on the art of the possible and invention of new theoretical ideas, and or the practical application of theories to drive a computational engineering solution pipeline</span></p></li><li><p>Own the Technical Sales Lifecycle:<span> Drive the technical sales process from introductory meetings and discovery through to post-sales success, upselling, and subscription renewals.</span></p></li><li><p>Architect AI Solutions:<span> Design comprehensive solutions for customer needs using Cloudera technologies\\u2014specifically </span>Cloudera AI, AI Inference, AI Studios, and AI Workbench<span>\\u2014based on reference architectures and common patterns.</span></p></li><li><p>Strategic Evangelism:<span> Present Cloudera\\u2019s product roadmap and vision to C-level executives (CIO, CTO, CDO), demonstrating how </span>AI Agents<span> and </span>Cloud Bursting<span> accelerate enterprise AI adoption.</span></p></li><li><p>Demonstrate Value:<span> Create and deliver inspiring technical presentations and demonstrations that compel customers to say \\u201cyes\\u201d to Cloudera. Partner with Account Managers to articulate the true business value of our solutions.</span></p></li><li><p>Voice of the Customer:<span> Interface with Product Management and Engineering to advocate for your customers&#39; needs, transforming feedback from the field into actionable roadmap items.</span></p></li><li><p>Community Leadership:<span> Participate in external publicity and evangelism, including speaking at conferences, writing blogs, and leading webinars to drive the narrative around trusted Enterprise AI.</span></p></li></ul><p></p><p><b>We\\u2019re excited about you if you have:</b></p><ul><li><p>Senior Experience:<span> A minimum of </span>8 years of experience<span> in a customer-facing role, ideally in a pre-sales or solutions engineering context.</span></p></li><li><p>AI &amp; Data Proficiency:<span> Deep experience with Data Engineering, Data Science, or Machine Learning. You understand the difference between Data Engineering and Data Science and can navigate the technical nuances of </span>AI Assistants<span> and </span>Data Services<span>.</span></p></li><li><p>Cloud Architecture Skills:<span> Proficiency with one or more major cloud service providers (AWS, Azure, or GCP) and an understanding of hybrid deployment factors (public vs. private cloud).</span></p></li><li><p>Enterprise Governance:<span> You understand that a Data Lake is more than just a storage dump. You are well-versed in the problems of </span>Operations, Security, and Data Governance<span> required to make AI safe for the enterprise.</span></p></li><li><p>Technical Versatility:<span> Experience with Big Data, Data Warehousing (e.g., Iceberg), or Relational Databases, as well as familiarity with Unix/Linux environments.</span></p></li><li><p>Communication Mastery:<span> Excellent written and verbal communication skills, with the ability to whiteboard complex architectures and gather business requirements effectively.</span></p></li><li><p>Passion &amp; Curiosity:<span> A willingness to learn, a curiosity to discover new use cases for Cloudera technology, and a drive to make your customers successful.</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p><span>#LI-ZY1</span></p>","260463":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p></p><p>We are seeking a Staff Software Engineer to drive the evolution of the Cloudera Embedded Container Service based on the Rancher Kubernetes Engine for enterprise and multi-cluster environments. This role will focus on evolving the Rancher Kubernetes Engine\\u2019s integration with the Cloudera Data Services.</p><p></p><p>The Data Services Platform organization has deep technical expertise in distributed computing and container orchestration technologies like Kubernetes, Apache Hadoop, etc. and on various cloud platforms like Openshift, RKE, AWS, Azure, GCP etc. We have team members who have been the pioneers of open source projects like YuniKorn for Kubernetes. We are deeply involved in open source communities like Apache Software Foundation and CNCF.</p><p></p><p>We are incubating a new team focused on Rancher Kubernetes Engine (RKE) under the Data Services Platform organization to strengthen our Embedded Container Service which serves as a foundation for the Cloudera Data Platform - On Premise offering.</p><p></p><h2><b>As a Staff Software Engineer you will\\u2026</b></h2><ul><li><p>Incubate the Rancher Kubernetes Engine focused team and support development of the Cloudera Data Platform - On Premise.</p></li><li><p>Support the integration of Rancher Kubernetes Engine within CDP-On Premise by designing and implementing enhancements around Cluster lifecycle (provisioning, upgrades, backup/restore), CNI based Networking and CSI based Storage.</p></li><li><p>Introduce best-practices and tooling to debug and troubleshoot deployments, upgrades, and ongoing operational problems.</p></li><li><p>Customize and extend RKE using Kubernetes APIs &amp; CRDs, Controllers &amp; Operators, Rancher APIs and other extensions.</p></li><li><p>Define install/upgrade paths for version upgrades and compatibility strategies for Kubernetes and Longhorn</p></li><li><p>Actively influence and work with Quality Engineering &amp; Scale Testing teams to improve the quality standards of the platform.</p></li><li><p>Contribute to Rancher, Kubernetes, Canal, Calico, Flannel, Longhorn and other CNCF projects.</p></li><li><p>Review upstream changes and influence adoption strategy.</p></li><li><p>Represent the team in open-source forums and technical communities.<br /><b>\\u00a0</b></p></li></ul><h2><b>We are excited if you have\\u2026</b></h2><ul><li><p>5&#43; years of backend development experience with strong expertise in Go-lang programming language.</p></li><li><p>Bachelor\\u2019s degree in Computer Science, Engineering, Information Systems, Business, or a related field or equivalent practical experience</p></li><li><p>Solid understanding of Kubernetes Core including the K8s API Server, Scheduler, Control Plane, etcd etc.</p></li><li><p>Experience with designing Kubernetes APIs, CRDs &amp; Controllers with emphasis on backward compatibility.</p></li><li><p>CSI-Level understanding of storage in K8s. Experience with Longhorn development and evolution is highly preferred.</p></li><li><p>An understanding of how these services interact with the host system\\u2019s storage, networking and compute capabilities is required.</p></li><li><p>Strong troubleshooting skills and experience resolving complex issues in Kubernetes, networking, and storage.</p></li><li><p>Hands-on experience with development / troubleshooting of the Rancher Kubernetes Engine\\u00a0</p></li><li><p>Demonstrate ability to go deep into technology and complex distributed systems.\\u00a0</p></li><li><p>Self-driven and motivated, with a strong sense of ownership and craftsmanship</p></li><li><p>Strong written and verbal communication skills</p></li></ul><p></p><h2><b>You may also have\\u2026</b></h2><ul><li><p>Experience building PaaS and SaaS products</p></li><li><p>Experience working in the Cloud Native Computing Foundation (CNCF) community</p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-EO1</p><p>#LI-HYBRID</p>","260875":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Corp. Strategy<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Director<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>As the Director of AI Industry Solutions, you will play a pivotal role in supporting global Sales, R&amp;D, and Customer Retention in the Financial Services industry. Your focus will be on leveraging AI, data analytics, and innovative R&amp;D to track market trends, shape business strategies, and turn insights into actionable plans. You&#39;ll guide Cloudera&#39;s teams through the AI-driven transformation, providing them with the knowledge, tools, and R&amp;D advancements needed to engage effectively with key accounts.</span></p><p><span>In this role, you will create and manage AI-focused content, support internal enablement, pipeline development, and help acquire new clients through industry-specific use cases. You&#39;ll work closely with R&amp;D teams to ensure the latest AI innovations are integrated into solutions, enhancing market differentiation. Additionally, you will lead internal industry communities and represent Cloudera as a subject matter expert at external events, driving thought leadership on AI and advanced analytics in the Financial Services sector.</span></p><p></p><p><b>This role is not eligible for immigration sponsorship.</b></p><p></p><p><b><span>As the Director, Global AI Industry Solutions, you will:</span></b></p><ul><li><p><span>The Strategic Bridge: Translate complex Product R&amp;D advancements into high-value business outcomes, sales playbooks, and go-to-market strategies tailored specifically for the Financial Services sector.</span></p></li><li><p><span>Executive &amp; Technical Evangelism</span>:<span> Act as a trusted advisor to key customer accounts. Deliver compelling presentations to C-level executives (CEOs, CDOs, CIOs) while maintaining deep technical credibility with data science and engineering teams.</span></p></li><li><p><span>Cross-Functional Influence: Collaborate closely with Sales, Product Management, Engineering, and Marketing to ensure Cloudera\\u2019s AI solutions align with evolving market dynamics and customer pain points.</span></p></li><li><p><span>Deal Support &amp; Value Engineering: Provide deep industry-specific AI expertise during high-value sales cycles, helping technical teams validate architecture while helping business buyers calculate ROI.</span></p></li><li><p><span>Thought Leadership: Represent Cloudera as an industry expert at global conferences, panels, and through written collateral, driving market share through insightful, research-backed commentary on AI in finance.</span></p></li><li><p><span>Technical Prototyping &amp; Architecture: Act as a hands-on builder. Design, develop, and deliver cutting-edge AI reference architectures, technical prototypes, and MVPs (Minimum Viable Products) that address specific Financial Services use cases (e.g., fraud detection, risk modeling, generative AI compliance, etc.).</span></p></li></ul><p></p><p><b><span>What We&#39;re Looking For:</span></b></p><ul><li><p><span>The Builder Mindset</span>:<span> Proven ability to build technical prototypes and design production-grade reference architectures.</span></p></li><li><p><span>Technical Proficiency</span>:<span> Deep, hands-on familiarity with enterprise AI/ML engineering lifecycles, data orchestration, hybrid cloud infrastructure, and modern AI frameworks (e.g., LLMs, RAG architecture, vector databases).</span></p></li><li><p><span>Industry Experience</span>:<span> 10&#43; years within the Financial Services ecosystem, with a track record of implementing AI, machine learning, or advanced data analytics solutions in a production environment.</span></p></li><li><p><span>Executive Presence</span>:<span> Exceptional communication skills with the rare ability to pivot seamlessly from technical whiteboarding to high-level business strategy presentations.</span></p></li><li><p><span>Education</span>: <span>Bachelor\\u2019s degree in Computer Science, Engineering, Mathematics, or a highly technical discipline. An advanced technical degree (Master&#39;s or Ph.D.) or an MBA is a strong plus.</span></p></li></ul><p></p><p><b><span>The expected base salary range for this role in:\\u00a0\\u00a0</span></b></p><ul><li><p><span>New York is $200-225k\\u00a0</span></p></li><li><p><span>Please note that the compensation details listed in our job\\u00a0 postings reflect the base salary only, and do not include commissions or bonus as applicable.\\u00a0\\u00a0</span></p></li><li><p><span>The salary will vary depending on your job-related skills, experience and location</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-AO1</p><p>#-LI-HYBRID</p>","260983":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>Ready to take cloud innovation to the next level? Join Cloudera\\u2019s Anywhere Cloud team and help deliver a true \\u201cbuild your own pipeline, bring your own engine\\u201d experience. enabling data and AI workloads to run anywhere, without friction or vendor lock-in.</p><p></p><p>We take the best of the public cloud- cost efficiency, scalability, elasticity, and agility and extend it to wherever data lives: public clouds, private data centers, and even the edge. Powered by Kubernetes, our hybrid architecture separates compute and storage, giving customers maximum flexibility and optimized infrastructure usage.</p><p></p><p>We are looking for a <b>Staff Software Engineer</b> to design and build high-performance infrastructure for Anywhere Cloud (AWC). AWC is Cloudera&#39;s Kubernetes-native platform for deploying data services onto any cluster, including air-gapped environments. The systems layer handles credential brokering, protocol-level proxying, request signing, and distributed log collection. These are Rust services deployed on Kubernetes where correctness and latency matter equally.</p><p></p><p>This is not a feature-engineering role. You will own infrastructure where a subtle bug means a security bypass and a naive implementation means unbounded memory growth. You will set the technical direction for performance-critical services, mentor engineers on systems thinking, and provide the low-level capabilities that the rest of the platform depends on.</p><p></p><p><b>As a Staff Software Engineer you will:</b></p><ul><li><p>High-Performance Service Development: Build and own Rust-based infrastructure services (reverse proxies, credential brokers, log collectors) that sit in the data path. Ship end-to-end from design doc to production.</p></li><li><p>Correctness in Security-Critical Code: Implement and verify authentication protocols and access control enforcement. Write thorough tests (including property-based and fuzz testing) for code where bugs have security implications.</p></li><li><p>Systems Architecture: Design new infrastructure components. Define module boundaries, memory budgets, streaming patterns, and graceful shutdown semantics. Document tradeoffs clearly.</p></li><li><p>Observability: Build distributed telemetry and log collection systems. Instrument services with structured tracing, metrics, and health endpoints.</p></li><li><p>Cross-Team Guidance: Be the go-to engineer when other teams need systems-level help. Performance-sensitive design reviews, streaming patterns, caching strategies.</p></li><li><p>Technical Direction: Drive design documents for new components. Evaluate build-vs-buy decisions. Define testing strategies that give confidence in critical code paths.</p></li></ul><p></p><p><b>We\\u2019re excited about you if you have: (Minimum Qualifications)</b></p><ul><li><p>Experience: 8&#43; years of professional software engineering, with at least 3 years building performance-critical or security-critical systems (proxies, storage engines, network services, or similar).</p></li><li><p>Rust: You have shipped production Rust services (not just CLIs or libraries). Comfortable with async Rust, multi-crate workspaces, and the tokio/hyper ecosystem.</p></li><li><p>Systems Fundamentals: Strong understanding of networking (TCP/HTTP), memory management, streaming/backpressure, and concurrency. You can reason about resource constraints and design accordingly.</p></li><li><p>Security Awareness: Experience working on systems where correctness has security implications. Comfortable reasoning about authentication protocols, input validation, and adversarial edge cases.</p></li><li><p>Kubernetes: Experience deploying and operating services on Kubernetes. Familiarity with the operator pattern, Helm, and cloud-native infrastructure.</p></li><li><p>Testing: You go beyond happy-path unit tests. Experience with property-based testing, integration test harnesses, or fuzz testing.</p></li><li><p>Bsc/Msc in related field or equivalent exerience</p></li></ul><p></p><p><b>You may also have: (Preferred Qualifications)</b></p><ul><li><p>Experience with S3-compatible storage protocols or request signing (SigV4 or similar).</p></li><li><p>Experience building or operating observability/telemetry pipelines (OpenTelemetry, gRPC, log aggregation).</p></li><li><p>Prior work on reverse proxies, load balancers, service meshes, or API gateways.</p></li><li><p>Experience with performance profiling and optimization (flamegraphs, benchmarking, P99 latency work).</p></li><li><p>Experience building Kubernetes operators or controllers.</p></li></ul><p></p><p><b>This role is not eligible for immigration support or relocation.</b></p><p></p><ul><li><p><b>Why this role matters:\\u00a0</b></p><p>This is more than cloud management, it\\u2019s about building the foundation for a consistent, secure, and compliant cloud experience that gives organizations 100% access to 100% of their data, anywhere.</p><p>With the recent acquisition of Taikun, we are simplifying Kubernetes and cloud management even further, creating a platform that is unified, scalable, and future-ready.</p><p>If you are passionate about Kubernetes, not just using it but building it at the core managing workloads across hybrid clouds and datacenters and obsessed with performance, devops, etc. this is where you belong.</p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-AC1</p><p>#LI-HYBRID</p>","260822":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Ready to take cloud innovation to the next level? Join Cloudera\\u2019s Anywhere Cloud team and help deliver a true \\u201cbuild your own pipeline, bring your own engine\\u201d experience. enabling data and AI workloads to run anywhere, without friction or vendor lock-in.</span></p><p></p><p><span>We take the best of the public cloud- cost efficiency, scalability, elasticity, and agility and extend it to wherever data lives: public clouds, private data centers, and even the edge. Powered by Kubernetes, our hybrid architecture separates compute and storage, giving customers maximum flexibility and optimized infrastructure usage.</span></p><p></p><p><span>We are looking for a <b>Staff Software Engineer</b> to design and build high-performance infrastructure for Anywhere Cloud (AWC). AWC is Cloudera&#39;s Kubernetes-native platform for deploying data services onto any cluster, including air-gapped environments. The systems layer handles credential brokering, protocol-level proxying, request signing, and distributed log collection. These are Rust services deployed on Kubernetes where correctness and latency matter equally.</span></p><p></p><p><span>This is not a feature-engineering role. You will own infrastructure where a subtle bug means a security bypass and a naive implementation means unbounded memory growth. You will set the technical direction for performance-critical services, mentor engineers on systems thinking, and provide the low-level capabilities that the rest of the platform depends on.</span></p><p></p><p><b>As a </b><span><b>Staff Software Engineer you will</b></span><b>:</b></p><ul><li><p>High-Performance Service Development:<span> Build and own Rust-based infrastructure services (reverse proxies, credential brokers, log collectors) that sit in the data path. Ship end-to-end from design doc to production.</span></p></li><li><p>Correctness in Security-Critical Code:<span> Implement and verify authentication protocols and access control enforcement. Write thorough tests (including property-based and fuzz testing) for code where bugs have security implications.</span></p></li><li><p>Systems Architecture:<span> Design new infrastructure components. Define module boundaries, memory budgets, streaming patterns, and graceful shutdown semantics. Document tradeoffs clearly.</span></p></li><li><p>Observability:<span> Build distributed telemetry and log collection systems. Instrument services with structured tracing, metrics, and health endpoints.</span></p></li><li><p>Cross-Team Guidance:<span> Be the go-to engineer when other teams need systems-level help. Performance-sensitive design reviews, streaming patterns, caching strategies.</span></p></li><li><p>Technical Direction:<span> Drive design documents for new components. Evaluate build-vs-buy decisions. Define testing strategies that give confidence in critical code paths.</span></p></li></ul><p></p><p><b>We\\u2019re excited about you if you have: (Minimum Qualifications)</b></p><ul><li><p>Experience:<span> 8&#43; years of professional software engineering, with at least 3 years building performance-critical or security-critical systems (proxies, storage engines, network services, or similar).</span></p></li><li><p>Rust:<span> You have shipped production Rust services (not just CLIs or libraries). Comfortable with async Rust, multi-crate workspaces, and the tokio/hyper ecosystem.</span></p></li><li><p>Systems Fundamentals:<span> Strong understanding of networking (TCP/HTTP), memory management, streaming/backpressure, and concurrency. You can reason about resource constraints and design accordingly.</span></p></li><li><p>Security Awareness:<span> Experience working on systems where correctness has security implications. Comfortable reasoning about authentication protocols, input validation, and adversarial edge cases.</span></p></li><li><p>Kubernetes:<span> Experience deploying and operating services on Kubernetes. Familiarity with the operator pattern, Helm, and cloud-native infrastructure.</span></p></li><li><p>Testing:<span> You go beyond happy-path unit tests. Experience with property-based testing, integration test harnesses, or fuzz testing.</span></p></li><li><p>Bsc/Msc in related field or equivalent exerience</p></li></ul><p></p><p><b>You may also have: (Preferred Qualifications)</b></p><ul><li><p><span>Experience with S3-compatible storage protocols or request signing (SigV4 or similar).</span></p></li><li><p><span>Experience building or operating observability/telemetry pipelines (OpenTelemetry, gRPC, log aggregation).</span></p></li><li><p><span>Prior work on reverse proxies, load balancers, service meshes, or API gateways.</span></p></li><li><p><span>Experience with performance profiling and optimization (flamegraphs, benchmarking, P99 latency work).</span></p></li><li><p><span>Experience building Kubernetes operators or controllers.</span></p></li></ul><p></p><p><b>This role is not eligible for immigration support or relocation.</b></p><p></p><ul><li><div><div><div><div><div><div><div><div><div><p><b>Why this role matters:\\u00a0</b></p><p>This is more than cloud management, it\\u2019s about building the foundation for a consistent, secure, and compliant cloud experience that gives organizations 100% access to 100% of their data, anywhere.</p><p>With the recent acquisition of Taikun, we are simplifying Kubernetes and cloud management even further, creating a platform that is unified, scalable, and future-ready.</p><p>If you are passionate about Kubernetes, not just using it but building it at the core managing workloads across hybrid clouds and datacenters and obsessed with performance, devops, etc. this is where you belong.</p></div></div></div></div></div></div></div></div></div></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-AC1</p><p>#LI-HYBRID</p>","260840":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Cloudera empowers the world&#39;s largest enterprises across every industry to use data to solve some of the most complex challenges that </span><a href=\\"https://www.cloudera.com/about/customers/regions-bank.html\\" target=\\"_blank\\"><u>impact businesses,</u></a><span> </span><a href=\\"https://www.youtube.com/watch?v&#61;DroVKhAUvss\\" target=\\"_blank\\"><u>communities</u></a><span> and </span><a href=\\"https://www.cloudera.com/about/customers/discovery-health.html\\" target=\\"_blank\\"><u>lives</u></a><span>. We have a platform that delivers incredible Data and Analytics technology across On-Premises, Public Cloud, and in a Hybrid model. We\\u2019re at an exciting point in our transformation as we successfully execute on our strategy.</span></p><p></p><p></p><p><span>The Cloudera Public Sector sales team is seeking an experienced SLED Account Executive for the North East region. We require a seller with established relationships in this territory, a proven ability to excel at solution selling, and the skills necessary to act as a strategic trusted advisor to our clients. You will join our relationship-driven team and take charge of the SLED North East territory by developing detailed sales/marketing plans and maximizing sales opportunities to drive results that inspire productivity and teamwork. You will rely on your experience and good judgment to proactively build and exponentially grow accounts and drive year-over-year growth in line with revenue goals.</span></p><p></p><p><b>As a SLED Account Executive you will:</b></p><ul><li><p><span>Develop and execute a strategic and comprehensive business plan for your territory, including identifying core customers, mapping the benefits of Cloudera\\u2019s solutions to the business requirements.</span></p></li><li><p><span>Demonstrate a proven ability to excel at complex, consultative solution selling.</span></p></li><li><p><span>Serve as a strategic trusted advisor to key decision-makers across your assigned agencies and subcomponents, driving adoption of Cloudera&#39;s Data and Analytics platform.</span></p></li><li><p><span>Strive to understand the customer\\u2019s organizational structure and work to achieve alignment.</span></p></li><li><p><span>Drive new business in greenfield accounts at the C-suite level or equivalent.</span></p></li><li><p><span>Ensure accurate forecasting, pipeline creation, regular quarterly revenue delivery, and facilitation of sales enablement and regulate the implementation of agreed account and business plans.</span></p></li><li><p><span>Coach &amp; collaborate with partners, accessing resources within Cloudera to support them on specific opportunities, with the goal of building capacity to meet customers\\u2019 demand for Cloudera-related services and skills.</span></p></li><li><p><span>Develop detailed sales/marketing plans and sales forecasts.</span></p></li><li><p><span>Manage time and workflow and create effective call plans.</span></p></li><li><p><span>Monitor competition and respond immediately and appropriately.</span></p></li><li><p><span>Leverage existing relationships to build an exhaustive network and generate prolific referrals.</span></p></li></ul><p></p><p><b>We\\u2019re excited about you if you have:</b></p><ul><li><p><span>A successful &amp; proven track record of overachieving quota goals.</span></p></li><li><p><span>Established, deep-seated relationships within SLED North East region customers</span></p></li><li><p><span>5&#43; years of full sales cycle, technology solutions sales, business development, consulting or equivalent experience.</span></p></li><li><p><span>Ability to operate &amp; thrive in an entrepreneurial environment.</span></p></li><li><p><span>Sales experience with Big Data, Open Source Applications, Enterprise Application Integration, Database and/or Business Intelligence software concepts and solutions preferred.</span></p></li><li><p><span>BA/BS or equivalent educational background.</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-Remote</p><p>#LI-KB1</p>","260677":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>IT<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>Join the IT Infrastructure team, where we provide the foundational technology that powers our entire organization. Our group is dedicated to operational excellence, ensuring our infrastructure is visible, manageable, and optimized. We are currently moving beyond basic asset tracking toward a proactive, service-aware ecosystem, using the ServiceNow CMDB as the central nervous system for our global technology strategy.<br />\\u00a0</p><p>We are seeking a Staff IT Asset Architect (IC4) to serve as the lead designer and strategist for our global Asset Management programme. This is a high-impact, cross-functional role spanning the full breadth of our technology estate: endpoints, data centre infrastructure, cloud accounts and subscriptions, applications, and business services.<br />\\u00a0</p><p>You will build on our existing asset tracking foundations, working to identify gaps in coverage, data quality, and process maturity, and drive a clear roadmap to accelerate the programme toward a fully governed, automated, and business-aligned state.<br />\\u00a0</p><p>Working across IT Infrastructure, InfoSec, Finance, and Cloud Operations, you will establish the standards, workflows, and integrations that make our asset data trustworthy and actionable at every level of the business.<br />\\u00a0</p><p><b>This role is not eligible for sponsorship or relocation.</b></p><p></p><p><b><b>As a </b></b><b>Staff IT Asset Architect you will:</b></p><ul><li><p>Architectural Strategy: Lead the design and evolution of our asset and configuration management architecture within ServiceNow, ensuring it scales to cover all asset classes and supports both technical operations and business service visibility.</p></li><li><p>Taxonomy &amp; Governance Design: Define and own the enterprise asset tagging and metadata standards. Establish the policies that govern how assets are registered, classified, and decommissioned across business units, ensuring consistency from endpoint to cloud account.</p></li><li><p>Strategic Integration: Design and oversee integrations between ServiceNow and external systems including AWS, Azure, GCP, FinOps tooling, security scanners, and endpoint management platforms. Ensure a reliable, multi-source reconciliation model that keeps data accurate and current.</p></li><li><p>Full-Spectrum Asset Lifecycle: Ensure end-to-end lifecycle visibility across all asset classes: physical endpoints, data centre hardware (compute nodes, switches, racks, cabling), cloud accounts and subscriptions, SaaS applications, and internal services.</p></li><li><p>Cross-Functional Leadership: Act as the primary bridge between Infrastructure, InfoSec, Finance, and Cloud Operations. Design the workflows, standards, and governance frameworks that these teams use to manage risk, control spend, and maintain compliance. You will lead through influence and expertise rather than direct authority.</p></li><li><p>Automation Roadmap: Drive the organisation towards autonomous asset management. Design self-healing workflows and automated discovery processes that reduce manual effort and proactively correct data quality issues.</p></li><li><p>Service Mapping &amp; Dependency Visibility: Lead service mapping initiatives for critical applications, ensuring full visibility into upstream and downstream dependencies to support disaster recovery and business continuity planning.</p></li><li><p>Executive Reporting &amp; CMDB Health: Develop KPIs and observability frameworks that communicate asset programme health, infrastructure risk, and financial exposure to VP and C-suite stakeholders in clear business terms.<br />\\u00a0</p></li></ul><p><b><b>We are excited if you have (Required Experience):</b></b></p><ul><li><p>Experience: 7&#43; years in IT Infrastructure or IT Asset Management, with at least 3 years in a lead or architect capacity. Demonstrated experience operating across multiple asset domains, including physical infrastructure, cloud, and application portfolios.</p></li><li><p>Education: Bsc/Msc in related field or equivalent experience.</p></li><li><p>Governance &amp; Standards: Proven ability to design and enforce enterprise-wide asset governance frameworks, including tagging taxonomies, lifecycle policies, and data quality standards.</p></li><li><p>ServiceNow: Strong hands-on experience with the ServiceNow platform, including CMDB, Discovery, and Service Mapping capabilities. Familiarity with the Common Service Data Model (CSDM) and asset lifecycle management within ServiceNow is expected. Ability to work at a technical level with platform configuration and integration design.</p></li><li><p>Cloud &amp; Modern Infrastructure: Solid understanding of multi-cloud environments (AWS, Azure, GCP) and how cloud-native resources, accounts, and subscriptions are managed as assets. Familiarity with containerised and ephemeral infrastructure.</p></li><li><p>Integration &amp; Automation: Experience designing integrations between asset management platforms and external data sources. Comfortable working with APIs and automation tooling, with or without deep coding expertise.</p></li><li><p>Cross-Functional Influence: Demonstrated ability to drive adoption of standards and governance frameworks across teams where you hold influence rather than direct authority. Strong communication skills across technical and non-technical audiences.</p></li><li><p>Analytical Communication: Ability to translate complex infrastructure data into business risk and financial language for senior stakeholders.<br />\\u00a0</p></li></ul><p><b><b>You may also have:\\u00a0</b></b></p><ul><li><p>ServiceNow Certified Implementation Specialist (CIS) in Discovery, Service Mapping, or Hardware Asset Management</p></li><li><p>ITIL v4 Managing Professional or Strategic Leader</p></li><li><p>FinOps Certified Practitioner or equivalent cloud financial governance experience<br />\\u00a0</p></li></ul><p><b><b>Why Join Our Team?</b></b><br />\\u00a0</p><p>As a Staff Engineer, you are a technical sovereign. You will have the autonomy to dismantle legacy silos and build a world-class asset intelligence platform. Your work will directly influence the company\\u2019s ability to scale, its posture against cyber threats, and its multi-million dollar cloud efficiency strategy.</p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-EO1</p><p>#LI-HYBRID</p>","251467":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>The Data Platform Pillar is the bedrock of Cloudera\\u2019s technology, where we design and build the core components that let our customers store, manage, and process data with unmatched scalability, security, and performance.</p><p><br /><br /><span>We are looking for passionate Senior Software Engineers for our Streams Messaging Engineering Team in Hungary. Our team is responsible for the development of Streams Messaging products of Cloudera (featuring Kafka, Schema Registry, Streams Replication Manager and several other components related to streaming)\\u00a0 and making it easily usable by the customers of our platform. Kafka is a general purpose distributed messaging/streaming technology designed for low latency, high throughput, massive scalability and high reliability. Kafka is the fundamental streaming technology in our platform, frequently used together with Apache Flink, Spark and NiFi to ingest, process and analyze large scale message streams.</span></p><p><span>As a Senior Software Engineer, you will collaborate with other engineers and stakeholders in Hungary, the United States and other countries around the globe.</span></p><h2></h2><p></p><h2><b><span>As a Senior Software Engineer you will \\u2026</span></b></h2><ul><li><p><span>Expertize in the Kafka ecosystem, identify improvement areas and define a roadmap to make Kafka more feature-rich, more robust and more supportable resulting in an enterprise grade distribution of Kafka for our customers</span></p></li><li><p><span>Extend monitoring and management capabilities of our platform to make Kafka easy to adopt and operate</span></p></li><li><p><span>Modify and update software application after delivery to correct errors and to improve performance</span></p></li><li><p><span>Develop and maintain automated test framework, tools, and processes</span></p></li><li><p><span>Integrate with other components of our component stack (like Flink, NiFi, etc.)\\u00a0</span></p></li><li><p><span>Develop our big data and large scale streaming data processing platforms targeting on-premise, private/public cloud and hybrid customer environments.</span></p></li><li><p><span>Analyze complex requirements, collaborate with other engineers and other stakeholders internally and in the open source community from around the world to design and implement solutions</span></p></li><li><p><span>Focusing on both functional and non-functional aspects and deliver high-quality products using agile software development lifecycle practices</span></p></li><li><p><span>Help customers adopting new versions of our software</span></p></li><li><p><span>Help troubleshooting customer issues, find the root cause of complex technical problems and provide guidance to system engineers for fixing those in production systems</span></p></li><li><p><span>Help releasing our software for Public Cloud and Private Cloud platforms</span></p></li><li><p><span>Learn continuously to build an extensive knowledge about the Kafka ecosystem, large scale stream processing technologies and become the go-to person in a wide range of questions related to the technology</span></p></li><li><p><span>Demonstrate an open, agile mindset, suggest and implement ideas to continuously improve processes used by the team in a collaborative manner</span></p></li></ul><h2></h2><p></p><h2><b><span>We\\u2019re excited about You if You have \\u2026</span></b></h2><ul><li><p><span>Relevant studies / BS or MS in Computer Science or related field.</span></p></li><li><p><span>Experience with Kafka or other distributed messaging technology</span></p></li><li><p><span>4&#43; years of experience in designing, developing and testing software solutions</span></p></li><li><p><span>Strong Java skills and proficiency across the Java ecosystem</span></p></li><li><p><span>Hands-on experience with Python for data processing, automation or backend development</span></p></li><li><p><span>Experience in the Linux environment</span></p></li><li><p><span>Experience with delivery pipeline tools, CI/CD solutions, automated testing</span></p></li><li><p><span>Analytical mindset to be able to understand complex software systems</span></p></li><li><p><span>Self-driven, proactive and motivated personality, with the ability to effectively work even on loosely defined tasks independently and in a team</span></p></li><li><p><span>Open, agile attitude, focusing on continuous improvement</span></p></li><li><p><span>Excellent verbal and written communication skills in English</span></p></li></ul><h2></h2><p></p><h2><b><span>You may also have ...</span></b></h2><ul><li><p><span>Experience with cloud platforms (AWS, Azure, GCE)</span></p></li><li><p><span>Experience with private cloud technologies and containerization orchestration technologies: Kubernetes, Docker, Helm</span></p></li><li><p><span>Big data experience</span></p></li><li><p><span>Experience in designing, implementing and debugging multithreaded and distributed systems</span></p></li><li><p><span>Experience in open source software development</span></p></li></ul><p><br /><b>Why this role matters:</b><br />\\u00a0</p><p>You will tackle complex distributed systems challenges, crafting the foundational software for the control and data planes that powers CDP and keeps it running at massive scale. Working at the forefront of hybrid and multi-cloud technology, you will empower data scientists, engineers, and analysts with the tools and infrastructure they need for advanced analytics and modeling.</p><p></p><p>\\u00a0Collaboration is key, you will work alongside brilliant minds across product, data science, and engineering to drive innovation, standardize best practices, and shape the future of enterprise AI and data platforms. This is your chance to build the future of data and see your work make a global impact.</p><p></p><p><b>This role is not eligible for immigration\\u00a0sponsorship.</b></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-AC1</p><p>#LI-HYBRID</p>","260337":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Corp. Strategy<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>As a Principal in Business Value Management, you operate at the intersection of business value, AI platform architectures, and deal strategy. You partner with account teams and customer executives to translate complex data and AI capabilities into quantified economic outcomes, shaping investment decisions, influencing deal structures, and enabling enterprises to transition toward AI-native operating models.</span></p><p></p><p><b>As a Principal for Business Value Management you will:</b></p><ul><li><p><span>Drive ARR growth by embedding quantified, forward-looking value narratives into deal strategy, linking AI platform architectures and emerging AI operating models to revenue uplift, cost optimisation, and risk reduction.</span></p></li><li><p><span>Build and present CFO-grade business cases (TCO, ROI, NPV, IRR), incorporating evolving cost dynamics such as inference workloads, utilisation patterns, and long-term AI operating economics.</span></p></li><li><p><span>Align solution design with commercial objectives by partnering with Sales, Solutions Engineering, and Product, ensuring architectures are optimised for performance, scalability, and durable economic efficiency in AI-driven environments.</span></p></li><li><p><span>Engage C-suite stakeholders to shape enterprise AI and data strategies, positioning Cloudera within broader shifts toward platform consolidation, hybrid architectures, and AI-enabled business models.</span></p></li><li><p><span>Lead value discovery engagements to map current-state environments to future-state AI-native architectures, with explicit quantification of value drivers, investment trade-offs, and execution pathways.</span></p></li><li><p><span>Leverage AI tools and automation, including LLMs and agentic workflows, to scale analysis, accelerate insight generation, and industrialise repeatable assets such as TCO models and scenario simulators.</span></p></li><li><p><span>Support complex, multi-year deal cycles through commercial structuring, scenario modelling, and competitive positioning against cloud-native and emerging AI platform alternatives.</span></p></li><li><p><span>Represent Cloudera in executive forums, articulating perspectives on enterprise AI economics, architectural trade-offs, and the long-term implications of AI adoption on cost structures and operating models.</span></p></li></ul><p></p><p><b>We&#39;re excited about you if you have:</b></p><ul><li><p><span>5\\u20137&#43; years in strategy consulting, value engineering, or equivalent customer-facing roles</span></p></li><li><p><span>Strong commercial and financial acumen, including advanced financial modelling (DCF, NPV, IRR) and the ability to link technology decisions to P&amp;L, balance sheet, and cash flow outcomes</span></p></li><li><p><span>Demonstrated ability to influence enterprise deal cycles, including shaping deal strategy, positioning, and commercial outcomes</span></p></li><li><p><span>Solid understanding of modern data platforms, distributed systems, and AI/ML workloads, including data pipelines, model deployment, and infrastructure trade-offs</span></p></li><li><p><span>Ability to quantitatively reason about evolving cost drivers in AI and data environments, including compute, storage, and workload patterns</span></p></li><li><p><span>Hands-on experience using AI tools (e.g., LLMs, automation frameworks) to support analysis, modelling, and content generation</span></p></li><li><p><span>Strong executive presence with the ability to engage and influence CIO, CFO, CDO, and senior business stakeholders</span></p></li><li><p><span>Excellent communication skills, with the ability to distil complex technical and financial concepts into clear, actionable insights</span></p></li><li><p><span>High ownership mindset, with the ability to operate independently in ambiguous, high-growth environments</span></p></li><li><p><span>Proven experience working closely with Sales teams in complex, high-value enterprise deals</span><br />\\u00a0</p></li></ul><p><b>Preferred Experience:</b></p><ul><li><p><span>Post-MBA experience, particularly within a top-tier management consulting firm or equivalent environment</span></p></li><li><p><span>Deep expertise in one or more industries such as Financial Services, Manufacturing, Consumer Goods, or Telecommunications</span></p></li><li><p><span>Experience designing or deploying enterprise AI or data platform architectures in production environments</span></p></li><li><p><span>Experience building scalable value engineering assets such as TCO calculators, benchmarking models, or scenario simulators</span></p></li><li><p><span>Familiarity with hybrid and on-prem AI deployments, including cost and performance trade-offs versus public cloud</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-ND3</p><p>#LI-Remote</p>","260537":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Cloudera Solutions Engineers are the technical leaders in the sales account team. We\\u2019re a close-knit community and truly enthusiastic about our work, which gives us the opportunity to grow our personal reputation both internally and externally in the data community. We are responsible for securing the technical win in each sales opportunity and for building an ongoing relationship with our customers to ensure their business success with Cloudera technologies.\\u00a0</span></p><p></p><p><b><b>As a Solutions Engineer you will:</b></b></p><ul><li><p><span>Own the technical sales process from introductory meetings (net new sales) through post-sales (customer satisfaction, upselling, and subscription renewals)</span></p></li><li><p><span>Supporting the technical needs of customers including discovering new use cases for Cloudera\\u2019s technology</span></p></li><li><p><span>Designing solutions for your customers\\u2019 needs using Cloudera technologies, based on reference architectures and common patterns</span></p></li><li><p><span>Demonstrating Cloudera products in a way that inspires your customers to say \\u201cyes\\u201d to Cloudera</span></p></li><li><p><span>Partnering with your Account Managers to show your customers the true value of a Cloudera solution and drive successful sales</span></p></li><li><p><span>Presenting product roadmap and vision to inspire your customers to think bigger</span></p></li><li><p><span>Interfacing with other Cloudera teams to ensure your customers hear one Cloudera voice\\u00a0</span></p></li><li><p><span>Advocating for your customers\\u2019 needs to Product Management and Engineering</span></p></li><li><p><span>Participating in external publicity and evangelism (conferences, meetups, webinars, blogs)</span></p></li></ul><p></p><p><span>Achievements are aligned to a team goal with annual sales targets, as well as to your participation in knowledge exchange with peers and the wider community.</span></p><p></p><p><b><b>We&#39;re excited about you if you have:</b></b></p><ul><li><p><span>A passion for using technology to make a difference to people and organisations. We&#39;ll supply some amazing tools to help you with this and you&#39;ll provide the connection to use cases, which make it real for your customers</span></p></li><li><p><span>A minimum of 3 years experience in a customer-facing role, ideally in a pre-sales context</span></p></li><li><p><span>Bachelor&#39;s degree in related field of study or equivalent work experience</span></p></li><li><p><span>Valid Security Clearance (Level 2 at the minimum)</span></p></li><li><p><span>The ability to create and give technical presentations and demonstrations</span></p></li><li><p><span>Experience with some of the following technologies:</span></p><ul><li><p><span>Big Data, Data Warehousing or Relational Databases</span></p></li><li><p><span>One or more of the three major cloud service providers (AWS, Azure or GCP). Formal certification is not required, but would be a great thing to have</span></p></li><li><p><span>Data Engineering, Machine Learning and/or AI</span></p></li><li><p><span>Operations, Security and Data Governance within the enterprise</span></p></li><li><p><span>Unix or Linux</span></p></li></ul></li><li><p><span>Experience gathering and understanding customer business requirements</span></p></li><li><p><span>Excellent written and verbal communication</span></p></li><li><p><span>Problem solving skills</span></p></li><li><p><span>A willingness to learn, a curiosity to discover and a drive to make your customers successful</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-ND3</p><p>#LI-Remote</p>","260835":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>As a Engineering Manager in the Taikun pillar at Cloudera, you will lead the team that builds and operates the Cloudera Cloud Foundation (CCF), the foundation layer that every managed Kubernetes cluster (CSK) depends on, across AWS, Azure, Google Cloud, and OpenStack. CCF is what makes those clusters secure, multi-tenant, and operable, and it is a hard prerequisite for the broader Cloudera platform on Kubernetes.</span></p><p></p><p><span>You will lead a growing, geographically distributed team across European, Indian, and US time zones, set the bar for execution and engineering quality, and partner with architects and peer engineering teams across Cloudera to deliver the foundation Cloudera runs on.</span></p><p></p><h1><b><span>As an Engineering Manager you will\\u2026</span></b></h1><ul><li><p><span>Lead, grow, and mentor a team of platform and software engineers responsible for CCF&#39;s foundation services, distributed across European, Indian, and US time zones.</span></p></li><li><p><span>Own delivery and execution end-to-end for CCF:\\u00a0 roadmap, commitments, predictability, quality, and operational excellence..</span></p></li><li><p><span>Partner with architects to translate architecture into well-scoped engineering work; bring independent judgment to technical decisions and escalate cleanly when needed.</span></p></li><li><p><span>Drive multi-tenant, multi-cloud (AWS, Azure, Google Cloud, OpenStack) design and execution, ensuring CCF behaves consistently across substrates.</span></p></li><li><p><span>Partner with peer engineering teams across Cloudera to align on contracts, dependencies, and integration points.</span></p></li><li><p><span>Establish and uphold engineering standards: code review, testing, CI/CD, observability, security posture, and incident response.</span></p></li><li><p><span>Recruit, hire, and onboard engineers at pace across multiple geographies; run performance management, career development, and 1:1s.</span></p></li></ul><p></p><h1><b><span>We are excited if you have\\u2026</span></b></h1><ul><li><p><span>5&#43; years of engineering management experience leading platform, infrastructure, or cloud-native teams, with a strong senior IC background prior to management.</span></p></li><li><p><span>Experience leading distributed teams across multiple time zones, including Europe and North America.</span></p></li><li><p><span>Hands-on familiarity with the Kubernetes ecosystem and the cloud-native platform stack: Helm, GitOps tooling, CI/CD systems, and common ecosystem components, enough to engage credibly in architecture and design discussions, ask sharp questions, push back when something smells off, and earn IC trust.</span></p></li><li><p><span>Track record of shipping infrastructure software (not just operating it)\\u00a0 including decisions about packaging, distribution, and lifecycle.</span></p></li><li><p><span>Strong delivery track record: roadmap ownership, dependency management, predictable execution.</span></p></li><li><p><span>Good written and verbal communication; able to drive alignment with peer engineering managers and cross-functional partners.</span></p></li><li><p><span>BSc/MSc in a relevant field or equivalent experience.</span></p></li></ul><p></p><h1><b><span>You may also have\\u2026</span></b></h1><ul><li><p><span>Experience building or operating platforms in airgapped or restricted-network environments.</span></p></li><li><p><span>Familiarity with OpenStack as a substrate.</span></p></li><li><p><span>Exposure to policy-as-code and admission control patterns.</span></p></li><li><p><span>Contributions to open-source CNCF projects.</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p><span>#LI-EO1</span></p><p>#HYBRID</p>","260744":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Product Mgmt.<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>The ideal candidate has a clear sense of what platform and infrastructure engineers need to reliably host, scale, and secure the environments that power massive data pipelines\\u2014and how to turn that into product choices. We have more ideas than we can ship; you prioritize ruthlessly, then support your choices with data, customer evidence, empathy, and conviction.</span></p><p></p><p><span>Cloudera Cloud Core (CCC) is our private cloud platform for running Cloudera data services: a combined stack of Kubernetes (container orchestration), OpenStack (IaaS on bare metal), and Ceph (software-defined storage), operated on bare metal infrastructure. As Staff Product Manager for CCC, you will work with engineering, field, and marketing, partner with strong practitioners across the stack, and engage with customers who depend on Cloudera for critical workloads. You will help define how CCC is deployed, scaled, and operated, and how it supports the full lifecycle of Cloudera\\u2019s data services on this platform.</span></p><p></p><p><b>As a Senior Product Manager you will:</b></p><p></p><ul><li><p>Product vision and strategy:<span> Define and communicate a long-term vision and strategy for Cloudera Cloud Core, spanning Kubernetes, OpenStack, and Ceph on bare metal, and align the control plane and platform roadmap with Cloudera\\u2019s company strategy and with how customers adopt CCC in their environments.</span></p></li><li><p>Feature specification:<span> Turn that vision into PRDs, user stories, and Jira epics for the CCC team. Be explicit on the \\u201cwhat\\u201d and \\u201cwhy\\u201d for engineering, with clear outcomes in reliability, security, performance, scale, operability, and cost. Requirements should reflect how features behave across the K8s, OpenStack, and Ceph stack, not only a single layer.</span></p></li><li><p>Roadmap management:<span> Own a prioritized product roadmap for Cloudera Cloud Core. Make data-driven tradeoffs among customer needs, market direction, and technical debt\\u2014including upgrades, day-2 operations, and platform consistency across deployments.</span></p></li><li><p>Market and customer insight:<span> Run ongoing market and competitive analysis for Kubernetes control planes, private cloud and OpenStack-style platforms, storage platforms like Ceph, and hybrid / FinOps / operations patterns. Be the main path for customer feedback through field, partners, and direct customer conversations.</span></p></li><li><p>Own the Cloudera Cloud Core platform roadmap:<span> Guide capabilities for elasticity, cost and capacity optimization, governance, and automated lifecycle and resource management across Kubernetes, OpenStack, and Ceph on bare metal, so CCC delivers a consistent operational model for Cloudera data services in hybrid and multicloud topologies.</span></p></li><li><p>Go-to-market and enablement:<span> Work with Marketing, Sales, Solutions Engineering, Technical Field Teams and Documentation on launches, positioning, and packaging of Cloudera Cloud Core. Build messaging and enablement so internal teams and customers understand value, architecture, and deployment models for CCC, including how K8s, OpenStack, and Ceph fit together on bare metal.</span></p></li><li><p>Business ownership: <span>Define and track KPIs for Cloudera Cloud Core\\u2014such as hardware utilization efficiency, TCO (Total Cost of Ownership) reduction, cluster stability/uptime, and Day-2 upgrade success rates across complex, air-gapped or restricted environments.deployment growth, service adoption, upgrade success, and platform health\\u2014aligned to business and customer outcomes.</span></p></li></ul><p></p><p><b>We are excited if you have (Required Experience):</b></p><p></p><ul><li><p><span>Experience 5&#43; years in product management, with meaningful exposure to distributed data platforms, cloud and private-cloud data services, and/or control-plane and infrastructure products (Kubernetes, OpenStack, storage at scale).</span></p></li><li><p><span>Strong understanding of the Kubernetes ecosystem, and how it integrates with infrastructure and storage in a platform like CCC</span></p></li><li><p><span>OpenStack experience or strong familiarity: IaaS concepts, networking, and operations on bare metal</span></p></li><li><p><span>Ceph experience or strong familiarity: object, block, and file usage patterns, capacity, resilience, and day-2 operations in productized platforms</span></p></li><li><p><span>Hands-on or deep familiarity with how hybrid patterns connect to on-prem and bare metal</span></p></li><li><p><span>Experience with containerized software on Kubernetes at customer scale, with awareness of storage and network dependencies on Ceph and OpenStack in bare metal environments</span></p></li><li><p><span>Appreciation for how CCC\\u2019s full stack fits into larger data and analytics deployments</span></p></li><li><p><span>Proven ability to write crisp technical specs (PRDs), define user stories and use cases, spot patterns in customer and operational feedback, and simplify complex platform topics for many audiences while managing a healthy backlog.</span></p></li><li><p><span>Hybrid cloud Experience with products that run in public cloud, private cloud, and on premises (including bare metal), and the differences in operations, compliance, and networking across those.</span></p></li></ul><p></p><p><b>You may also have:</b></p><ul><li><p><span>MBA or equivalent business depth</span></p></li><li><p><span>Prior experience as a Staff product manager (IC) on infrastructure, platform, or data/control-plane products</span></p></li></ul><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-HYBRID</p><p>#LI-AC1</p>","260863":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Marketing<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><div><p><span>As the </span>Global Executive Briefing Manager<span> , you will own the strategic direction, operational execution, and global scale of Cloudera\\u2019s flagship customer briefing experience. This is a high-visibility, senior individual contributor role for a strategic operator who doesn&#39;t just manage a schedule, but understands how to leverage a physical space to accelerate revenue, build brand equity, and deepen relationships with our most valuable enterprise customers.</span></p><p><span>You will have the independence to audit our current briefing program, challenge the status quo, and build a world-class, immersive executive experience from the ground up. If you are a builder, a master collaborator, and a champion of world-class customer experiences, we want you to lead our next phase of growth.</span></p></div><p></p><p><b>As a Global Executive Briefing Manager, you will:</b></p><ul><li><p>Strategic Vision &amp; Operational Excellence:<span> Define and execute the global strategy for the Customer Briefing Program. Drive scalable growth by introducing automation, modernizing processes, and expanding the program\\u2019s global footprint.</span></p></li><li><p>Program Revitalization &amp; Strategy:<span> Conduct a comprehensive audit of our existing EBC infrastructure, content, and processes. Design and execute a strategic roadmap to transform the center into a high-tech, high-touch showcase of our innovation.</span></p></li><li><p>Content &amp; Messaging Strategy:<span> Partner with Product Marketing to maintain and continuously enhance a cutting-edge content catalog that reflects market trends, technical advancements, and core value propositions.</span></p></li><li><p>Discussion Leader\\u00a0 Bureau Management:<span> Recruit, onboard, train, and support a world-class bureau of internal subject matter experts and executives, ensuring they can deliver high-impact presentations with clarity and conviction.</span></p></li><li><p>Internal Business Development &amp; Sales Alignment:<span> Act as a strategic partner to the Global Sales organization. Enable and equip account teams to strategically leverage the briefing program to accelerate deals and unlock revenue opportunities.</span></p></li><li><p>Customer Insights:<span> Capture vital customer feedback to ensure our product roadmap aligns with market demands</span><b><span>.</span></b></p></li><li><p>Data &amp; Analytics Alignment:<span> Partner closely with the Marketing Operations team to define, track, and report on key KPIs, utilizing data-driven insights to measure program ROI and optimize performance.</span></p></li><li><p>Onsite Experience Ownership:<span> Manage the daily physical environment, technology integrations (AV, digital signage, interactive displays), and premium catering/hospitality vendors to ensure an elite, white-glove experience</span></p></li></ul><p></p><p></p><p><b>We\\u2019re excited about you if you have:</b></p><p></p><ul><li><p>Experience:<span> 7&#43; years of experience managing Executive or Customer Briefing Programs (EBP), in a global B2B technology environment.</span></p></li><li><p>The &#34;IC&#34; Superpower:<span> You are a self-starter who thrives in an autonomous individual contributor role. You possess the strategic gravitas to guide C-level executives, but you aren&#39;t afraid to roll up your sleeves and handle the tactical logistics of an onsite center.</span></p></li><li><p>Leadership Skills:<span> Proven track record of scaling programs through innovation, process optimization, and automation toolkit implementation.</span></p></li><li><p>Cross-Functional Influence:<span> Exceptional relationship-building skills with the ability to collaborate effectively with Sales,Strategy, Product Management, Product Marketing, and C-suite executives.</span></p></li><li><p>Communication Mastery:<span> Exceptional presentation, writing, and interpersonal skills. You can command a room of internal or external executives with ease and diplomacy.</span></p></li><li><p>Financial Acumen:<span> Strong budget management skills with an eye for strategic resource allocation.</span></p></li><li><p>Presence:<span> Must be able to work onsite at our San Jose campus to manage the physical center, welcome guests, and oversee daily operations.</span></p></li></ul><p></p><p></p><p><span>The Global EBC Manager will partner with our growing sales team to scale our business. This person will help drive the programs to accelerate Cloudera\\u2019s revenue growth, targeting the decision-makers of our customers by showcasing our strategy, building trust, partnering on customer success and building relationships.</span></p><p></p><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-AW1</p><p>#LI-Hybrid</p>","260461":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><h2><b><b>About the Role</b></b></h2><p></p><p><span>We are building Cloudera Cloud Core \\u2014 the base layer for the Cloudera ecosystem on-prem. Kubernetes runs on bare-metal servers (certified enterprise-grade hardware from Dell, Pure Storage), with containerized OpenStack running on top of that Kubernetes (deployed with openstack-helm). AI and big data workloads run on top of the platform. The product is based on the OpenStack Taikun product pillar and the majority of the team is based in the Czech republic, including full-remote co-workers. We are using mainly Claude and also other AI models are available through our LLM gateway.</span></p><p></p><p><b><span>Tech Stack:</span></b></p><p><span>- Kubernetes (bare-metal), containerized OpenStack (openstack-helm)</span></p><p><span>- Python, Bash</span></p><p><span>- GitHub, FluxCD, Harness, OpenTofu/Terraform</span></p><p><span>- Prometheus, Loki, Grafana</span></p><p><span>- Rook-Ceph</span></p><p><span>- Cilium, Istio-ambient, Traefik</span></p><p><br />\\u00a0</p><p><b><b>As a Senior Staff Platform Engineer you will:\\u00a0\\u00a0</b></b></p><ul><li><p><span>Design and build the platform product that powers Cloudera&#39;s SaaS.</span></p></li><li><p><span>Work on system architecture, platform lifecycle and GitOps-driven delivery at scale</span></p></li><li><p><span>Rewrite the current Ansible-based provisioning to use our own Kubernetes distribution</span></p></li><li><p><span>Work on our lifecycle manager for the solution</span></p></li><li><p><span>Build an enterprise-grade modern monitoring stack (greenfield project)</span></p></li><li><p><span>Support running on hundreds of bare-metal servers (potentially thousands in some cases)</span></p></li><li><p><span>Drive GitOps adoption (FluxCD) across provisioning and lifecycle management</span></p></li><li><p><span>Ensure compliance with security standards (SPIRE/SPIFFE, FedRAMP) and support air-gapped deployments</span><br />\\u00a0</p></li></ul><p><b><b>We are excited about you if you have:</b></b></p><ul><li><p><span>8&#43; years of related experience.\\u00a0</span></p></li><li><p><span>Deep Linux system administration and networking knowledge</span></p></li><li><p><span>System design and infrastructure architecture (understanding the big picture)</span></p></li><li><p><span>Kubernetes and cloud-native technologies</span></p></li><li><p><span>GitOps workflows (FluxCD or similar)</span></p></li></ul><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-EO1</p><p>#LI-HYBRID</p>","260700":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><h2><b><span>About the Role</span></b></h2><p></p><p><span>We are building a hybrid cloud platform for enterprise customers based on Kubernetes and cutting-edge CNCF technologies, tackling challenges like air-gapped deployments and FedRAMP compliance. We are building a platform to run significant AI and big data workloads, scaling up to thousands of nodes. The product is based on the Taikun product pillar and the majority of the team is based in the Czech republic, including full-remote co-workers. We are using mainly Claude and also other AI models are available through our LLM gateway.</span></p><p></p><p><b><span>Tech Stack:</span></b></p><p><span>- Kubernetes, GCP/AWS/Azure, OpenStack</span></p><p><span>- Golang, C#</span></p><p><span>- GitHub, FluxCD, Harness, OpenTofu/Terraform, Crossplane</span></p><p><span>- Prometheus, Loki, Grafana</span></p><p><span>- OpenBao, Kyverno</span></p><p><span>- External-dns, cert-manager, trust-manager</span></p><p><span>- Cilium, Istio-ambient, Traefik</span></p><p><span>- Velero</span></p><p><span>- Keda</span></p><p></p><p><b><b>As a Staff Systems Engineer you will\\u2026</b></b></p><ul><li><p><span>Improve scaling solution which can cover cases of thousands of clusters and applications</span></p></li><li><p><span>Ensure our platform is compliant with security standards e.g. role-based identity (SPIRE/SPIFFE) and certifications like e.g. FedRamp</span></p></li><li><p><span>Participate on the new architecture design from scratch on standardization of observability for the whole company (greenfield project)</span></p></li><li><p><span>Ensure our platform can provide seamless upgrade for the heavy stateful workload running on top of it</span></p></li><li><p><span>\\u00a0Implementing new features to our APIs, K8s operators and tooling</span></p></li></ul><p></p><p><b><b>We are excited if you have\\u2026</b></b></p><ul><li><p><span>Proficiency with Kubernetes and cloud-native technologies</span></p></li><li><p><span>6&#43; years of Development experience of platform tools and systems (Golang or other languages)</span></p></li><li><p><span>Good collaboration and communication skills.</span></p></li><li><p><span>Bsc/MSc in related field or equivalent experience</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-EO1</p><p>#LI-HYBRID</p>","260931":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Marketing<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Director<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p></p><p>As the Senior Director of Developer Relations &amp; Community, you will build and scale Cloudera\\u2019s global developer community, driving adoption, advocacy, and engagement for Cloudera\\u2019s data and AI platform.<br />You will own strategy and execution, serving as the primary bridge between Cloudera\\u2019s marketing, product, and engineering teams and the global developer community, including open-source innovators. As the face of Cloudera to developers, you will champion our &#34;AI Anywhere, Cloud Anywhere, Data Anywhere&#34; differentiation and define the global evangelism strategy, ensuring Cloudera remains the preferred hybrid data and AI platform for data engineers and AI practitioners.<br />This role will collaborate closely with the Chief Product Officer and engineering leaders to ensure developer feedback directly informs the evolution of our hybrid data and AI platform.</p><p><br /><b>As Sr Director of Developer Relations &amp; Community, you will:</b></p><p></p><ul><li><p><b>Strategy &amp; Leadership:</b> Define and execute the global developer marketing strategy to drive awareness, adoption, and advocacy among developers and AI/OpenSource engineers - ensuring we speak with an authentic voice across channels and programs.\\u00a0</p></li><li><p><b>Developer Programs: </b>Lead developer acquisition programs, ensuring they deliver measurable developer engagement. Collaborate with Demand Gen on paid marketing for developers, including advertising campaigns targeting AI/OpenSource developers, sponsorships, and experimental acquisition channels. Oversee developer events strategy, including conference sponsorships, speaking engagements, workshops, and creative activations showcasing use cases.</p></li><li><p><b>Community Building: </b>Establish and nurture a vibrant developer community through events, forums, hackathons, and online content. Own and develop key relationships with AI/OpenSource developer communities and influencers (AI research labs,Twitter, Universities, etc.) \\u2026 Understand where the practitioners are.</p></li><li><p><b>Content &amp; Enablement: </b>Oversee the creation of technical content, tutorials, sample applications, and other resources that empower developers to succeed with our products.\\u00a0</p></li><li><p><b>Collaboration:</b> Work closely with Product, Engineering, Sales, and Marketing teams to align on messaging and ensure a cohesive go-to-market approach. Collaborate cross-functionally to ensure developer needs inform roadmap, messaging and GTM programs.\\u00a0</p></li><li><p><b>Metrics &amp; Optimization</b>: Measure and analyze the impact of developer marketing initiatives, using data to refine tactics and improve engagement over time.\\u00a0</p></li></ul><p>\\u200b<br /><b>We are excited about you if you have the following:</b></p><p></p><ul><li><p>10&#43; years in developer marketing or a closely related field, ideally in a B2B tech or SaaS environment.\\u00a0</p></li><li><p>Previous leadership position of Developer Marketing required.</p></li><li><p>Strong understanding of developer communities, developer tools, and the AI/OpenSource landscape.</p></li><li><p>Experience as practitioner in the data and AI field; deep knowledge of databases, application development, and AI/OpenSource.\\u00a0</p></li><li><p>Excellent communication skills and the ability to translate technical concepts into compelling narratives.\\u00a0</p></li><li><p>Leadership experience and a collaborative mindset to drive cross-functional initiatives.\\u00a0</p></li><li><p>Ability to work with and manage agencies and contractors to deliver results.</p></li><li><p>This role is not eligible for immigration support</p></li></ul><p><br />The anticipated annual base salary range for this position is:<br />[Massachusetts]: $211,000- $235,000<br />\\u00a0</p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-AW1</p><p>#LI-Remote</p>","260921":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>The Data Platform Pillar is the bedrock of Cloudera\\u2019s technology, where we design and build the core components that let our customers store, manage, and process data with unmatched scalability, security, and performance.\\u00a0</span></p><p><span>Cloudera is seeking a Senior </span>Staff Software Engineer, Spark (Java)<span> with strong distributed systems expertise to work on the Cloudera distribution of </span>Apache Spark<span> and </span>Livy<span>. The role involves building enterprise-grade systems for customers running Spark on thousands of nodes and processing petabytes of data.</span></p><p><span>We are looking for a passionate engineer eager to enhance a product already supporting major production systems and to drive the next-generation Data Engineering experience. You will collaborate with a distributed team across the United States and Hungary, including multiple Apache Spark committers.</span></p><p></p><p><b>This role is not eligible for immigration sponsorship or relocation.</b></p><p></p><p><b>As a Senior Staff Software Engineer, you will:</b></p><ul><li><p><span>Design new features for Cloudera\\u2019s data engineering experience, and take them from prototypes to leading a team to deliver the feature in production at scale</span></p></li><li><p><span>Contribute to Apache Spark, Livy</span></p></li><li><p><span>Develop new features in Scala/Java/Python on a modern platforms</span></p></li><li><p><span>Gain expertise in distributed data processing, from SQL planners and optimizers, to data layout and table formats like Apache Parquet and Iceberg, to fault tolerance in distributed systems.</span></p></li><li><p><span>Gain a solid understanding and deep technical knowledge of components across the Cloudera Data Engineering Experience stack, but focusing on Iceberg and Spark, which you can utilize in your daily tasks</span></p></li><li><p><span>Get to work on large scale distributed systems, from 100s to 1000s of nodes, in production clusters</span></p></li><li><p><span>Debug system level deployment issues, root cause analysis, perform system test analysis and resolve failures</span></p></li><li><p><span>Work on improving internal infrastructure</span></p></li><li><p><span>Collaborate with other team members and stakeholders</span></p></li></ul><p></p><p><b>We are excited if you have (Required Experience):</b></p><ul><li><p><span>Bsc/Msc in related field or equivalent experience</span></p></li><li><p><span>6&#43; years professional software development.</span></p></li><li><p><span>Experience leading and delivering complex product enhancements.</span></p></li><li><p><span>We use Java/Scala/Python in projects, you should have a strong understanding of at least one of the following languages: Java, Scala, Python. And interested to learn the languages we\\u2019re using.</span></p></li><li><p><span>Experience with systems design, development.</span></p></li><li><p><span>Passionate about programming, clean coding habits, attention to detail, and focus on quality</span></p></li><li><p><span>Strong oral and written communication skills.</span></p></li><li><p><span>Strong ability to research and solve problems independently without constant supervision</span></p></li><li><p><span>(Most importantly) Open-minded, desire to learn new things and build great products.</span></p></li><li><p><span>Experience with distributed systems</span></p></li></ul><p></p><p><b>You may also have:</b></p><ul><li><p><span>Experience with SQL planners</span></p></li><li><p><span>Experience with using/developing Apache Spark, Livy or other related technologies.</span></p></li><li><p><span>Experience with large-scale, distributed systems design and development with an understanding of scaling, performance, and scheduling.</span></p></li><li><p><span>Solid experience with at least one cloud s</span></p></li></ul><p></p><p><b>Why this role matters:\\u00a0</b></p><p></p><p><span>You will tackle complex distributed systems challenges, crafting the foundational software for the control and data planes that powers CDP and keeps it running at massive scale. Working at the forefront of hybrid and multi-cloud technology, you will empower data scientists, engineers, and analysts with the tools and infrastructure they need for advanced analytics and modeling.</span></p><p><span>Collaboration is key, you will work alongside brilliant minds across product, data science, and engineering to drive innovation, standardize best practices, and shape the future of enterprise AI and data platforms. This is your chance to build the future of data and see your work make a global impact.</span></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-AO1</p><p>#LI-HYBRID</p><p>#LI-REMOTE</p>","260934":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><b>About Cloudera</b></p><p>We are on a mission to make data and analytics easy and accessible to everyone. The work we do empowers any organization\\u2014from the world&#39;s largest enterprises to small nonprofits\\u2014to use data to solve some of the most complex challenges that impact businesses, communities, and lives.</p><p></p><p>At Cloudera, we are Customer Driven &amp; People First. We believe in the power of our people because when we bring together bold ideas, collaboration, and purpose, we do not just imagine the future\\u2014we help build it.</p><p>The Role</p><p>This position\\u00a0 will serve as a customer-facing, hands-on technologist with a track record of success. You will be the technical authority for Cloudera\\u2019s Enterprise AI portfolio, bridging the gap between complex data architectures and actionable AI business outcomes.</p><p>In this senior individual contributor role, you will own the technical sales strategy for the industry\\u2019s only platform bringing AI to data anywhere. You will not only demonstrate technology but also inspire customers to think bigger about their AI roadmap, ensuring they understand the value of the Open Data Lakehouse and Unified Data Fabric.</p><p></p><p><b>As a Solutions Engineer \\u2013 Artificial Intelligence, you will:</b></p><ul><li><p>Innovation Lifecycle - develop advanced techniques, solutions, and methodologies for customer core business process adoption</p></li><li><p>Research Engineering - assist domain experts, scientists, data scientists and technical engineers to develop AI Solutions to meet organizational objectives to include\\u00a0</p></li><li><p>Computational Engineering - work with clients to define objectives to curate data, algorithms, and outcomes; setup training pipelines, large-scale customer experiments, and evaluate models for production deployment</p></li><li><p>Research Consultation - consult with research scientists on the art of the possible and invention of new theoretical ideas, and or the practical application of theories to drive a computational engineering solution pipeline</p></li><li><p>Own the Technical Sales Lifecycle: Drive the technical sales process from introductory meetings and discovery through to post-sales success, upselling, and subscription renewals.</p></li><li><p>Architect AI Solutions: Design comprehensive solutions for customer needs using Cloudera technologies\\u2014specifically Cloudera AI, AI Inference, AI Studios, and AI Workbench\\u2014based on reference architectures and common patterns.</p></li><li><p>Strategic Evangelism: Present Cloudera\\u2019s product roadmap and vision to C-level executives (CIO, CTO, CDO), demonstrating how AI Agents and Cloud Bursting accelerate enterprise AI adoption.</p></li><li><p>Demonstrate Value: Create and deliver inspiring technical presentations and demonstrations that compel customers to say \\u201cyes\\u201d to Cloudera. Partner with Account Managers to articulate the true business value of our solutions.</p></li><li><p>Voice of the Customer: Interface with Product Management and Engineering to advocate for your customers&#39; needs, transforming feedback from the field into actionable roadmap items.</p></li><li><p>Community Leadership: Participate in external publicity and evangelism, including speaking at conferences, writing blogs, and leading webinars to drive the narrative around trusted Enterprise AI.</p></li></ul><p></p><p><b>We\\u2019re excited about you if you have:</b></p><ul><li><p>Senior Experience: A minimum of 8 years of experience in a customer-facing role, ideally in a pre-sales or solutions engineering context.</p></li><li><p>AI &amp; Data Proficiency: Deep experience with Data Engineering, Data Science, or Machine Learning. You understand the difference between Data Engineering and Data Science and can navigate the technical nuances of AI Assistants and Data Services.</p></li><li><p>Cloud Architecture Skills: Proficiency with one or more major cloud service providers (AWS, Azure, or GCP) and an understanding of hybrid deployment factors (public vs. private cloud).</p></li><li><p>Enterprise Governance: You understand that a Data Lake is more than just a storage dump. You are well-versed in the problems of Operations, Security, and Data Governance required to make AI safe for the enterprise.</p></li><li><p>Technical Versatility: Experience with Big Data, Data Warehousing (e.g., Iceberg), or Relational Databases, as well as familiarity with Unix/Linux environments.</p></li><li><p>Communication Mastery: Excellent written and verbal communication skills, with the ability to whiteboard complex architectures and gather business requirements effectively.</p></li><li><p>Passion &amp; Curiosity: A willingness to learn, a curiosity to discover new use cases for Cloudera technology, and a drive to make your customers successful.</p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-ZY1</p>","260884":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>The Cloudera Data Services On Premise Platform team seeks a passionate lead engineer to join our growing engineering team. The team is responsible for building out the market-leading management and orchestration plane for data at scale, on-prem, and in the cloud and is at the heart of Cloudera\\u2019s hybrid story. The team&#39;s goal is to make the management of data products simple and develop functional capabilities for everyday users, operators, and admins to interact with the data in amazingly interactive ways. We are a team of top-notch engineers passionate about distributed systems, scalability, test-driven development, and user experience.</span></p><p></p><p><span>You will be responsible for architecting and driving cross-engineering initiatives for various Cloudera Data Services applications. Designed specifically for mission-critical environments, the Cloudera Data Services includes the Control Plane, Cloudera Manager, and several Data Experiences, which combine the best of Cloudera\\u2019s management and data plane into a one-stop sophisticated data machine to orchestrate and scale workloads.</span></p><p></p><p><b>As a Staff Full Stack Engineer\\u00a0you will: </b></p><ul><li><p><span>Work closely with Product Managers to drive a project\\u2019s requirements and convert said requirements into technical designs</span></p></li><li><p><span>Produce high-fidelity design documentation and get sign-offs from architects on aligning the design along with delivering high quality code to create elegant, scalable, enterprise-quality cloud based application services</span></p></li><li><p><span>Execute the development of software with a strong focus on the security, performance, and robustness</span></p></li><li><p><span>Build strong relationships and collaborate with UI engineers, quality engineers, UX designers, Product Managers, SRE, Infosec and external partners</span></p></li><li><p><span>Hire, mentor and lead junior engineers by example</span></p></li><li><p><span>Work to enhance developer productivity and team agility</span></p></li></ul><p></p><p><b>We are excited if you have (Required Experience):</b></p><ul><li><p><span>12&#43; years of experience building scalable applications with Golang and Java.</span></p></li><li><p><span>Solid hands-on experience with microservices development (gRPC, REST etc.), Object Oriented Programming System (OOPS), SQL and NoSQL databases, Messaging infrastructure, etc.</span></p></li><li><p><span>At least 5 years of development and production experience with Kubernetes (such as in an on-premise or Private Cloud environment), OpenShift, or other enterprise-grade private cloud platforms, Terraform, etc.</span></p></li><li><p><span>Should have some conceptual understanding of Enterprise networking aspects for on-premise and Private Cloud deployments (such as VLANs, Load Balancers, VPNs, Firewalls, and other datacenter networking concepts).</span></p></li><li><p><span>Experience in debugging connection problems. Knowledge of how TLS and PKI work.</span></p></li><li><p><span>Self-driven with a strong sense of ownership and craftsmanship along with high bias for action.</span></p></li><li><p><span>Strong written and verbal communication skills.</span></p></li></ul><p></p><p><b>You may also have:</b></p><ul><li><p><span>Experience with implementing Service Mesh such as Istio</span></p></li><li><p><span>Experience with certification/compliance standards such as Fedramp, CIS etc.</span></p></li></ul><p></p><p></p><p><b><b>Why this role matters:</b></b></p><p></p><p><span>This is your opportunity to build cloud-native solutions that are deployable anywhere whether in massive clusters on any cloud provider or in private data centers. You\\u2019ll work with cutting-edge technologies like Trino, Spark, Airflow, and advanced AI inferencing systems to shape the future of analytics. Your code will directly influence how data engineers, analysts, and developers worldwide find value in their data.</span></p><p></p><p><span>We believe in the power of open source. You\\u2019ll collaborate with project committers, contributing upstream to keep technologies like Apache Hive and Impala evolving. You\\u2019ll harden these engines for rock-solid security, optimize them for peak performance, and make them effortlessly run across all environments.\\u00a0 Join us and help build the trusted, cloud-native platform that powers insights for the most data-intensive companies on the planet.</span></p><p></p><p><b>This role is not eligible for immigration sponsorship or relocation.</b></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-BV1</p><p>#LI-REMOTE</p>","260865":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Product Mgmt.<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>\\u00a0Cloudera is seeking an experienced and visionary Senior Product Manager for Anywhere Cloud (AWC) Platform to own security across hybrid and multi-cloud environments. This role is within the fast paced Anywhere Cloud team driving new innovation.</span></p><p></p><h2><b>This role is not eligible for Immigration Sponsorship or Relocation.</b></h2><p></p><p><b>As a Senior Product Manager you will:</b></p><ul><li><p><span>Define and drive the product roadmap for security on the Anywhere Cloud platform.\\u00a0</span></p></li><li><p><span>Translate complex customer needs and market opportunities into detailed product requirements, user stories, and acceptance criteria for engineering teams.</span></p></li><li><p><span>Collaborate closely with engineering, design, and other cross-functional teams to ensure successful product development, delivery and customer satisfaction.</span></p></li><li><p><span>Lead the entire product lifecycle from concept to launch and post-launch optimization, ensuring high-quality, scalable, and secure product offerings.</span></p></li><li><p><span>Champion product adoption and customer success through strong advocacy, thought leadership, and engagement with key customers and partners.</span></p></li><li><p><span>Monitor and analyze product performance metrics, identifying areas for improvement and driving continuous product enhancements.</span></p></li><li><p><span>Stay abreast of industry trends, technologies, and best practices security and data.\\u00a0</span></p></li></ul><p></p><p><b>We are excited if you have (Required Experience):</b></p><ul><li><p><span>Bachelor&#39;s degree in Computer Science, Engineering, or a related technical field. MBA or advanced degree is a plus.</span></p></li><li><p><span>5&#43; years of experience in product management, with a strong focus on security and data platforms.</span></p></li><li><p><span>Proven track record of successfully defining, launching, and managing enterprise-grade software products in a fast-paced environment.</span></p></li><li><p><span>Deep understanding of security,\\u00a0</span></p></li><li><p><span>Experience with cloud platforms (AWS, Azure, GCP) and hybrid cloud environments.</span></p></li><li><p><span>Excellent communication, presentation, and interpersonal skills, with the ability to articulate complex technical concepts to diverse audiences.</span></p></li><li><p><span>Demonstrated ability to lead cross-functional teams and influence stakeholders at all levels.</span></p></li><li><p><span>Strategic thinker with a strong business acumen and a customer-centric approach.</span></p></li><li><p><span>Experience with Agile development methodologies.</span></p></li></ul><p></p><p><b>You may also have:</b></p><ul><li><p><span>Familiarity with open-source security, compute &amp; data technologies such as Kubernetes, SSL/TLS, OAuth/OIDC, SAML, OWASP Top 10, FIPS 140-3</span></p></li><li><p><span>Experience with regulated industries and data compliance (e.g., GDPR, CCPA, \\u00a0FedRAMP.).</span></p></li><li><p></p></li></ul><p>This role is not eligible for immigration sponsorship.</p><p><span>\\u00a0</span></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-CP1</p><p>#LI-HYBRID</p>","260850":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><div>Cloudera Sales empowers the world&#39;s largest enterprises across every industry to use data to solve some of the most complex challenges that <u><span><a href=\\"https://www.cloudera.com/about/customers/regions-bank.html\\" target=\\"_blank\\">impact businesses,</a></span></u> <u><span><a href=\\"https://www.youtube.com/watch?v&#61;DroVKhAUvss\\" target=\\"_blank\\">communities</a></span></u> and <u><span><a href=\\"https://www.cloudera.com/about/customers/discovery-health.html\\" target=\\"_blank\\">lives</a></span></u>. We have a platform that delivers incredible Data and Analytics technology across On- Prem, Public Cloud, and in a Hybrid model. We\\u2019re at an exciting point in our transformation as we<br />successfully execute on our strategy.</div><div><br />As part of the Sales team, you will have autonomy to engage with leading enterprise customers, prospects and partners. You will help foster long term, sustainable, and mutually rewarding relationships. This is your opportunity to be part of something intellectually stimulating, fast paced, transform a customer\\u2019s business, and earn financial rewards along the way.<br /><br /><b>As a Key Account Director you will:</b></div><ul><li>Align with the company&#39;s strategic objectives, handle and grow revenue and market share at designated Enterprise accounts to improve customer success at all levels in the customer organization.</li><li>Develop and deliver business plans to address customer and prospect priorities and critical needs.</li><li>Convey public and acquired intelligence about customer technology footprints, strategic growth plans, technology strategies and competitive landscape and trends Introduce domain product and service experts/specialists while maintaining account oversight.</li><li>Own account relationships and drive overall customer success for these assigned accounts.</li><li>Build consensus and develop relationships at multiple levels \\u2013 executive sponsors, influencers and decision makers.</li><li>Lead large scale transactions to close large scale deals. Build pipeline, forecast business, lead the internal team, communicate key updates and competitive intelligence.</li><li>Exceed quarterly and annual new and expansion software subscription, renewals, professional service and training business goals.</li></ul><div></div><div><b>We\\u2019re excited about you if you have:</b></div><ul><li>Minimum 11&#43; years of exceeding enterprise software sales targets</li><li>Fast moving start-up and vertical use case driven experience</li><li>Data management or Data warehousing experience</li><li>Containers, Kubernetes and public cloud infrastructure technology knowledge and experience</li><li>Four year degree (Bachelor&#39;s) from accredited university required</li><li>Ability to travel domestically and internationally</li></ul><p></p><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI - Remote</p><p>#LI - KB1</p>","260568":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Cloudera Sales empowers the world&#39;s largest enterprises across every industry to use data to solve some of the most complex challenges that </span><a href=\\"https://www.cloudera.com/about/customers/regions-bank.html\\" target=\\"_blank\\"><u>impact businesses,</u></a><span> </span><a href=\\"https://www.youtube.com/watch?v&#61;DroVKhAUvss\\" target=\\"_blank\\"><u>communities</u></a><span> and </span><a href=\\"https://www.cloudera.com/about/customers/discovery-health.html\\" target=\\"_blank\\"><u>lives</u></a><span>. We have a platform that delivers incredible Data and Analytics technology across On- Prem, Public Cloud, and in a Hybrid model. We\\u2019re at an exciting point in our transformation as we successfully execute on our strategy.\\u00a0</span></p><div><div><div><div><p></p><p><span>As part of the Sales team, you will have autonomy to engage with leading enterprise customers, prospects and partners. You will help foster long term, sustainable, and mutually rewarding relationships. This is your opportunity to be part of something intellectually stimulating, fast paced, transform a customer\\u2019s business, and earn financial rewards along the way.\\u00a0</span></p></div></div></div></div><p></p><p></p><p>As a Sales Account Manager you will:</p><ul><li><p><span>Align with the company&#39;s strategic objectives, handle and grow revenue and market share at designated Enterprise accounts to improve customer success at all levels in the customer organization.\\u00a0</span></p></li><li><p><span>Develop and deliver business plans to address customer and prospect priorities and critical needs</span></p></li><li><p><span>Convey public and acquired intelligence about customer technology footprints, strategic growth plans, technology strategies and competitive landscape and trends</span></p></li><li><p><span>Introduce domain product and service experts/specialists while maintaining account oversight</span></p></li><li><p><span>Own account relationships and drive overall customer success for assigned accounts</span></p></li><li><p><span>Build consensus and develop relationships at multiple levels \\u2013 executive sponsors, influencers and decision makers</span></p></li><li><p><span>Lead large scale transactions to close large scale deals </span></p></li><li><p><span>Build pipeline, forecast business, lead the internal team, communicate key updates and competitive intelligence</span></p></li><li><p><span>Exceed quarterly and annual new and expansion software subscription, renewals, professional service and training business goals </span></p></li></ul><p></p><p>We&#39;re excited about you if you have:</p><ul><li><p><span>Minimum 8&#43; years of exceeding enterprise software sales targets</span></p></li><li><p><span>Fast moving start-up and vertical use case driven experience</span></p></li><li><p><span>Proven experience building strategic relationships with Financial Services and Telecom customers </span></p></li><li><p><span>Data lifecycle management, Data Lakehouse and Enterprise AI</span><span> experience</span></p></li><li><p><span>Containers, Kubernetes and public cloud infrastructure technology knowledge and experience</span></p></li><li><p><span>Four year degree (Bachelor&#39;s) from accredited university required</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-KB1</p><p>#LI-Remote</p>","260514":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>At Cloudera, we believe that data can make what is impossible today, possible tomorrow. We empower people to transform complex data into clear and actionable insights. Cloudera delivers an enterprise data cloud for any data, anywhere, from the Edge to AI.</p><p></p><p>Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</p><p></p><p>Are you able to quickly understand where individuals are and where they want to go and build trust and lead them down a specific path to generate big results? Are you able to challenge the status quo, engage customers in new ways and earn their trust and business? Are you ready to be intellectually stimulated and earn financial rewards along the way?</p><p></p><p>We are currently seeking a Sales Account Manager based in Singapore.</p><p></p><p><b>As the Sales Account Manager, you will:</b></p><ul><li><p>Align with company\\u2019s strategic objectives, handle and grow revenue and market share at designated accounts to improve customer success at all levels in the customer organization in Thailand and Singapore.</p></li><li><p>Develop and deliver business plans to address customer and prospect priorities and critical needs.</p></li><li><p>Convey public and acquired intelligence about customer technology footprints, strategic growth plans, technology strategies and competitive landscape and trends Introduce domain product and service experts/specialists while maintaining account oversight.</p></li><li><p>Own account relationships and drive overall customer success for assigned accounts.</p></li><li><p>Build consensus and develop relationships at multiple levels \\u2013 executive sponsors, influencers and decision makers.</p></li><li><p>Lead large scale transactions to close large scale deals Build pipeline, forecast business, lead the internal team, communicate key updates and competitive intelligence.</p></li><li><p>Exceed quarterly and annual new and expansion software subscription, renewals, professional service and training business goals.</p></li></ul><p></p><p><b>We\\u2019re excited about you if you have:</b></p><ul><li><p>Minimum 8&#43; years of exceeding enterprise software sales targets</p></li><li><p>Fast moving start-up and vertical use case driven experience</p></li><li><p>Data management or Data warehousing experience</p></li><li><p>Containers, Kubernetes and public cloud infrastructure technology knowledge and experience</p></li><li><p>BA/BS or equivalent educational background</p></li><li><p>Excellent English written and verbal communication skills</p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><div><div>#LI-ZY1</div></div>","260923":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Professional Services<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>As an </span>AI Solutions Engineer<span> within Cloudera\\u2019s Public Sector Consulting team, you will be the technical architect and execution lead for agencies moving from &#34;data chaos&#34; to &#34;agentic autonomy.&#34; You will work directly with government organizations to design, build, and deploy mission-critical AI applications on the Cloudera Data Platform (CDP).</span></p><p></p><p><span>This is not a &#34;theoretical&#34; role. You will be on the front lines of Phase 2 and Phase 3 adoption journeys\\u2014helping customers clean legacy data silos, select the right model architectures, and industrialize MLOps pipelines in highly secure, often air-gapped or hybrid-cloud environments.</span></p><p></p><p><b><b>As the AI Solutions Engineer you will:\\u00a0</b></b></p><p><span>1. AI Model Strategy, Selection and Implementation</span></p><ul><li><p><span>Evaluate and select optimal model architectures (LLMs, SLMs, or traditional ML) based on mission requirements, considering tradeoffs between accuracy, latency, and cost.</span></p></li><li><p><span>Guide customers on &#34;Build vs. Buy vs. Fine-tune&#34; decisions, prioritizing open-source models (Llama, Mistral, Falcon) that can run securely within a sovereign data perimeter.</span></p></li><li><p><span>Experience building Agentic Workflows (AI agents that can execute API calls and multi-step tasks).</span></p></li></ul><p><span>2. End-to-End Data Engineering</span></p><ul><li><p><span>Design and implement robust data pipelines within CDP to transform &#34;messy&#34; legacy data into AI-ready formats.</span></p></li><li><p><span>Develop and optimize Vector Databases and Retrieval-Augmented Generation (RAG) architectures to ground AI responses in verified agency facts.</span></p></li><li><p><span>Build Data pipelines with Spark, Nifi, Kafka or other ETL tools.</span></p></li></ul><p><span>3. Optimization &amp; Performance Tuning</span></p><ul><li><p><span>Optimize model inference for production environments using quantization, pruning, and hardware acceleration (NVIDIA GPU orchestration).</span></p></li><li><p><span>Implement LLMOps to monitor model performance, detect hallucination rates, and manage model versioning and drift.</span></p></li></ul><p><span>4. Public Sector Advisory &amp; Governance</span></p><ul><li><p><span>Collaborate with the customer\\u2019s AI Center of Excellence (CoE) to establish automated guardrails for ethics, bias mitigation, and FedRAMP/IL5 compliance.</span></p></li><li><p><span>Translate complex technical AI concepts into mission-value briefings for GS-level stakeholders and agency leadership.</span></p></li></ul><p></p><p><b><b>We\\u2019re excited about you if you have: (Minimum Qualifications):\\u00a0</b></b></p><ul><li><p><span>Experience: 5&#43; years in Data Engineering, Machine Learning, or Software Engineering, with at least 2 years focused on Generative AI or Deep Learning.</span></p></li><li><p><span>Technical Stack: Expertise in Python and deep learning frameworks (PyTorch, TensorFlow, Hugging Face).</span></p><ul><li><p><span>Hands-on experience with Cloudera (CDP), Spark, or similar big data ecosystems.</span></p></li><li><p><span>Proficiency in orchestration tools like LangChain, LlamaIndex, or Haystack.</span></p></li><li><p><span>Experience developing visual data representations and dashboards (Django, React, or Angular)\\u00a0\\u00a0</span></p></li><li><p><span>Experience using a compiled programming language, preferably one that runs on the JVM (Java, Scala, etc)</span></p></li></ul></li><li><p><span>Data Expertise: Proven ability to build ETL/ELT pipelines and work with both SQL and NoSQL/Vector databases (e.g., Pinecone, Milvus, or PGVector).</span></p></li><li><p><span>Public Sector Knowledge: Understanding of government security frameworks (NIST AI RMF, FedRAMP, SRGs, STIGs).</span></p></li><li><p><span>Active Top Secret Security Clearance</span></p></li></ul><p></p><p><b><b>You may also have: (Preferred Qualifications)</b></b></p><ul><li><p><span>Experience fine-tuning of foundational models using techniques such as PEFT (Parameter-Efficient Fine-Tuning) and LoRA to adapt AI to domain-specific government nomenclature.</span></p></li></ul><ul><li><p><span>Experience training of specialized models on proprietary datasets while ensuring strict adherence to data privacy and sensitivity labels.</span></p></li><li><p><span>Experience installing and operating Cloudera Data Platform\\u00a0</span></p></li><li><p><span>Experience installing and operating Kubernetes</span></p></li><li><p><span>Experience in Air-Gapped deployments and managing AI workloads in disconnected environments.</span></p></li><li><p><span>Advanced degree (MS or PhD) in Computer Science, Data Science, or a related field.</span></p></li><li><p>Active Counterintelligence (CI) or Full Scope (FS) Poly is required.</p></li></ul><p></p><p><span>This role is not eligible for immigration sponsorship.</span></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-Remote</p><p>#LI-ND3</p>","260706":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>IT<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>We are seeking an experienced </span>Senior Data Architect (AI-First Data Architecture &amp; AI-Assisted Development)<span> with 5&#43; years of experience designing scalable enterprise data platforms and enabling modern AI-driven ecosystems. The ideal candidate will bring deep expertise in data warehousing, lakehouse architectures, combined with hands-on experience in AI governance, Large Language Models (LLMs), Retrieval-Augmented Generation (RAG), semantic data architectures, and AI-assisted development practices.</span></p><p></p><p><span>This role extends beyond traditional data architecture by partnering with Business Intelligence, Data Science, Engineering, and AI teams to build AI-ready data foundations. The architect will lead the design of data models, metadata frameworks, and governance practices that optimize enterprise data for AI consumption, intelligent search, agentic workflows, and RAG-based applications. A key focus will be establishing robust metadata, business definitions, lineage, data tagging, and semantic structures to improve the accuracy, discoverability, and scalability of AI-powered solutions.</span></p><p></p><p><span>The successful candidate will drive AI-first data acquisition, curation, and governance strategies that support business intelligence, advanced analytics, and AI-driven decision-making across Finance, Sales, and other strategic business domains. They will also champion AI-assisted architecture and documentation practices to accelerate delivery, improve productivity, and create reusable patterns that enable both users and AI systems to effectively discover, understand, and leverage enterprise data.</span></p><p></p><p><span>This role will lead the evolution of intelligent, governed, and scalable data platforms that seamlessly integrate traditional data engineering with next-generation AI-powered capabilities, ensuring the organization&#39;s data ecosystem is optimized for the future of AI-enabled business operations.</span></p><h3></h3><p></p><p><b>As a Sr. Data Architect you will:</b></p><ul><li><p><span>Design and implement scalable data warehouse and lakehouse architectures on the Cloudera platform.</span></p></li><li><p><span>Define enterprise data models, governance frameworks, data stewardship processes, security standards, and data quality practices.</span></p></li><li><p><span>Architect and optimize analytics solutions across SQL engines including Impala, Hive, and Iceberg.</span></p></li><li><p><span>Design AI-powered analytics solutions leveraging LLMs, Retrieval-Augmented Generation (RAG), vector databases (such as PostgreSQL, Qdrant, Milvus) , and NLQ capabilities.</span></p></li><li><p><span>Lead the integration of AI/ML capabilities into enterprise data platforms and data pipelines while establishing governance controls for AI models, data usage, and lifecycle management.</span></p></li><li><p><span>Leverage vibe coding / AI-assisted development tools to accelerate development and improve productivity.</span></p></li><li><p><span>Build and optimize batch and near real-time data pipelines.</span></p></li><li><p><span>Collaborate with business stakeholders to translate business requirements into scalable data products and analytics solutions.</span></p></li><li><p><span>Establish best practices for performance optimization, data architecture, and AI-assisted development.</span></p></li><li><p><span>Mentor teams on modern data architecture and AI-enabled development methodologies.</span></p></li><li><p><span>Ensure data security, governance, compliance, and responsible AI practices within enterprise data platforms and AI-enabled solutions.</span></p></li><li><p><span>Collaborate with business stakeholders across </span>FP&amp;A, Sales, and Revenue Operations<span> to translate business requirements into scalable data solutions that support </span>financial forecasting, revenue optimization, budgeting, pipeline analysis, and sales forecasting</p></li></ul><p><br />\\u00a0</p><p><b>We are excited about you if you have:</b></p><ul><li><p><span>Bachelor\\u2019s degree in Computer Science or equivalent and 5-6 years of related experience; OR Master\\u2019s degree and 3-5 years of related experience; OR PhD and 0-3 years of related experience</span></p></li><li><p><span>Deep expertise in enterprise data warehousing, lakehouse architectures, and Cloudera-based data platforms.</span></p></li><li><p><span>Strong experience with CDP, including HDFS, Hive, Impala, Kudu, and Cloudera data ingestion and processing frameworks.</span></p></li><li><p><span>Strong understanding of distributed data systems and Hadoop-based architectures.</span></p></li><li><p><span>Advanced SQL skills, including performance tuning and query optimization.</span></p></li><li><p><span>Proficiency in Python and data engineering frameworks.</span></p></li><li><p><span>Experience with dimensional and normalized data modeling.</span></p></li><li><p><span>Strong understanding of data governance, lineage, metadata management, data cataloging, enterprise security, and compliance requirements.</span></p></li><li><p><span>Experience implementing AI governance practices including model governance, AI risk management, explainability, monitoring, and responsible AI controls.</span></p></li><li><p><span>Experience implementing AI/ML, LLM, vector database, and RAG-based solutions in production environments.</span></p></li><li><p><span>Familiarity with AI-assisted development tools (e.g., GitHub Copilot and LLM-powered workflows).</span></p></li><li><p><span>Strong communication, stakeholder management, and problem-solving skills.</span></p></li><li><p><span>Ability to align enterprise data architecture with business objectives in Finance, Sales, and Revenue Operations.</span></p></li><li><p><span>Ability to bridge traditional data platforms with modern AI capabilities</span></p></li></ul><p><br /><b>You might also have:</b></p><ul><li><p><span>Experience with CDP Public Cloud and Private Cloud deployments.</span></p></li><li><p><span>Knowledge of </span>Cloudera Data Warehouse (<span>CDW), </span>Cloudera Data Engineering (<span>CDE), Kafka, Spark, and streaming architectures.</span></p></li><li><p><span>Experience with generative AI, vector databases, modern AI data architectures, and AI governance frameworks.</span></p></li><li><p><span>Understanding of Data Mesh, Data Fabric, and enterprise governance operating models.</span></p></li><li><p><span>Experience working with Salesforce, NetSuite, and other enterprise business systems.</span></p></li><li><p><span>Experience supporting FP&amp;A, Sales Analytics, and executive reporting environments.</span></p></li></ul><p><br /><br /><b>What Makes This Role Unique</b></p><ul><li><p><span>Lead architecture for a modern Cloudera-centric enterprise data platform.</span></p></li><li><p><span>Drive the convergence of data warehousing, lakehouse architectures, and AI innovation.</span></p></li><li><p><span>Influence enterprise-wide data, governance, and AI strategy.</span></p></li><li><p><span>Champion AI-assisted development practices to accelerate productivity.</span></p></li></ul><p></p><p></p><p><b>This role is not eligible for immigration\\u00a0sponsorship.</b></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-SZ1</p><p>#LI-REMOTE</p>","260735":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Corp. Strategy<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>The Pricing &amp; Monetization Manager is accountable for the overall coordination, strategic alignment, and success of the pricing and monetization GTM execution for new products and releases. This role focuses on managing complex projects, developing and executing monetization programs, and driving cross-functional teams toward stated commercial goals and performance metrics. Programs cover new or updated products, offers, and services being introduced to the market.</span></p><p><span>Serving as a strategic partner and operational force multiplier for leadership, this function requires an extremely proactive, data-driven, and analytical member who will ensure both technical execution and commercial readiness across the entire enterprise.</span></p><p></p><h2>As a Pricing &amp; Monetization Manager you will:</h2><ul><li><p>Strategic planning: <span>Plan pricing execution and GTM monetization initiatives for new product launches, working closely with Pricing Strategy Director, VP of Sales Operations, Corporate Strategy and Sales leadership to drive growth through pricing and packaging</span></p></li><li><p>Executive Dashboard &amp; Analytics: <span>Coordinate reporting of commercial initiatives for new product and services launches, track adoption and impact of monetization initiatives post-launch for new and updated products, utilizing financial and product metrics</span></p></li><li><p>Dependency &amp; Influence Management:<span> Identify, map, and influence timely deliverables, complex cross-functional dependencies, and enterprise business processes.</span></p></li><li><p>Risk Mitigation &amp; Contingency Planning:<span> Proactively identify roadblocks and execute contingency planning\\u2014imperative as priorities, market dynamics, and milestones can be in flux.</span></p></li><li><p>Change Management &amp; Strategic Alignment:<span> Facilitate early engagement with senior stakeholders, in particular GTM / Field to ensure strategic alignment, corporate consistency, and clear notification of new projects and/or deliverables.</span></p></li></ul><p></p><h2>We\\u2019re excited about you if you have:</h2><ul><li><p>4-6 years of experience<span> in Product Launch Management, Product Marketing, Strategic Program Management, Commercial Operations, or Pricing Strategy.</span></p></li><li><p><span>Prior experience in high-growth B2B tech, SaaS, or digital services environments with complex, multi-product ecosystems is highly preferred.</span></p></li><li><p><span>Deep understanding of monetization frameworks, value-based pricing models, packaging structures, and tiering strategies.</span></p></li><li><p><span>Skillful at translating complex pricing changes into clear, actionable guidance for GTM and Field sales teams to ensure minimal friction and high adoption.</span></p></li><li><p><span>Proven mastery of New Product Introduction (NPI) frameworks and Go-To-Market (GTM) commercial readiness processes.</span></p></li><li><p><span>Strong capability to interpret complex financial data, product usage metrics, and market trends to drive data-backed decisions.</span></p></li><li><p><span>Experience defining KPIs and creating tracking mechanisms to evaluate the long-term financial health and performance of monetization initiatives.</span></p></li><li><p><span>Proficiency in building executive-ready dashboards and tracking systems using tools like Tableau, Power BI, Excel, or internal CRM/analytics platforms.\\u00a0</span></p></li><li><p><span>Demonstrated history of leading the operational execution of high-stakes product, offer, or service launches from conception through post-launch adoption.</span></p></li><li><p><span>Sharp organizational skills to map intricate interdependencies, manage timelines, and keep multi-phase launches on track.\\u00a0</span></p></li></ul><p></p><p><b>This role is not eligible for immigration sponsorship</b></p><p><br />\\u00a0</p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-KB1</p><p>#LI-remote</p>","260367":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Ready to take cloud innovation to the next level? Join Cloudera\\u2019s Anywhere Cloud team and help deliver a true \\u201cbuild your own pipeline, bring your own engine\\u201d experience \\u2014 enabling data and AI workloads to run anywhere, without friction or vendor lock-in.</span></p><p></p><p><span>We bring the best of public cloud \\u2014 cost efficiency, scalability, elasticity, and agility \\u2014 to wherever data lives: public clouds, private data centers, and the edge. Powered by Kubernetes, our hybrid architecture separates compute and storage to maximize flexibility and optimize infrastructure usage.</span></p><p></p><p><span>This isn\\u2019t just cloud management \\u2014 it\\u2019s about building a consistent, secure, and compliant cloud experience that gives organizations full access to all their data, anywhere.</span></p><p></p><p><span>With the acquisition of Taikun, we\\u2019re simplifying Kubernetes and cloud management even further, creating a unified, scalable, future-ready platform. If you\\u2019re passionate about Kubernetes \\u2014 not just using it, but building it at the core, managing workloads across hybrid clouds and data centers, and obsessing over performance and DevOps \\u2014 this is where you belong.</span></p><p></p><p><span>We are seeking a Staff Software Engineer to lead the architecture and delivery of our cloud\\u2011native AI platform. In this high\\u2011impact role, you will bridge the gap between cutting\\u2011edge AI research and production\\u2011grade Kubernetes environments. You will build the \\u201cnervous system\\u201d of our AI stack\\u2014optimizing how we run and manage open\\u2011source models (Llama, Qwen, etc.) using K8s\\u2011native patterns like Custom Resources (CRDs) and Operators, enabling agentic AI to thrive, and designing integration patterns that let our product teams and customers consume AI capabilities seamlessly.</span></p><p></p><p><b><b>As a Staff Software Engineer, you will:</b></b></p><ul><li><p><b><b>Enterprise AI Services:</b><span> </span></b><span>Design and implement elegant, scalable application services (Go/Node.js) that wrap AI capabilities for enterprise use.</span></p></li><li><p><b><b>K8s-Native AI Orchestration:</b><span> </span></b><span>Lead the deployment of inference servers (vLLM, Triton) using KServe, KubeRay, or Knative to ensure serverless-style scaling for AI workloads.</span></p></li><li><p><b><b>Developer Velocity:</b></b><span> Build internal tooling, SDKs, and &#34;AI Gateways&#34; that enhance team agility and simplify the integration of Foundation Models (Llama, GPT) into product features.</span></p></li><li><p><b><b>RAG &amp; Prompt Engineering:</b><span> </span></b><span>Architect robust Retrieval-Augmented Generation (RAG) pipelines and prompt management services that integrate seamlessly with vector databases and enterprise data sources.</span></p></li><li><p><b><b>Cross-Functional Collaboration:</b><span> </span></b><span>Partner with UI engineers, UX designers, and Product Management to ensure the AI platform is not just powerful, but highly usable for internal developers.</span></p></li><li><p><b><b>Infrastructure &amp; Security:</b><span> </span></b><span>Ensure AI workloads are secure, multi-tenant, and optimized for GPU resource scheduling (MIG, fractional GPUs) within Kubernetes.</span></p></li></ul><p></p><p><b><b>We\\u2019re excited about you if you have:</b></b></p><ul><li><p><span>Bachelor\\u2019s degree with </span>6&#43; years<span> of software engineering experience (or equivalent Masters/PhD tenure), with at least </span>2&#43; years<span> focused on AI/ML systems.</span></p></li><li><p><span>Expert proficiency in </span>Python<span> (for AI ecosystem) and strong competence in a systems language like </span>Go<span> or </span>Rust/C&#43;&#43;<span> (for high-performance serving layers).</span></p></li><li><p><span>Deep understanding of LLM deployment challenges and runtimes (e.g., </span>vLLM, ONNX, TorchServe, Triton<span>). Familiarity with quantization techniques (AWQ, GPTQ) to optimize model size/speed.</span></p></li><li><p><span>Experience building complex workflows using tools like </span>LangChain<span> or </span>LlamaIndex<span>, and deploying them on containerized infrastructure (</span>Docker/Kubernetes<span>).</span></p></li><li><p><span>Ability to navigate the rapidly changing AI landscape, filtering hype from practical engineering solutions, and driving technical alignment across teams.</span></p></li></ul><p></p><p><b><b>You May Also Have:\\u00a0</b></b></p><ul><li><p>Model Fine-Tuning:<span> Experience with efficient fine-tuning techniques (PEFT, LoRA/QLoRA) on custom datasets.</span></p></li><li><p>GPU Optimization:<span> Familiarity with </span>CUDA<span> programming or profiling GPU performance (Nsight systems).</span></p></li><li><p>Open Source:<span> Contributions to open-source AI projects (HuggingFace transformers, vLLM, etc.).</span></p></li></ul><p></p><p><b><b>Why this role matters:\\u00a0</b></b></p><p><span>This is more than cloud management, it\\u2019s about building the foundation for a consistent, secure, and compliant cloud experience that gives organizations 100% access to 100% of their data, anywhere.</span></p><p></p><p><span>With the recent acquisition of Taikun, we are simplifying Kubernetes and cloud management even further, creating a platform that is unified, scalable, and future-ready.</span></p><p></p><p><span>If you are passionate about Kubernetes, not just using it but building it at the core managing workloads across hybrid clouds and datacenters and obsessed with performance, devops, etc. this is where you belong.</span></p><p></p><p><b><b>This role is not eligible for immigration sponsorship.</b></b></p><p></p><p><i>The anticipated annual base salary range for this position is:</i></p><ul><li><p><i>California: $184,000- $230,000</i></p></li></ul><p></p><p><i>Individual compensation within the published range is determined by the candidate&#39;s skills, experience, qualifications, and primary work location. In addition to base pay, sales roles are eligible for Cloudera&#39;s commission plan, while non-sales roles are eligible for the corporate incentive plan. All employees receive a comprehensive benefits package.</i></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-BV1</p><p>#LI-HYBRID</p>","260823":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Ready to take cloud innovation to the next level? Join Cloudera\\u2019s Anywhere Cloud team and help deliver a true \\u201cbuild your own pipeline, bring your own engine\\u201d experience. enabling data and AI workloads to run anywhere, without friction or vendor lock-in.</span></p><p></p><p><span>We take the best of the public cloud- cost efficiency, scalability, elasticity, and agility and extend it to wherever data lives: public clouds, private data centers, and even the edge. Powered by Kubernetes, our hybrid architecture separates compute and storage, giving customers maximum flexibility and optimized infrastructure usage.</span></p><p></p><p><span>We are looking for a Senior Backend Engineer to build and own backend services for the Anywhere Cloud (AWC) platform. AWC is a Kubernetes-native cloud management platform that provisions and manages clusters across Cloud Providers and On Premise. You will work in Go, building services that run on Kubernetes, and collaborate closely with engineers working on operators, auth, platform infrastructure, and the frontend console. This is a hands-on IC role where you ship production code, design service APIs, and solve real distributed systems problems in a team that moves fast and keeps things simple.</span></p><p></p><p><b>As a Senior Backend Engineer you will:</b></p><ul><li><p>Backend Service Development:<span> Design and build Go microservices (REST APIs via Echo, Kubernetes controllers via controller-runtime) that power the AWC console and platform layer. Services include cluster lifecycle management, app deployment, authentication, and credential brokering.</span></p></li><li><p>Kubernetes-Native Engineering:<span> Build operators, controllers, and jobs that run on Kubernetes. Work with Helm charts, CRDs, and the Kubernetes API directly. Understand pod lifecycle, RBAC, and service mesh (Istio) patterns.</span></p></li><li><p>Platform Integration:<span> Integrate with internal platform components (CCF/Taikun provisioning API, Knox for secrets, cert-manager for TLS, Proxinator for credential indirection) and external cloud provider APIs (AWS S3/IAM, GCP).</span></p></li><li><p>Database and State Management:<span> Design schemas and write migrations (golang-migrate, PostgreSQL). Own data consistency for services that manage cluster state, marketplace metadata, and deployment records.</span></p></li><li><p>Testing and Quality:<span> Write unit and integration tests. Contribute to system-level test infrastructure. Validate changes against real clusters, not just mocks</span></p><p></p></li></ul><p></p><p><b>We are excited if you have (Required Qualifications):</b></p><ul><li><p>Experience:<span> 5&#43; years of professional software engineering experience shipping production backend systems.</span></p></li><li><p>Go Proficiency:<span> Strong day-to-day Go skills. You have built and maintained Go services in production, not just written scripts or CLIs.</span></p></li><li><p>Kubernetes Familiarity:<span> You understand how Kubernetes works from an application developer perspective: pods, services, deployments, CRDs, RBAC. You have deployed services to Kubernetes clusters and debugged issues in that environment.</span></p></li><li><p>API Design:<span> Experience building and maintaining REST APIs. Comfort with request validation, middleware patterns, error handling, and versioning.</span></p></li><li><p>SQL/Relational Databases:<span> Comfortable writing SQL, designing schemas, and managing migrations against PostgreSQL or similar.</span></p></li><li><p>Autonomy:<span> You can take a loosely-defined problem, break it down, and ship a working solution without constant direction. You ask questions when stuck, not when uncertain.</span></p><p></p></li></ul><p><b>You may also have:</b></p><ul><li><p>Kubernetes Operators:<span> Experience building operators or controllers using controller-runtime/kubebuilder. Understanding of reconciliation loops and CRD design.</span></p></li><li><p>Helm:<span> Experience authoring and maintaining Helm charts for complex multi-service deployments.</span></p></li><li><p>Auth/Security:<span> Familiarity with OIDC, SAML, mTLS, or credential-brokering patterns (SigV4, token exchange).</span></p></li><li><p>Cloud Provider APIs:<span> Hands-on experience with AWS or GCP APIs (IAM, S3, networking).</span></p></li><li><p>Build Systems:<span> Comfort with Bazel, Make, or similar build tooling in a monorepo or multi-repo setup.</span></p></li><li><p>Observability:<span> Experience instrumenting services with structured logging (slog), metrics, or distributed tracing.</span></p></li></ul><p></p><p><b><span>Why this role matters:\\u00a0</span></b></p><p></p><p><span>This is more than cloud management, it\\u2019s about building the foundation for a consistent, secure, and compliant cloud experience that gives organizations 100% access to 100% of their data, anywhere. With the recent acquisition of Taikun, we are simplifying Kubernetes and cloud management even further, creating a platform that is unified, scalable, and future-ready. If you are passionate about Kubernetes, not just using it but building it at the core managing workloads across hybrid clouds and datacenters and obsessed with performance, devops, etc. this is where you belong.</span></p><p></p><p><b><b>This role is not eligible for immigration sponsorship or relocation.</b></b></p><p></p><p><i>The anticipated annual base salary range for this position is:</i></p><ul><li><p><i>California: $152,000- $190,000</i></p></li></ul><p></p><p><i>Individual compensation within the published range is determined by the candidate&#39;s skills, experience, qualifications, and primary work location. In addition to base pay, sales roles are eligible for Cloudera&#39;s commission plan, while non-sales roles are eligible for the corporate incentive plan. All employees receive a comprehensive benefits package.</i></p><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-BV1</p><p>#LI-HYBRID</p>","251262":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>The Data Platform Pillar is the bedrock of Cloudera\\u2019s technology, where we design and build the core components that let our customers store, manage, and process data with unmatched scalability, security, and performance. </span></p><p></p><p><span>Cloudera is looking for a strong engineering leader with a distributed systems background to lead a team within the Storage Engineering group, focused on building Apache Ozone and Apache HDFS. The Storage team is responsible for primary storage and storage access layers, which are core to the Cloudera Data Platform.</span></p><p><span>Apache Ozone is an open source, massively scalable, distributed object store with a distributed file system interface. Ozone is designed to scale to tens of billions of files and blocks, and overcome the limitations of Hadoop Distributed File System (HDFS), namely, millions of small files and managing a huge number of data nodes.</span></p><p><span>Ozone is one of the fastest-growing products inside CDP in terms of customer adoption and expansion revenue. This is an opportunity to lead a team that created and wrote most of the Ozone code and make a huge impact on the big data storage industry.</span><br />\\u00a0</p><p></p><p><b>As a Sr. Manager, Engineering you will:</b></p><ul><li><p><span>Manage and lead a team of talented engineers and senior individual contributors based in North America.</span></p></li><li><p><span>Develop and execute on a technical roadmap and strategy for your team, aligning with the department&#39;s vision and the company&#39;s business goals.</span></p></li><li><p><span>Lead and mentor a team of software engineers, including senior and principal-level contributors, fostering a culture of technical excellence and innovation.</span></p></li><li><p><span>Partner with Engineering leaders, product managers, and partner teams to understand requirements, develop solid designs and implementations, and facilitate integration and adoption.</span></p></li><li><p><span>Drive and enforce best practices for the software development lifecycle, including coding standards, testing, deployment, system scalability, reliability, and security, tracking key performance indicators for engineering quality and efficiency.</span></p></li><li><p><span>Communicate team progress, successes, challenges, and strategic plans clearly and transparently to engineering leadership and other business stakeholders.</span></p></li><li><p><span>Oversee team resources, staffing, mentoring, and enhancing a best-of-class engineering team.</span></p></li><li><p><span>Work closely with customers in various geographies and partner teams (like PS and support) to ensure successful adoption of Ozone and provide technical guidance for enterprise customers running 100s of petabytes-scale big data analytics and ML/AI pipelines.</span></p></li><li><p><span>Guide the team in contributing to the Apache open-source community.</span></p></li></ul><p></p><p></p><p><b>We are excited if you have (Required Qualifications):</b></p><ul><li><p>Experience<span>: </span>8&#43;<span> years of experience in software engineering, with </span>2&#43;<span> years in an </span>engineering management role<span>.</span></p></li><li><p>Domain Expertise<span>: Demonstrable experience with the design, implementation, and operation of large-scale distributed systems, particularly in storage, file systems, databases, or cloud infrastructure.</span></p></li><li><p>Technical Depth<span>: Strong understanding of fundamental storage concepts (e.g., consistency, replication, erasure coding, caching).</span></p></li><li><p>Management Skills<span>: Proven track record of </span>leading and managing high-performing engineering teams, <span>demonstrating excellent communication and organizational skills.</span></p></li><li><p>Communication: <span>Excellent written and verbal communication skills. If you can point to publicly available papers, technical articles or blog posts that is a huge plus.</span></p></li><li><p>Education<span>: Bachelor&#39;s or Master&#39;s degree in Computer Science, Computer Engineering, or a related technical field.</span></p></li></ul><p></p><p></p><p><b>You may also have:</b></p><ul><li><p><span>Prior experience contributing to or leading large-scale open-source projects.</span></p></li><li><p><span>Familiarity with the Apache Hadoop big data ecosystem (HDFS, YARN, Hive, Impala, Spark) or related distributed data frameworks.</span></p></li><li><p><span>Experience with specific commercial or open-source distributed storage technologies (e.g., Ceph, Gluster, ZFS, S3-compatible systems).</span></p></li><li><p><span>Experience managing </span>remote or hybrid<span> engineers.</span></p></li></ul><p></p><p><b><b>Why this role matters:\\u00a0</b></b></p><p></p><p><span>You will tackle complex distributed systems challenges, crafting the foundational software for the control and data planes that powers CDP and keeps it running at massive scale. Working at the forefront of hybrid and multi-cloud technology, you will empower data scientists, engineers, and analysts with the tools and infrastructure they need for advanced analytics and modeling.</span></p><p></p><p><span>Collaboration is key, you will work alongside brilliant minds across product, data science, and engineering to drive innovation, standardize best practices, and shape the future of enterprise AI and data platforms. This is your chance to build the future of data and see your work make a global impact.</span><br /><br />\\u00a0</p><p><b>This role is not eligible for immigration\\u00a0sponsorship.</b><br /><br />\\u00a0</p><p><b><span>The expected base salary range for this role in</span></b></p><ul><li><p><b><span>California is $213,000 - $266,000</span></b><b><span> </span><span><span> </span></span><span><span> </span></span><span><span> </span></span><span>\\u00a0</span></b></p></li></ul><p><b><span>The salary will vary depending on your job-related skills, experience and location</span><span> </span></b></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-SZ1</p><p>#LI-REMOTE</p>","251146":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>The Data Platform Pillar is the bedrock of Cloudera\\u2019s technology, where we design and build the core components that let our customers store, manage, and process data with unmatched scalability, security, and performance.\\u00a0</span></p><p></p><p>We are seeking an experienced Senior Software Engineer to join Cloudera&#39;s Cloud Connector Engineering team. In this role, you will design, develop, and maintain cloud connector solutions that enable seamless integration between Cloudera&#39;s data platform and various cloud providers and services. You will work on scalable, high-performance solutions that power data integration across hybrid and multi-cloud environments.</p><p></p><p><b>As a Senior Software Engineer you will:</b></p><ul><li><p>Design and implement cloud connectors that integrate Cloudera&#39;s platform with AWS, Azure, GCP, and other cloud services.</p></li><li><p>Develop robust, well-tested code for data ingestion, movement, and synchronization across cloud platforms.</p></li><li><p>Lead technical design discussions and contribute architectural decisions for connector frameworks and infrastructure.</p></li><li><p>Collaborate with product, architecture, and infrastructure teams to define requirements and specifications.</p></li><li><p>Mentor junior engineers and provide technical guidance on best practices and design patterns.</p></li><li><p>Participate in code reviews, establish coding standards, and drive continuous improvement in code quality.</p></li><li><p>Troubleshoot complex issues in production environments and implement scalable solutions.</p></li><li><p>Document technical designs, APIs, and implementation details for internal and external audiences.</p></li><li><p>Stay current with cloud platform updates, emerging technologies, and industry best practices</p></li></ul><p></p><p><b>Required Qualifications:</b></p><ul><li><p><span>Bsc/Msc in related field or equivalent experience</span></p></li><li><p>5&#43; years of software engineering experience with a focus on cloud platforms or distributed systems</p></li><li><p>Strong proficiency in Java, Python, or Go (one or more)</p></li><li><p>Demonstrated experience developing cloud connectors, integrations, or middleware solutions</p></li><li><p>Reasonable understanding of cloud platforms (AWS, Azure, or GCP) and their services (storage, compute, networking)</p></li><li><p>Experience with data processing frameworks and large-scale data movement</p></li><li><p>Solid understanding of API design, REST, gRPC, and message protocols</p></li><li><p>Proven ability to design and implement scalable, maintainable software solutions</p></li><li><p>Excellent problem-solving skills and attention to detail</p></li><li><p>Strong written and verbal communication skills</p></li><li><p>Experience working in agile environments</p></li></ul><p></p><p><b>Preferred Qualifications:</b></p><ul><li><p>Experience with Apache Hadoop, Spark, or other big data technologies</p></li><li><p>Familiarity with Kubernetes, Docker, or container orchestration</p></li><li><p>Background in cloud-native application development</p></li><li><p>Experience with CI/CD pipelines and infrastructure automation</p></li><li><p>Contributions to open-source projects</p></li><li><p>Knowledge of data governance, security, and compliance in cloud environments</p></li><li><p>Experience with monitoring, logging, and observability tools</p></li></ul><p></p><p><b><b>Why this role matters:\\u00a0</b></b></p><p></p><p><span>You will tackle complex distributed systems challenges, crafting the foundational software for the control and data planes that powers CDP and keeps it running at massive scale. Working at the forefront of hybrid and multi-cloud technology, you will empower data scientists, engineers, and analysts with the tools and infrastructure they need for advanced analytics and modeling.</span></p><p></p><p><span>\\u00a0Collaboration is key, you will work alongside brilliant minds across product, data science, and engineering to drive innovation, standardize best practices, and shape the future of enterprise AI and data platforms. This is your chance to build the future of data and see your work make a global impact.</span></p><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-VG1</p><p>#LI-HYBRID</p>","260696":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>The Data Platform Pillar is the bedrock of Cloudera\\u2019s technology, where we design and build the core components that let our customers store, manage, and process data with unmatched scalability, security, and performance.\\u00a0</span></p><p></p><p><span>As a Staff Software Engineer of the Replication Manager team, you will be responsible for designing, developing, and maintaining enterprise-grade data replication solutions that enable seamless data movement across hybrid and multi-cloud environments. You&#39;ll work on critical infrastructure that helps Fortune 500 companies manage their data lifecycle and migration strategies.</span></p><p></p><p>As the Staff Software Engineer\\u00a0 you will lead: (5-7 bullets)</p><ul><li><p><span>Data Replication Engineering \\u2014 Design and implement scalable replication services across HDFS, Hive, HBase, Apache Iceberg, and other big data technologies, with strong data consistency and minimal downtime.</span></p></li><li><p><span>Cloud Migration \\u2014 Lead complex data migration initiatives between on-premises clusters and cloud environments including AWS S3 and Azure ADLS Gen2.</span></p></li><li><p><span>API &amp; Microservices Development \\u2014 Build robust APIs and microservices for the Replication Manager platform, along with advanced features like bandwidth throttling, scheduling, and policy management.</span></p></li><li><p><span>Distributed Systems Architecture \\u2014 Design fault-tolerant, petabyte-scale distributed systems with comprehensive monitoring, alerting, and observability capabilities.</span></p></li><li><p><span>Security &amp; Governance \\u2014 Ensure data security and governance compliance during movement operations, leveraging Apache Atlas for metadata lineage and data discovery.</span></p></li><li><p><span>Product &amp; Innovation \\u2014 Drive technical decisions for new features, evaluate emerging replication and cloud technologies, and translate business requirements into technical specifications.</span></p></li><li><p><span>Cross-functional Collaboration \\u2014 Partner with CDP, SRE, and field engineering teams to integrate replication capabilities, resolve customer escalations, and improve system reliability.</span></p></li><li><p><span>Technical Mentorship \\u2014 Guide junior engineers on best practices, conduct code reviews, and contribute to technical documentation and customer-facing materials.</span></p></li></ul><p></p><p>We\\u2019re excited about you if you have: (Minimum Qualifications)</p><ul><li><p><span>12&#43; years in software engineering with strong proficiency in Java, Scala, or Python, and deep hands-on experience with the Apache Hadoop ecosystem (HDFS, Hive, HBase, YARN).</span></p></li><li><p><span>Solid experience with modern data formats including Apache Iceberg, Delta Lake, and Hive tables with ACID support, alongside streaming technologies like Kafka and Pulsar.</span></p></li><li><p><span>Practical experience across AWS, Azure, and GCP storage services, with working knowledge of containerization tools like Docker and Kubernetes.</span></p></li><li><p><span>Proven ability to architect large-scale distributed systems with a strong grasp of data consistency models, CAP theorem, microservices, and API design.</span></p></li><li><p><span>Familiarity with security protocols and data governance frameworks to ensure compliant and trustworthy data operations.</span></p></li><li><p><span>Well-versed in agile SDLC, CI/CD pipelines, automated testing, Git-based code review workflows, and observability tooling including Prometheus, Grafana, and the ELK stack.</span></p></li></ul><p></p><p>You may also have: (Preferred Qualifications)</p><ul><li><p><span>Experience with Apache Ranger and Apache Atlas for data governance and metadata management</span></p></li><li><p><span>Understanding of Apache Iceberg table format and its replication challenges in hybrid cloud environments</span></p></li><li><p><span>Knowledge of enterprise backup and disaster recovery solutions</span></p></li><li><p><span>Previous experience in data migration or ETL pipeline development</span></p></li><li><p><span>Contributions to open-source big data projects</span></p></li><li><p><span>Experience in customer-facing roles or supporting enterprise customers</span></p></li><li><p><span>Advanced degree in Computer Science, Engineering, or a related field</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-SV1</p>","260810":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>We are seeking passionate and skilled engineers to join our </span>Public Cloud Image Engineering / R&amp;D Core<span> team. As a </span>Senior Software Engineer<span>, you will play a key role in developing and maintaining the </span>public cloud images <span>and</span> infrastructure<span> that underpin our product&#39;s multi and hybrid cloud data management capabilities. This role offers the opportunity to drive technical direction and execute complex engineering tasks focused on reliable, secure, and performant images.</span></p><h3></h3><p></p><p></p><p><b><span>As a Senior Software Engineer, you will:</span></b></p><ul><li><p>Design, develop, and maintain automated pipelines<span> for building, testing, and distributing our secure, hardened public cloud images across </span>AWS, GCP, <span>and</span> Azure<span>.</span></p></li><li><p><span>Focus on developing core image capabilities, including </span>security hardening, infrastructure provisioning, configuration management, <span>and</span> release automation<span> for our product.</span></p></li><li><p><span>Utilize </span>Packer, Python, <span>and</span> Go<span> to automate the creation and lifecycle management of these cloud artifacts.</span></p></li><li><p><span>Utilize </span>Ansible<span> and </span>Salt<span> for configuration management</span></p></li><li><p><span>Serve as a </span>technical expert and role model<span>, providing guidance and mentorship to other engineers on best practices for image creation, security, and cloud infrastructure.</span></p></li><li><p><span>Play a pivotal role in influencing </span>platform definition, technical architecture of the image pipeline, <span>and</span> adherence to modern project delivery principles.</p></li><li><p><span>Collaborate effectively with high-performance individuals across various teams to ensure image consistency and compatibility.</span></p></li></ul><h3></h3><p></p><p><b><span>We are excited about you if you have (required Experience):</span></b></p><ul><li><p><span>MSc/BSc degree in computer science or equivalent industry experience.</span></p></li><li><p>Demonstrated experience as a Senior Software Engineer<span> or equivalent role, driving the architecture and execution of complex projects related to cloud infrastructure or image automation.</span></p></li><li><p>Strong background <span>in</span> public cloud (AWS, GCP, Azure)<span>, with expertise in infrastructure provisioning, security, and service enablement.</span></p></li><li><p>Expertise in creating <span>and</span> managing immutable infrastructure/VM images<span> using tools like </span>Packer<span>.</span></p></li><li><p><span>Expertise in </span>containerization<span> technologies like </span>Docker <span>and </span>container images<span>\\u00a0</span></p></li><li><p>Advanced proficiency in Python and/or Go<span> for automation and tooling; experience in other relevant languages (especially </span>Java<span>) is a plus.</span></p></li><li><p>Strong expertise <span>in</span> developing, deploying, <span>and</span> operating systems <span>in</span> production.</p></li><li><p><span>Solid knowledge of </span>Linux environments<span> and </span>CI/CD solutions <span>like</span> Jenkins<span> and </span>GitHub actions<span> for pipeline automation.</span></p></li><li><p><span>Experience with the full software development lifecycle, including production operations, monitoring, alerting, and participating in an on-call rotation for the services you build.</span></p></li><li><p><span>You are a proactive problem-solver who can independently identify, define, and drive projects forward with minimal guidance.</span></p></li><li><p><span>Proven ability to diagnose and resolve challenging issues in large-scale, distributed cloud environments.</span></p></li><li><p><span>Excellent communication skills and the ability to collaborate effectively with cross-functional teams across different geographies.</span></p></li></ul><h3></h3><p></p><p><b>This role is not eligible for immigration sponsorship or relocation.</b></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-EO1</p><p>#LI-HYBRID</p>","260440":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>The Data Platform Pillar is the bedrock of Cloudera\\u2019s technology, where we design and build the core components that let our customers store, manage, and process data with unmatched scalability, security, and performance.\\u00a0</span></p><p></p><p><span>Are you ready to architect the future of big data? Cloudera is searching for a visionary Staff Software Engineer with deep expertise in distributed systems to join the Apache Spark Team. You will be at the forefront of innovation, building our next-generation, enterprise-grade system designed to conquer data challenges at a massive scale\\u2014running Spark on thousands of nodes and crunching petabytes of data for the world&#39;s largest companies. This is your chance to directly influence the open-source community as a key contributor to Apache Spark while collaborating with a high-impact, distributed team that includes multiple Spark committers. If you&#39;re passionate about pushing the boundaries of distributed data processing, come build the impossible with us.\\u00a0\\u00a0</span></p><p></p><p><b><span>As a Staff Engineer you will:</span></b></p><ul><li><p>Pioneer Scalable Solutions:<span> Architect, implement, and deliver next-generation features for Cloudera\\u2019s Data Engineering Experience, operating at a massive scale on thousands of production nodes.</span></p></li><li><p>Drive Open-Source Innovation:<span> Be a core contributor to </span>Apache Spark<span>, directly shaping the future of distributed data processing in the open-source community.</span></p></li><li><p>Build with Modern Stacks:<span> Develop high-performance features using Scala, Java, and Python on modern data platforms.</span></p></li><li><p>Deepen Technical Mastery:<span> Gain and apply expert-level knowledge in core distributed data processing concepts, including:</span></p><ul><li><p>SQL Planners and Optimizers</p></li><li><p><span>Data layout and modern table formats like </span>Apache Parquet and Iceberg</p></li><li><p><span>Fault tolerance and resilience in large-scale distributed systems.</span></p></li></ul></li><li><p>Own the Technology Stack:<span> Develop a deep technical understanding of components across the Cloudera Data Engineering Experience, with a focus on Iceberg and Spark, applying this knowledge to your daily tasks.</span></p></li><li><p>Conquer Large-Scale Challenges:<span> Work hands-on with massive distributed systems, scaling from hundreds to thousands of nodes in live production clusters.</span></p></li><li><p>Ensure System Integrity:<span> Conduct thorough root cause analysis, debug complex system-level deployment issues, and resolve failures to maintain high system quality.</span></p></li><li><p>Enhance Engineering Velocity:<span> Improve internal infrastructure and tooling to streamline development, testing, and deployment processes.</span></p></li><li><p>Collaborate and Influence:<span> Work closely with a high-impact, distributed team and stakeholders to drive product vision and delivery.</span></p></li></ul><h1></h1><h2><span>We are excited about you if you have: </span></h2><ul><li><p>Professional Experience:<span> 5-7&#43; years of experience in professional software development.</span></p></li><li><p>Leadership &amp; Delivery:<span> Proven experience leading technical initiatives and delivering complex product enhancements from concept to production.</span></p></li><li><p>Core Languages:<span> Strong proficiency in Java, Scala, or other JVM-based language.</span></p></li><li><p>Systems Expertise:<span> Solid experience in the design and development of distributed systems.</span></p></li><li><p>Engineering Excellence:<span> Passion for clean coding, attention to detail, and a focus on software quality and maintainability.</span></p></li><li><p>Communication:<span> Strong oral and written communication skills for effective collaboration across a distributed team.</span></p></li><li><p>Autonomy:<span> Demonstrated ability to research, problem-solve, and operate independently without constant supervision.</span></p></li><li><p>Growth Mindset:<span> An open-minded approach with a desire to learn new technologies and an unwavering passion for building exceptional products.</span></p></li></ul><h2></h2><h2>You might also have:</h2><ul><li><p>Spark &amp; Ecosystem <span>Experience with using/developing Apache Spark, Apache Iceberg, or other related technologies.</span></p></li><li><p>Distributed Systems Mastery:<span> Deep experience with large-scale, distributed systems design and development, including a strong understanding of scaling, performance optimization, and scheduling.</span></p></li><li><p>SQL Expertise:<span> Experience with SQL Planners and Optimizers</span></p></li><li><p>Open-Source Contributions:<span> Prior experience as a contributor to open-source projects.</span></p></li></ul><p></p><p><b><b>Why this role matters: </b></b></p><p><span>You will tackle complex distributed systems challenges, crafting the foundational software for the control and data planes that powers CDP and keeps it running at massive scale. Working at the forefront of hybrid and multi-cloud technology, you will empower data scientists, engineers, and analysts with the tools and infrastructure they need for advanced analytics and modeling.</span></p><p></p><p><span>\\u00a0Collaboration is key, you will work alongside brilliant minds across product, data science, and engineering to drive innovation, standardize best practices, and shape the future of enterprise AI and data platforms. This is your chance to build the future of data and see your work make a global impact.</span><br /><br />\\u00a0</p><p><span>\\u00a0</span><span>The expected base salary range for this role in:</span></p><ul><li><p><span>California &amp; Washington is $184,000</span><span> - $230,000 USD</span></p></li><li><p><span>Canada is $165,000 - $206,000 CAD</span></p></li></ul><p><span>The salary will vary depending on your job-related skills, experience and location. </span><span>\\u00a0</span></p><p></p><p><b>This position is not eligible for sponsorship.</b></p><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-REMOTE</p><p>#LI-SZ1</p>","260341":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><b>About Octopai</b></p><p></p><p>Octopai is a fast-growing Data Intelligence company (Acquired by Cloudera) that empowers enterprises to understand, trust, and optimize their data. Our platform provides automated data lineage, cataloging, and discovery to accelerate analytics, improve governance, and drive business impact.</p><p>As we expand from SaaS into large-scale enterprise and on-premise deployments, we are investing in strengthening our <b>core platform infrastructure and runtime services</b> \\u2014 the foundational layer that powers Octopai\\u2019s ingestion, analysis, metadata processing, and operational execution.</p><p>We are looking for a Staff Software Engineer to help build and evolve these critical platform components.</p><p></p><p><b>Role Overview</b></p><p></p><p>As a <b>Staff Software Engineer (Core Platform, Runtime Services)</b>, you will focus on designing and developing the foundational runtime and shared services that enable Octopai\\u2019s platform to operate at scale.</p><p>This role is deeply technical, centered around building robust infrastructure primitives, runtime orchestration, platform-wide reliability, and performance improvements.</p><p>You will work on the systems that sit at the heart of Octopai\\u2019s execution engine \\u2014 supporting metadata harvesting, lineage computation, distributed processing, and enterprise workloads across SaaS and customer-managed deployments.</p><p></p><p><b>As a Staff Software Engineer you will:</b></p><p></p><ul><li>Design and implement core runtime services that power Octopai\\u2019s platform execution, analysis workflows, and operational stability.</li><li>Build shared infrastructure components used across the backend organization, including service frameworks, job execution layers, scheduling, and platform abstractions.</li><li>Improve scalability, reliability, and performance of platform services supporting metadata ingestion and lineage computation.</li><li>Develop platform capabilities for workload orchestration, lifecycle management, retries, fault handling, and resource optimization.</li><li>Partner with DevOps and Cloud teams to ensure runtime services are deployable and manageable in Kubernetes-based and enterprise environments.</li><li>Build foundations for observability, including logging, metrics, tracing, and troubleshooting tools for core services.</li><li>Ensure runtime infrastructure supports enterprise-grade requirements such as isolation, security, compliance, and predictable operations.</li><li>Contribute to architecture discussions and evolve Octopai\\u2019s core platform foundations through strong design and implementation practices.</li><li>Support engineering quality through clean architecture, code reviews, and scalable backend patterns.<br />\\u00a0</li></ul><p><b>We\\u2019re excited about you if you have:</b></p><p></p><ul><li>8\\u201312&#43; years of backend or platform engineering experience, with demonstrated impact at Staff level.</li><li>Strong expertise in building scalable backend infrastructure, runtime systems, or distributed service platforms.</li><li>Excellent programming skills in <b>C# (.NET), Java</b> and modern backend engineering practices.</li><li>Experience designing shared services that support orchestration, execution pipelines, or platform-level abstractions.</li><li>Hands-on experience with SQL and NoSQL databases (<b>SQL Server, PostgreSQL, ArangoDB</b>, or similar).</li><li>Familiarity with messaging, caching, and coordination systems (<b>Kafka, Redis</b>, etc.).</li><li>Experience operating containerized services and supporting Kubernetes-based deployments.</li><li>Strong understanding of production reliability, fault tolerance, observability, and operational best practices.</li><li>Ability to work across teams and collaborate effectively with engineering, infrastructure, and product stakeholders.</li></ul><p></p><p><b>You may also have:\\u00a0</b></p><p></p><ul><li>Experience with workflow engines, distributed job execution systems, or large-scale runtime platforms.</li><li>Background supporting hybrid SaaS &#43; enterprise/on-prem deployments.</li><li>Familiarity with performance optimization for metadata-heavy or graph-based workloads.</li><li>Knowledge of search/index infrastructure (ElasticSearch/Solr) or ingestion pipelines.</li><li>Exposure to enterprise compliance, security constraints, and deployment complexity.</li></ul><p></p><p>This role is not eligible for immigration sponsorship</p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-AC1</p><p>#LI-HYBRID</p>","251517":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Cloudera is looking for a Staff Software Engineer to join the Enterprise AI Platform team and help drive development of Cloudera\\u2019s next-generation AI and machine learning platform. You will be responsible for helping design, build, and deliver a platform that not only accelerates machine learning &amp; AI from exploration to production but also enables enterprises to create &amp; deploy Generative AI applications using foundation models with enterprise data at scale. This role requires an empathetic mindset and close collaboration with front-end/web UI engineers, data scientists, designers, and product management.</span></p><p></p><p><span>We look for &#34;The Startup Spark&#34;, a desire to create new things, dive in wherever there&#39;s a need, eagerness to make an impact as an individual, and the willingness to learn new things. You must be self-motivated, innovative, and proactive. The role offers significant opportunities for growth.</span></p><p></p><p><span>Read about the Forrester Wave Report on Cloudera&#39;s Machine Learning offerings </span><a href=\\"https://blog.cloudera.com/cloudera-named-leader-in-the-forrester-wave-notebook-based-predictive-analytics-and-machine-learning-q3-2020/\\" target=\\"_blank\\"><u>here</u></a><span>.</span></p><p></p><p><b>As a Staff Software Engineer you will:</b></p><ul><li><p><span>Help build the leading platform for AI and Machine Learning in the enterprise.</span></p></li><li><p><span>Design, code, and implement elegant, scalable, enterprise-quality AI inference services powered by machine learning models.</span></p></li><li><p><span>Design and Develop AI Model Registry and AI applications\\u00a0</span></p></li><li><p><span>Work to enhance developer velocity and team agility.</span></p></li><li><p><span>Build strong relationships and collaborate with platform and front-end engineers, quality engineers, UX designers, as well as Product Management, Field, Professional Services, and other partners.</span></p></li></ul><p></p><p><b>We are excited if you have (Required Experience):</b></p><ul><li><p><span>Bsc/Msc in related field or equivalent experience</span></p></li><li><p><span>10&#43; years of experience building scalable microservices or applications using Go, Python, Node.js, C# or Java</span></p></li><li><p><span>Experience building and deploying AI Inference and Generative AI applications.</span></p></li><li><p><span>Experience with foundation models, prompt engineering, fine-tuning, semantic search and Retrieval-Augmented Generation (RAG) using vector databases such as Pinecone, Milvus, etc.</span></p></li><li><p><span>Experience with microservices design and development (Go, GRPC, SQL) on Kubernetes</span></p></li><li><p><span>Demonstrate ability to go deep into technology and complex distributed systems</span></p></li><li><p><span>Experience in crafting high-level and low-level design</span></p></li><li><p><span>Experience in building highly scalable, robust and secure enterprise applications</span></p></li><li><p><span>Self-driven and motivated, with a strong sense of ownership and craftsmanship</span></p></li><li><p><span>Strong written and verbal communication skills.</span></p></li></ul><p></p><p><b>You may also have:</b></p><ul><li><p><span>Experience with HuggingFace, Nvidia AI frameworks and Nim models.</span></p></li><li><p><span>Experience with AI/ML orchestration software KServe, Knative, Kubeflow.</span></p></li><li><p><span>Experience with building AI applications with machine learning models using data science and machine learning tools (Python, Tensorflow, Spark, MLflow, R, etc.)</span></p></li><li><p><span>Experience with at least one of the following Cloud technologies - Google Cloud Platform (GCP), Amazon Web Services (AWS), Microsoft Azure</span></p></li><li><p><span>Good to have some full-stack experience with React, HTML, CSS.</span></p></li><li><p><span>Experience with data science and machine learning tools (R, Python, Tensorflow, Spark)</span></p></li><li><p><span>Deep understanding of cloud-based networking</span></p></li><li><p><span>Experience using Big Data technologies like Spark, Hive etc.</span></p></li><li><p><span>Proven track record of collaborating with agile teams across geographically dispersed locations</span></p></li></ul><p></p><p><b>This role is not eligible for immigration sponsorship or relocation.</b></p><p></p><p><i>The anticipated annual base salary range for this position is: </i></p><ul><li><p><i>California: $184,000- $230,000</i></p></li></ul><p></p><p><i>Individual compensation within the published range is determined by the candidate&#39;s skills, experience, qualifications, and primary work location. In addition to base pay, sales roles are eligible for Cloudera&#39;s commission plan, while non-sales roles are eligible for the corporate incentive plan. All employees receive a comprehensive benefits package.</i></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-HYBRID</p><p>#LI-BV1</p>","260845":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><b><span>The Data Platform Pillar is the bedrock of Cloudera\\u2019s technology, where we design and build the core components that let our customers store, manage, and process data with unmatched scalability, security, and performance. </span> </b><br /><br />Join the forefront of Big Data innovation at Cloudera! We are seeking a visionary Staff Engineer to take ownership of the next generation of our enterprise-grade Apache Iceberg distribution. This is a rare opportunity to architect, design, and scale the system that powers data processing for the world&#39;s largest companies, managing petabytes of data across thousands of nodes. If you are an experienced leader in distributed systems and data processing, ready to drive massive impact and define the future of Data Engineering, your mission starts here.</p><p></p><p>This is your chance to architect solutions that are responsible for managing Petabyte (PB) sized datasets across multi-cloud environments. You will gain deep technical experience in complex big data use cases and seize the unique opportunity to become a core contributor to the vibrant Apache Iceberg open-source community and directly influence the project&#39;s evolution.</p><p></p><p><b>As a Staff Engineer you will:</b></p><ul><li><p>Drive the future of data architecture by becoming a core contributor to Apache Iceberg, the open-source project defining modern data lakes.</p></li><li><p>Bring performance improvements to all of the engines in the Cloudera stack, by implementing new features in Iceberg and working with other teams to leverage them during queries.</p></li><li><p>Work with Product Managers and Customers to determine ways Iceberg can be improved for Modern Data Lakes.</p></li><li><p>Develop new features in Java on a modern platforms</p></li><li><p>Gain a solid understanding and deep technical knowledge of components across the Cloudera stack, but focusing on Iceberg, which you can utilize in your daily tasks.</p></li><li><p>Get to work on massive-scale distributed systems, spanning from 100s to 1000s of nodes in production clusters, leveraging Iceberg&#39;s capabilities for handling PB-scale data architectures.</p></li><li><p>Debug system level deployment issues, root cause analysis, perform system test analysis and resolve failures.</p></li><li><p>Collaborate with other team members and stakeholders.</p></li></ul><p></p><p><b>We are excited if you have (Required Experience):</b></p><ul><li><p>Bachelor\\u2019s degree in Computer Science or equivalent, and 6&#43; years of experience; OR Master\\u2019s degree and 4-6 years of experience; OR PhD and 2-4 years of experience</p></li><li><p>Hands-on programmer with solid data-structures and algorithms</p></li><li><p>Experience with systems design, development</p></li><li><p>Strong understanding of at least one of the following languages: Java, Scala, C&#43;&#43;, Python. And interested to learn the languages we\\u2019re using.</p></li><li><p>Passionate about programming, clean coding habits, attention to detail, and focus on quality</p></li><li><p>Strong ability to research and solve problems independently without constant supervision</p></li><li><p>Ability to work effectively both independently and as part of an international and virtual team</p></li><li><p>Excellent communication and collaboration skills</p></li><li><p>(Most importantly) Open-minded attitude, desire to learn new things and build great products</p></li></ul><p></p><p><b>You might have:</b></p><ul><li><p>Experience with using/developing Apache Iceberg or other related technologies</p></li><li><p>Experience (or demonstrated interest) in distributed computing or high availability systems</p></li><li><p>Contributions to open-source projects</p></li><li><p>Experience with SQL optimization, from analyzing query plans to implementing optimization in SQL engines</p></li></ul><p></p><p><b><b>Why this role matters:\\u00a0</b></b></p><p></p><p><span>You will tackle complex distributed systems challenges, crafting the foundational software for the control and data planes that powers CDP and keeps it running at massive scale. Working at the forefront of hybrid and multi-cloud technology, you will empower data scientists, engineers, and analysts with the tools and infrastructure they need for advanced analytics and modeling.</span></p><p></p><p><span>\\u00a0Collaboration is key, you will work alongside brilliant minds across product, data science, and engineering to drive innovation, standardize best practices, and shape the future of enterprise AI and data platforms. This is your chance to build the future of data and see your work make a global impact.</span></p><p></p><p><b>This role is not eligible for immigration sponsorship.</b><br /><br />\\u00a0</p><p><b>The expected base salary range for this role in</b></p><ul><li><p><b>Washington is $184,000 - $230,000</b></p></li></ul><p><b>The salary will vary depending on your job-related skills, experience and location</b><br /><br />\\u00a0</p><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-SZ1</p><p>#LI-REMOTE</p>","260055":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>We are seeking a Staff Engineer with a full-stack mentality to join our Public Cloud team. This is a mission-critical role within an impactful team of five, focused on the Cloudera Data Platform across the three major cloud providers (AWS, Azure, and GCP).</span></p><p></p><p>We need a seasoned Fullstack Engineer with Java expertise, who views software through the lens of the entire software development lifecycle. Y<span>ou will be a &#34;self-enabler&#34; who takes full ownership of features and architectural designs, in addition to the coding, </span><span>ownership of features and architectural designs, r</span>elease process, and takes testing and quality gates seriously.</p><p></p><p><span>Our ideal candidate will go to extremes when it comes to complex issues, such as starting up a VM/container to debug, and understands that a great profile involves both coding and deployment.</span></p><p></p><p><b>As a Staff Software Engineer, you will...</b></p><ul><li><p>Lead Image Management:<span> Drive the development of tooling for VM image creation, management, and release across AWS, Azure, and GCP.</span></p></li><li><p>Architectural Design:<span> Provide high-level architectural planning and contribute at a Senior Staff level by independently leading major features.</span></p></li><li><p>Own Test Frameworks:<span> Take ownership of and contribute to the Java-based image validation and test automation frameworks.</span></p></li><li><p>Drive Configuration as Code:<span> Manage infrastructure and configuration using tools like Ansible, Salt, and Packer.</span></p></li><li><p>Collaborate and Innovate:<span> Work within a diverse set of tasks to deliver scalable, high-availability solutions for large-scale distributed systems.</span></p></li></ul><p></p><p><b>We are excited if you have...</b></p><ul><li><p>Strong Generalist Background:<span> A robust development background combined with DevOps and Fullstack experience.</span></p></li><li><p>Java Expertise:<span> Significant experience with Java, specifically for developing test code and automation frameworks (note: this is a generalist role, not a pure Java Developer role).</span></p></li><li><p>Programming Skills:<span> Proficiency in </span>Python <span>and/or</span> Go<span>.</span></p></li><li><p>Cloud &amp; Infrastructure Proficiency:<span> Hands-on experience with at least one major cloud provider (AWS/Azure/GCP) and configuration management tools such as </span>Ansible, Salt, or Packer<span>.</span></p></li><li><p>Distributed Systems Knowledge:<span> An understanding of large-scale systems design, including scaling, replication, consistency, and high availability.</span></p></li><li><p>Self-Driven Leadership:<span> The ability to act as a &#34;self-enabler,&#34; taking individual ownership of complex features without needing constant tech-lead supervision.</span></p></li><li><p>Proven ability <span>to diagnose and </span>resolve<span> </span>challenging issues<span> in large-scale, distributed cloud environments.</span></p></li></ul><p></p><p><b>You may also have...</b></p><ul><li><p>Linux &amp; DevOps Mastery:<span> Deep knowledge of Linux environments and a &#34;DevOps&#34; mindset where you take responsibility for the full lifecycle, including deployment.</span></p></li><li><p>Experience with large-scale, distributed systems design and development with an understanding of scaling, performance, and scheduling.</p></li><li><p>Proactive problem-solving ability, to work<span> independently, identify, define, and drive projects forward with minimal guidance.</span></p></li><li><p>Excellent communication skills<span> and the ability to collaborate with cross-functional teams across different geographies.</span></p></li><li><p>Passion for coaching and developing team members<span> to achieve their full potential.</span></p></li></ul><p></p><p>This role is not eligible for immigration sponsorship.\\u00a0\\u00a0</p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-VG1</p><p>#LI-HYBRID</p>","260345":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p></p><p><b>About Octopai</b></p><p></p><p>Octopai is a fast-growing Data Intelligence company (Acquired by Cloudera) that empowers enterprises to understand, trust, and optimize their data. Our platform provides automated data lineage, cataloging, and discovery to accelerate analytics, improve governance, and drive business impact.</p><p>As we expand our platform capabilities and evolve our metadata foundations and next-generation APIs, we are looking for a Staff Software Engineer to help shape Octopai\\u2019s modeling and API layer \\u2014 the core systems that power lineage, catalog, governance, and integrations across enterprise environments.</p><p></p><p><b>Role Overview</b></p><p></p><p>As a <b>Staff Software Engineer (Modeling, APIs)</b>, you will focus on designing and building the metadata model and API infrastructure at the heart of Octopai\\u2019s platform.</p><p>This role is deeply technical, centered on creating scalable domain representations of data assets, transformations, relationships, and governance concepts \\u2014 and exposing them through robust, secure, enterprise-grade APIs.</p><p>You will work closely with backend engineers, platform teams, and product stakeholders to ensure Octopai\\u2019s modeling and API systems remain consistent, extensible, and ready for both SaaS and on-prem deployments.</p><p></p><p></p><p><b>As a Staff Software Engineer you will:</b></p><p></p><ul><li>Design and implement Octopai\\u2019s core metadata modeling systems, representing complex relationships across data assets, pipelines, lineage, and governance.</li><li>Build and evolve scalable, secure APIs that power Octopai\\u2019s platform functionality and partner integrations.</li><li>Drive improvements in API versioning, extensibility, backward compatibility, and developer experience.</li><li>Collaborate with Product and Engineering teams to translate platform requirements into robust modeling and API solutions.</li><li>Ensure modeling and API layers meet enterprise-grade requirements for performance, reliability, and security.</li><li>Support integration frameworks and external consumption patterns, including SDKs and documentation standards.</li><li>Partner with infrastructure teams to ensure APIs are deployable, observable, and maintainable across SaaS and customer-managed environments.</li><li>Contribute to engineering quality through strong architecture practices, code reviews, and scalable backend patterns.</li></ul><p></p><p><b>We\\u2019re excited about you if you have:\\u00a0</b></p><p></p><ul><li>8\\u201312&#43; years of backend engineering experience, with demonstrated impact at Staff level.</li><li>Strong expertise in building API-first backend systems or platform-level domain infrastructure.</li><li>Excellent programming skills in <b>C# (.NET), Java</b> and modern backend engineering practices.</li><li>Proven experience designing and maintaining RESTful APIs and distributed backend services.</li><li>Strong understanding of data modeling principles, metadata-driven architectures, or domain-driven design (DDD).</li><li>Hands-on experience with SQL and NoSQL databases (<b>SQL Server, PostgreSQL, ArangoDB</b>, or similar).</li><li>Familiarity with messaging and caching systems (<b>Kafka, Redis</b>, etc.).</li><li>Understanding of authentication/authorization models (SSO, RBAC) and enterprise security principles.</li><li>Strong communication and collaboration skills across engineering, product, and partner-facing teams.</li></ul><p></p><p><b>You may also have:\\u00a0</b></p><p></p><ul><li>Experience in data lineage, metadata management, cataloging, or governance platforms.</li><li>Background with graph databases and modeling highly connected data ecosystems.</li><li>Familiarity with OpenAPI standards, API gateways, and SDK generation.</li><li>Knowledge of search/index systems (ElasticSearch/Solr) and metadata discovery patterns.</li><li>Experience supporting hybrid SaaS &#43; on-prem enterprise deployments.</li></ul><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-AC1</p><p>#LI-HYBRID</p>","251473":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>The Mission: Engineering Resilience for Cloudera Data Flow (CDF) to Run Anywhere</p><p></p><p><span>Data is dynamic, and your processing services must be just as agile. As a Senior Software Engineer in Test on the Cloudera DataFlow team, you will be on a critical mission to ensure the quality, reliability, and deployment of our next-generation data service, Cloudera DataFlow (CDF). You will participate in and drive the testing strategy for the entire CDF platform.</span></p><p></p><p><span>This critical service must be rigorously tested to be capable of running anywhere, from fully air-gapped, on-premise servers to the most complex public cloud environments.</span></p><p></p><p><span>We are advancing a massive-scale platform. If you are obsessed with designing and executing highly reliable, distributed data flow systems testing that ensures efficient, scalable workloads across any environment, this is your perfect opportunity.</span></p><p></p><p><b>This role is not eligible for immigration sponsorship or relocation.</b></p><p></p><p><b>The Impact You\\u2019ll Make</b></p><ul><li><p>Testing &amp; Quality Assurance: <span>You will be responsible for enhancing and maintaining our existing </span>CI/CD pipelines and Java-based automated test suites<span>, working with modern, </span>Kubernetes-based test infrastructure<span>. Your goal is to transform these assets into an advanced validation engine, crucial for the swift and dependable release of Cloudera Data Flow, thereby owning the Testing &amp; Quality Assurance domain.</span></p></li><li><p>Technical Expertise &amp; Troubleshooting: <span>Become a subject matter expert in data flow management. When distributed systems fail at scale, you lead the charge. You will perform deep-dive troubleshooting and </span>Root Cause Analysis <span>on complex, system-level failures that only emerge in high-throughput environments.</span></p></li><li><p>Bake-In Excellence:<span> You will work synchronously with the broader engineering team to </span>bake quality into the code from day one<span>, ensuring that testability is a first-class citizen in our software design.</span></p></li></ul><p></p><p><b>Your Technical DNA</b></p><ul><li><p>Bsc/Msc in related field or equivalent experience</p></li><li><p>Java Proficiency:<span> You write clean, performant code and understand the nuances of the Java ecosystem in a distributed context.</span></p></li><li><p>Kubernetes &amp; Docker Mastery:<span> You treat containerization and orchestration as the foundation of modern deployments. You know how to simulate complex cluster failures to test system limits.</span></p></li><li><p>Validation Architect:<span> You have a proven track record of designing </span>complex test plans and automated methodologies<span> that integrate seamlessly into robust CI/CD pipelines.</span></p></li><li><p>Testing &amp; Development:<span> Familiarity with diverse test frameworks (e.g., JUnit, TestNG, Mockito) for various testing levels, and practical experience developing and debugging software in Linux environments.</span></p></li><li><p>Communication:<span> Excellent professional proficiency in written and spoken English, essential for clear documentation and seamless collaboration within distributed teams.</span></p></li></ul><p></p><p><b>What Makes You Stand Out</b></p><ul><li><p>Data flow management experience:<span> You\\u2019ve worked with </span>Apache NiFi<span> or similar engines and understand complex data flow pipelines.</span></p></li><li><p>Cloud &amp; Infrastructure:<span> You\\u2019ve deployed to </span>AWS, Azure, or GCP<span> and have used </span>Ansible or Terraform<span> to treat &#34;Infrastructure as Code&#34; as a creative discipline.</span></p></li><li><p>The &#34;Quality First&#34; Mindset:<span> You have a passion for building tools that break things so that our customers never do.</span></p></li><li><p><span>Hands-on experience with </span>Python<span> is considered an advantage.</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-AC1</p><p>#LI-HYBRID</p>","260798":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Cloudera is looking for a Staff Software Engineer to join the Enterprise AI Platform team and help drive development of Cloudera\\u2019s next-generation AI and machine learning platform. You will be responsible for helping design, build, and deliver a platform that not only accelerates machine learning &amp; AI from exploration to production but also enables enterprises to create &amp; deploy Generative AI applications using foundation models with enterprise data at scale. This role requires an empathetic mindset and close collaboration with front-end/web UI engineers, data scientists, designers, and product management.</span></p><p></p><p><span>We look for &#34;The Startup Spark&#34;, a desire to create new things, dive in wherever there&#39;s a need, eagerness to make an impact as an individual, and the willingness to learn new things. You must be self-motivated, innovative, and proactive. The role offers significant opportunities for growth.</span></p><p></p><p><span>Read about the Forrester Wave Report on Cloudera&#39;s Machine Learning offerings </span><a href=\\"https://blog.cloudera.com/cloudera-named-leader-in-the-forrester-wave-notebook-based-predictive-analytics-and-machine-learning-q3-2020/\\" target=\\"_blank\\"><u>here</u></a><span>.</span></p><p></p><p><b>As a Staff Software Engineer you will:</b></p><ul><li><p><span>Help build the leading platform for AI and Machine Learning in the enterprise.</span></p></li><li><p><span>Design, code, and implement elegant, scalable, enterprise-quality AI inference services powered by machine learning models.</span></p></li><li><p><span>Design and Develop AI Model Registry and AI applications\\u00a0</span></p></li><li><p><span>Work to enhance developer velocity and team agility.</span></p></li><li><p><span>Build strong relationships and collaborate with platform and front-end engineers, quality engineers, UX designers, as well as Product Management, Field, Professional Services, and other partners.</span></p></li></ul><p></p><p><b>We are excited if you have (Required Experience):</b></p><ul><li><p><span>Bsc/Msc in related field or equivalent experience</span></p></li><li><p><span>10&#43; years of experience building scalable microservices or applications using Go, Python, Node.js, C# or Java</span></p></li><li><p><span>Experience building and deploying AI Inference and Generative AI applications.</span></p></li><li><p><span>Experience with foundation models, prompt engineering, fine-tuning, semantic search and Retrieval-Augmented Generation (RAG) using vector databases such as Pinecone, Milvus, etc.</span></p></li><li><p><span>Experience with microservices design and development (Go, GRPC, SQL) on Kubernetes</span></p></li><li><p><span>Demonstrate ability to go deep into technology and complex distributed systems</span></p></li><li><p><span>Experience in crafting high-level and low-level design</span></p></li><li><p><span>Experience in building highly scalable, robust and secure enterprise applications</span></p></li><li><p><span>Self-driven and motivated, with a strong sense of ownership and craftsmanship</span></p></li><li><p><span>Strong written and verbal communication skills.</span></p></li></ul><p></p><p><b>You may also have:</b></p><ul><li><p><span>Experience with HuggingFace, Nvidia AI frameworks and Nim models.</span></p></li><li><p><span>Experience with AI/ML orchestration software KServe, Knative, Kubeflow.</span></p></li><li><p><span>Experience with building AI applications with machine learning models using data science and machine learning tools (Python, Tensorflow, Spark, MLflow, R, etc.)</span></p></li><li><p><span>Experience with at least one of the following Cloud technologies - Google Cloud Platform (GCP), Amazon Web Services (AWS), Microsoft Azure</span></p></li><li><p><span>Good to have some full-stack experience with React, HTML, CSS.</span></p></li><li><p><span>Experience with data science and machine learning tools (R, Python, Tensorflow, Spark)</span></p></li><li><p><span>Deep understanding of cloud-based networking</span></p></li><li><p><span>Experience using Big Data technologies like Spark, Hive etc.</span></p></li><li><p><span>Proven track record of collaborating with agile teams across geographically dispersed locations</span></p></li></ul><p></p><p><b>This role is not eligible for immigration sponsorship or relocation.</b></p><p></p><p><i>The anticipated annual base salary range for this position is: </i></p><ul><li><p><i>California: $184,000- $230,000</i></p></li></ul><p></p><p><i>Individual compensation within the published range is determined by the candidate&#39;s skills, experience, qualifications, and primary work location. In addition to base pay, sales roles are eligible for Cloudera&#39;s commission plan, while non-sales roles are eligible for the corporate incentive plan. All employees receive a comprehensive benefits package.</i></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-BV1</p><p>#LI-HYBRID</p>","260809":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>IT<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>At Cloudera, we believe that data can make what is impossible today, possible tomorrow. We empower organizations to transform complex data into clear and actionable outcomes. Join us in our mission to harness the power of data.</span></p><p></p><p><span>We are seeking a talented and curious </span><b>Senior Data Scientist </b><span>to join our fast-paced, data-driven organization. In this role, you will design and deliver AI-powered systems and applications that accelerate decision-making and enhance operational excellence.</span></p><p></p><p><span>You will combine strong statistical foundations, advanced programming expertise, and modern Generative AI techniques to build scalable, production-ready solutions. This is a builder-focused role. You will move beyond analysis to develop internal copilots, AI-enabled workflows, and reusable platform components that embed intelligence directly into business processes.</span></p><p></p><p><span>Our work empowers leadership and operational teams by creating measurable, AI-enabled capabilities. We seek a thoughtful and pragmatic innovator who is enthusiastic about GenAI, disciplined experimentation, and building durable internal AI infrastructure.</span></p><p></p><p><b>To succeed in this role, you will demonstrate technical depth, intellectual curiosity, and a strong builder mindset<span>:</span></b></p><ul><li><p><b>Generative AI &amp; LLM Engineering</b><span>: Hands-on experience working with large language models (LLMs) and modern AI tooling. This includes prompt design, structured output generation, retrieval-augmented generation (RAG), evaluation strategies, and workflow automation. Ability to translate GenAI capabilities into reliable, enterprise-ready solutions that integrate with existing systems and data sources.</span></p></li><li><p><b>AI Application Development Experience</b><span>: rapidly prototyping and iterating on internal applications, copilots, or AI-enabled workflow tools. Comfortable evolving prototypes into maintainable, production-grade solutions. Familiarity with modern development frameworks (e.g., Streamlit, Gradio, FastAPI, or similar) is beneficial.</span></p></li><li><p><b>Platform-Oriented Thinking</b><span>: Demonstrated ability to design reusable components such as shared prompt libraries, retrieval pipelines, evaluation frameworks, and standardized integration patterns that enable scalable AI adoption.</span></p></li><li><p><b>Data Science &amp; Machine Learning Expertise</b><span>: Proficiency in Python (or R) for data preparation, feature engineering, statistical modeling, and machine learning. Experience with core data science libraries (e.g., Pandas, NumPy, scikit-learn) and a solid understanding of supervised and unsupervised learning methods.</span></p></li><li><p><b>Strong Mathematical and Statistical Foundation</b><span>: Deep understanding of probability, statistical inference, experimentation, and quantitative reasoning to ensure model robustness and reliability.</span></p></li><li><p><b>SQL &amp; Data Fluency</b><span>: Strong understanding of relational databases and the ability to quickly learn new schemas and data environments. Comfortable writing efficient, production-grade SQL to support modeling, experimentation, and AI-enabled applications.</span></p></li><li><p><b>Exceptional Communication Skills</b><span>: Ability to translate complex business challenges into technical solutions and clearly communicate findings, trade-offs, and recommendations to both technical and non-technical stakeholders.</span></p></li><li><p><b>Collaborative Development Experience</b>:<span> Experience working in collaborative environments such as Cloudera Data Science Workbench, Jupyter, Zeppelin, or similar platforms.</span></p></li><li><p><b>GitHub Proficiency</b>:<span> Experience using version control to support collaboration, code review, documentation, and long-term maintainability.</span></p></li></ul><p></p><p><b>As a Senior Data Scientist, you will:</b></p><p><span>You will apply rigorous analytical thinking and modern AI capabilities to design, build, and scale high-impact solutions.</span></p><ul><li><p><span>Design, develop, and deploy GenAI-powered internal applications, copilots, and workflow accelerators.</span></p></li><li><p><span>Build reusable AI components, including retrieval pipelines, structured prompting patterns, orchestration workflows, and evaluation harnesses.</span></p></li><li><p><span>Design retrieval strategies that connect LLMs to trusted internal knowledge sources, ensuring grounded and reliable outputs.</span></p></li><li><p><span>Develop and maintain statistical and machine learning models to support automation, optimization, forecasting, and classification use cases.</span></p></li><li><p><span>Implement evaluation and validation frameworks to measure quality, accuracy, and consistency of AI-driven systems.</span></p></li><li><p><span>Partner cross-functionally to identify high-value opportunities for AI enablement across the organization.</span></p></li><li><p><span>Create reusable datasets, feature pipelines, and experimentation frameworks to support iterative development.</span></p></li><li><p><span>Uphold high standards for quality, reliability, and responsible AI practices.</span></p></li><li><p><span>Contribute to peer review processes to ensure technical rigor and maintainability.</span></p></li><li><p><span>Document methodologies, assumptions, and implementation details to ensure transparency and reproducibility.</span></p></li></ul><p><b>\\u00a0\\u00a0</b></p><p><b>We are excited if you have (Required Experience):</b></p><ul><li><p><span>Hands-on experience building applications or workflows powered by large language models (LLMs).</span></p></li><li><p><span>Evidence of a builder mindset through shipped AI tools, internal platforms, or automation solutions.</span></p></li><li><p><span>Demonstrated experience applying machine learning techniques in production or enterprise environments.</span></p></li><li><p><span>5&#43; years of relevant experience in Data Science, Machine Learning, or AI-focused roles.</span></p></li><li><p><span>Strong curiosity for emerging AI technologies and the ability to evaluate and adopt them responsibly.</span></p></li><li><p><span>Academic background in a quantitative discipline such as Statistics, Mathematics, Computer Science, Engineering, Economics, or a related field.</span></p></li></ul><p></p><p><b>You may also have: (Preferred Qualifications)</b></p><ul><li><p><span>Experience with vector databases, embedding models, or semantic retrieval systems.</span></p></li><li><p><span>Experience designing internal AI platforms or shared enablement frameworks.</span></p></li><li><p><span>Familiarity with API-driven architectures and integrating AI capabilities into enterprise systems.</span></p></li><li><p><span>Exposure to responsible AI practices, governance frameworks, or model lifecycle management.</span></p></li></ul><p></p><p><b>This role is not eligible for immigration sponsorship.</b></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p><span>#LI-MH2</span></p><p><span>#LI-Remote</span></p>","260715":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>IT<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>Cloudera Data Engineers power our Analytics and AI/ML initiatives by building scalable, high-performance data pipelines. In this role, you will lead our transition from traditional manual coding to AI-orchestrated development (Vibe Coding), architecting next-gen data pipelines and GenAI applications at unprecedented speed.</p><p></p><p>You will focus on modernizing development workflows and building GenAI-powered self-service tools that empower the business to resolve data needs independently. By designing robust, AI-first data management processes on Cloudera\\u2019s native platform, you will ensure data integrity while creating a blueprint for both internal efficiency and external customer success.</p><p></p><p><b>As a Senior Data Engineer you will:</b></p><ul><li><p>Design and implement robust system architectures for real-time, near real-time, and batch processing data flows to meet the operational demands of complex business systems.</p></li><li><p>Master &#34;Vibe Coding&#34; and AI-orchestrated development to accelerate the delivery of new data pipelines and GenAI applications, reducing the end-to-end development lifecycle from days to hours.</p></li><li><p>Design and deploy GenAI-powered &#34;Self-Service&#34; tools, including automated documentation generators and natural language interfaces, to empower business users and reduce routine engineering requests.</p></li><li><p>Standardize AI-first engineering workflows across the team to ensure high-quality, auto-validated, and well-documented code delivery.</p></li><li><p>Develop and implement data transformations to enrich and provision data, following established specifications and standards while utilizing AI-first workflows.</p></li><li><p>Partner with data owners to ensure seamless, reliable data ingestion for both traditional analytics and GenAI-powered applications.</p></li><li><p>Collaborate with Data Architects, Operational Architects, and Data Analysts to understand the data and operational requirements across different business units.</p></li><li><p>Implement monitoring and CI/CD automation processes to track data quality and ensure the reliability of AI-supported data services.</p></li></ul><p></p><p><b>We are excited if you have (Required Experience):</b></p><ul><li><p>5&#43; years of experience as a Data Engineer.</p></li><li><p>Solid skills in System Design for diverse data architectures, including expert-level knowledge of batch processing and real-time/streaming processing.</p></li><li><p>Proven experience with AI-first approaches and &#34;Vibe Coding,&#34; with a demonstrated ability to deliver production-ready data pipelines using AI orchestration rather than purely manual coding.</p></li><li><p>Deep proficiency with AI-assisted coding tools, including Cursor, GitHub Copilot, or Gemini, to modernize and accelerate engineering workflows.</p></li><li><p>Proficient in coding with Python (primary) and SQL, with experience in ETL and data processing.</p></li><li><p>Hands-on experience with Distributed Systems and Big Data technologies, including Spark and the Hadoop ecosystem (Hive, Impala, Kafka).</p></li><li><p>Proven proficiency in Data Modeling using industry best practices (e.g., Kimball, Inmon) to ensure data integrity.</p></li><li><p>Ability to monitor critical data pipelines for quality and resolve any issues effectively.</p></li><li><p>Strong communication skills, both written and verbal.</p></li><li><p>Education: Bachelor\\u2019s degree in Computer Science, Engineering, Information Systems, or a related field (or equivalent experience).</p></li></ul><p></p><p><b>You may also have:</b></p><ul><li><p>Experience supporting GenAI applications from the Data Engineering side, including managing vector databases, RAG (Retrieval-Augmented Generation) pipelines, or LLM data orchestration.</p></li><li><p>Experience with Apache Airflow or Apache NiFi.</p></li><li><p>Expertise in optimizing data storage using HDFS/Parquet/Avro, Kudu, or HBase.</p></li></ul><p></p><p><b>This role is not eligible for immigration sponsorship or relocation</b></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-MH2</p><p>#LI-REMOTE</p>","260762":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>The Cloudera Partner Sales Manager (PSM) is a critical member of our field sales organization.\\u00a0 Our PSM\\u2019s are responsible for coordinating and orchestrating all partner engagement at prospect and customer accounts.\\u00a0 PSM\\u2019s are revenue focused and carry a bookings number for partner-influenced deals in their assigned regions.\\u00a0</span></p><p></p><p>Responsibilities:</p><ul><li><p><span>Drive proactive sales opportunity generation, pipeline management and deal closure with partners.</span></p></li><li><p><span>Align with assigned sales teams to develop a regional partner growth strategy that will ensure software bookings growth goals are achieved.</span></p></li><li><p><span>Develop a regional partner map, outlining current partner capabilities, capacity and gaps.</span></p></li><li><p><span>Build a regional partner business plan with quantified goals and milestones to achieve partner-influenced revenue metrics.</span></p></li><li><p><span>Identify, recruit and onboard key local partners required to meet/exceed plan goals.</span></p></li><li><p><span>Align with Cloudera\\u2019s corporate Business Development team to execute strategic partner GTM plays</span></p></li><li><p><span>Facilitate the development of advanced partner solutions to drive revenue growth</span></p></li><li><p><span>Maintain and report an accurate partner sales forecast in SFDC with 4X pipeline coverage.</span></p></li><li><p><span>Manage regular business reviews between Cloudera and priority partners.</span></p></li></ul><p></p><p>Desired Skills and Qualities:</p><ul><li><p><span>Minimum 8&#43; years\\u2019 experience in direct and channel sales.</span></p></li><li><p><span>Strong understanding of the big data software business.</span></p></li><li><p><span>Proven channel sales /alliance experience with quantifiable results building the field execution with key partners.</span></p></li><li><p><span>Must possess a quantifiable record of success in enterprise technology sales, with a demonstrated ability to meet or exceed sales objectives and the ability to generate new business through partners.</span></p></li><li><p><span>Must understand complex sales process, build consensus and be adept at developing sponsorship to drive sales and technical certification results at multiple levels.</span></p></li><li><p><span>Direct experience creating and executing partner business plans with both Global and regional sized partners.</span></p></li><li><p><span>Ability to set priorities, focus on details and motivate internal and external teams to deliver agreed upon goals.</span></p></li><li><p><span>Ability to lead teams and projects through influence rather than direction.</span></p></li><li><p><span>Stand out communications skills and high energy level.</span></p></li><li><p><span>Experience working in both start-up and larger company environments, and with partners of different sizes.</span></p></li><li><p><span>BA/BS degree required. Technical competence strongly preferred.</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p>","260782":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>The Data Platform Pillar is the bedrock of Cloudera\\u2019s technology, where we design and build the core components that let our customers store, manage, and process data with unmatched scalability, security, and performance.\\u00a0</p><p><br />We are seeking passionate engineers to join our Public Cloud / R&amp;D Core team and contribute to groundbreaking projects. As a Staff Engineer, you will work in various areas that empower multi and hybrid cloud data management capabilities. This role encompasses a highly technical role, offering a unique balance for individuals seeking diverse challenges.</p><p></p><p><b>As a Senior Staff Engineer, you will:</b></p><ul><li><p>Lead the design and architecture of complex, large-scale cloud services that form the backbone of our multi-cloud and hybrid data management platform.</p></li><li><p>Develop and implement core components, tackling challenges in areas like data governance, security, and distributed systems.</p></li><li><p>Drive technical innovation by prototyping and evaluating new technologies, cloud-native solutions to solve complex customer problems.</p></li><li><p>Mentor and guide other engineers, fostering a culture of technical excellence, collaboration, and continuous improvement within the team.</p></li><li><p>Collaborate with product managers, and other engineering teams to design solutions and architecture to deliver high-quality, scalable, and resilient solutions.</p></li></ul><p></p><p><b>We are excited about you if you have (Required Experience):</b></p><ul><li><p>MSc/BSc degree in computer science or equivalent industry experience.</p></li><li><p>Demonstrated experience in large scale distributed projects</p></li><li><p>Strong background in public cloud (AWS, GCP, Azure), with expertise in security, infrastructure provisioning, containerization, and service enablement.</p></li><li><p>Advanced Java programming skills</p></li><li><p>Solid knowledge of Linux environments, networking, virtual machines and container technologies (e.g., Docker) and CI/CD solutions like Jenkins, Github Actions.</p></li><li><p>Experience with the full software development lifecycle, including production operations, monitoring, alerting, and participating in an on-call rotation for the services you build.</p></li><li><p>You are a proactive problem-solver who can independently identify, define, and drive projects forward with minimal guidance.</p></li><li><p>Proven ability to diagnose and resolve challenging issues in large-scale, distributed cloud environments.</p></li><li><p>Excellent communication skills and the ability to collaborate with cross-functional teams across different geographies.</p></li><li><p>Passion for coaching and developing team members to achieve their full potential.</p></li></ul><p></p><p><b>You may also have:</b></p><ul><li><p>Experience in Go, Python and Typescript is a plus.</p></li></ul><p></p><p><b>This role is not eligible for immigration sponsorship.</b></p><p></p><p><b>The expected base salary range for this role in</b></p><ul><li><p><b>California $213,000-$266,000</b></p></li></ul><p></p><p><b>The salary will vary depending on your job-related skills, experience and location</b></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-REMOTE</p><p>#LI-SZ1</p>","260363":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Director<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Cloudera Data Engineering is the next-generation cloud-native service that helps our customers run large-scale data engineering workflows made up of industry-standard big data processing frameworks like Apache Spark, Apache Airflow, Iceberg with just a few clicks, across both on-premises and public cloud environments.</span></p><p></p><p><a href=\\"https://www.cloudera.com/products/data-engineering.html?utm_source&#61;chatgpt.com\\" target=\\"_blank\\"><u>Cloudera Data Engineering</u></a><span> is a next-generation cloud-native service that enables customers to run large-scale data engineering workflows using industry-standard big data technologies such as Apache Spark, Apache Airflow, and Apache Iceberg\\u00a0 with just a few clicks across both on-premises and public cloud environments.</span></p><p></p><p><span>We are seeking a Principal Staff Engineer with a strong technical background in the data infrastructure space to lead the Cloudera Data Engineering experience for all customers using Cloudera Data Engineering Spark, Airflow, and Lakehouse. This high-impact IC role offers the opportunity to shape the future of Cloudera\\u2019s Data Engineering and Lakehouse\\u00a0 products across multiple cloud environments, impacting thousands of customers worldwide.</span></p><p></p><p><b>This role is not eligible for immigration sponsorship or relocation.</b></p><p></p><p><b><b>As a Principal Software Engineer you will:</b></b></p><ul><li><p><span>Drive the multi-year technical roadmap and architectural vision for Cloudera Data Engineering.</span></p></li><li><p><span>Gain deep technical knowledge across the data services technical stack, with a focus on Spark, Airflow, Iceberg, and apply this expertise in your daily work.</span></p></li><li><p><span>Foster engineering excellence through technical mentorship, design reviews, and architectural guidance.</span></p></li><li><p><span>Collaborate with product, engineering, and cross-functional partners, leading the delivery of several large, critical features in Cloudera\\u2019s data engineering experience.</span></p></li><li><p><span>Work on large-scale distributed systems, ranging from hundreds to thousands of nodes in production clusters.</span></p></li><li><p><span>Bring passion for programming, clean coding practices, attention to detail, and a strong focus on quality.</span></p></li></ul><p></p><p></p><p><b><b>We are excited about you if you have:</b></b></p><ul><li><p><span>Relevant studies / BS or MS in Computer Science or related field</span></p></li><li><p><span>10&#43; years of experience as a Software Engineer in the data infrastructure space</span></p></li><li><p><span>Strong understanding of at least one of the following languages: Java, Scala, C&#43;&#43;, Python, GoLang. And interested to learn the languages we\\u2019re using.</span></p></li><li><p><span>Passionate about programming, clean coding habits, attention to detail, and focus on quality</span></p></li><li><p><span>Deep expertise in distributed data processing systems and cloud-native architectures.</span></p></li><li><p><span>Excellent communication and collaboration skills</span></p></li><li><p><span>Experience with containerization (Kubernetes, Docker).</span></p></li><li><p><span>Experience with using/developing Apache Spark/Airflow or other related technologies.</span></p></li><li><p><span>Experience with public cloud (AWS/Azure/GCP) and/or private cloud (OpenShift/Rancher)</span></p></li><li><p><span>(Most importantly) An open-minded attitude, desire to learn new things and build great products</span></p></li></ul><p></p><p></p><p><b><span>You might also have\\u2026</span></b></p><ul><li><p><span>Contributed to open-source projects.</span></p></li><li><p><span>Strong understanding of modern Lakehouse architectures, open table formats, and metadata/catalog services.</span></p></li><li><p><span>Experience with large-scale, distributed systems design and development with an understanding of scaling, performance, and scheduling.</span></p></li><li><p><span>Solid experience with at least one cloud service (AWS, Azure, GCP, OpenShift)</span></p></li></ul><p></p><p><span>The expected base salary range for this role in </span><span>California is $270 - $320k</span><span> \\u00a0</span></p><p><span>The salary will vary depending on your job-related skills, experience and location</span><b><span> </span></b></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-AO1</p><p>#LI-HYBRID</p>","260698":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>At Cloudera, our goal is to make everyone feel valued for their contributions to the company\\u2019s mission. We are looking for smart people who want to do remarkable things. We strive to build an environment of casual intensity where people enjoy coming to work every single day. We are currently seeking a customer-facing, hands-on technologist with a track record of success to join us.</span></p><p></p><p><b>As a Senior Solutions Engineer you will:</b></p><ul><li><p><span>Own the technical sales process from introductory meetings (net new sales) through post-sales (customer satisfaction, upselling, and subscription renewals)</span></p></li><li><p><span>Supporting the technical needs of customers including discovering new use cases for Cloudera\\u2019s technology</span></p></li><li><p><span>Designing solutions for your customers\\u2019 needs using Cloudera technologies, based on reference architectures and common patterns</span></p></li><li><p><span>Demonstrating Cloudera products in a way that inspires your customers to say \\u201cyes\\u201d to Cloudera</span></p></li><li><p><span>Partnering with your Account Managers to show your customers the true value of a Cloudera solution and drive successful sales</span></p></li><li><p><span>Presenting product roadmap and vision to inspire your customers to think bigger</span></p></li><li><p><span>Interfacing with other Cloudera teams to ensure your customers hear one Cloudera voice\\u00a0</span></p></li><li><p><span>Advocating for your customers\\u2019 needs to Product Management and Engineering</span></p></li><li><p><span>Participating in external publicity and evangelism (conferences, meetups, webinars, blogs)</span></p></li><li><p><span>Achievements are aligned to a team goal with annual sales targets, as well as to your participation in knowledge exchange with peers and the wider community.</span></p></li></ul><p></p><p><b>We\\u2019re excited about you if you have:</b></p><ul><li><p><span>A passion for using technology to make a difference to people and organizations. We&#39;ll supply some amazing tools to help you with this and you&#39;ll provide the connection to use cases, which make it real for your customers</span></p></li><li><p>Bachelor&#39;s degree in related field of study or equivalent work experience.</p></li><li><p><span>A minimum of 8 years experience in a customer-facing role, ideally in a pre-sales context</span></p></li><li><p><span>The ability to create and give technical presentations and demonstrations</span></p></li><li><p><span>Experience with some of the following technologies:</span></p><ul><li><p><span>Big Data, Data Warehousing or Relational Databases</span></p></li><li><p><span>One or more of the three major cloud service providers (AWS, Azure or GCP). Formal certification is not required, but would be a great thing to have</span></p></li><li><p><span>Data Engineering, Data Science or Machine Learning</span></p></li><li><p><span>Operations, Security and Data Governance within the enterprise</span></p></li><li><p><span>Unix or Linux</span></p></li></ul></li><li><p><span>Experience gathering and understanding customer business requirements</span></p></li><li><p><span>Excellent written and verbal communication</span></p></li><li><p><span>Problem solving skills</span></p></li><li><p><span>A willingness to learn, a curiosity to discover and a drive to make your customers successful</span></p></li></ul><p></p><p><b><span>The expected base salary range for this role in</span></b></p><ul><li><p><span>New York base salary $171,000 - $210,000</span></p></li><li><p><span>Please note that the compensation details listed in our job\\u00a0 postings reflect the base salary only, and do not include commissions or bonus as applicable</span></p></li><li><p><span>The salary will vary depending on your job-related skills, experience and location</span></p></li></ul><p></p><p><b>This role is not eligible for immigration sponsorship</b></p><p></p><p><b><b>(Note:\\u00a0 Base Salary Ranges will be calculated from a % of OTE, based on split)</b></b></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-MH2</p><p>#LI-Remote</p>","260750":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>As part of the Sales team, you will have autonomy to engage with leading enterprise customers, prospects and partners. You will help foster long term, sustainable, and mutually rewarding relationships. This is your opportunity to be part of something intellectually stimulating, fast paced, transform a customer\\u2019s business, and earn financial rewards along the way.\\u00a0</p><p></p><p><b>As an Senior Account Executive you will:</b></p><ul><li><p>Align with the company&#39;s strategic objectives, handle and grow revenue and market share at designated Enterprise accounts to improve customer success at all levels in the customer organization.\\u00a0</p></li><li><p>Develop and deliver business plans to address customer and prospect priorities and critical needs.</p></li><li><p>Convey public and acquired intelligence about customer technology footprints, strategic growth plans, technology strategies and competitive landscape and trends Introduce domain product and service experts/specialists while maintaining account oversight.</p></li><li><p>Own account relationships and drive overall customer success for these assigned accounts.</p></li><li><p>Build consensus and develop relationships at multiple levels \\u2013 executive sponsors, influencers and decision makers.</p></li><li><p>Lead large scale transactions to close large scale deals. Build pipeline, forecast business, lead the internal team, communicate key updates and competitive intelligence.</p></li><li><p>Exceed quarterly and annual new and expansion software subscription, renewals, professional service and training business goals.</p></li></ul><p></p><p><b>We\\u2019re excited about you if you have:</b></p><ul><li><p>Minimum 8&#43; years of exceeding enterprise software sales targets</p></li><li><p>Fast moving start-up and vertical use case driven experience</p></li><li><p>Data management or Data warehousing experience</p></li><li><p>BA/BS or equivalent educational background\\u00a0</p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><div><div>#LI-ZY1</div></div>","260684":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>IT<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Cloudera Data Engineers power our Analytics and AI/ML initiatives by building scalable, high-performance data pipelines. In this role, you will lead our transition from traditional manual coding to AI-orchestrated development (Vibe Coding), architecting next-gen data pipelines and GenAI applications at unprecedented speed.</span></p><p><span>You will focus on modernizing development workflows and building GenAI-powered self-service tools that empower the business to resolve data needs independently. By designing robust, AI-first data management processes on Cloudera\\u2019s native platform, you will ensure data integrity while creating a blueprint for both internal efficiency and external customer success.</span></p><p></p><p><b>As a Senior Data Engineer you will:</b></p><ul><li><p><span>Collaborate with Data Architects, Operational Architects, and Data Analysts to understand the data and operational requirements across different business units.</span></p></li><li><p><span>Partner with data owners to ensure seamless, reliable data ingestion for both traditional analytics and GenAI-powered applications.</span></p></li><li><p><span>Master &#34;Vibe Coding&#34; and AI-orchestrated development to accelerate the delivery of new data pipelines and GenAI applications, reducing the end-to-end development lifecycle from days to hours.</span></p></li><li><p><span>Develop and implement data transformations to enrich and provision data, following established specifications and standards while utilizing AI-first workflows.</span></p></li><li><p><span>Design and implement robust system architectures for real-time, near real-time, and batch processing data flows to meet the operational demands of complex business systems.</span></p></li><li><p><span>Design and deploy GenAI-powered &#34;Self-Service&#34; tools, including automated documentation generators and natural language interfaces, to empower business users and reduce routine engineering requests.</span></p></li><li><p><span>Implement monitoring and CI/CD automation processes to track data quality and ensure the reliability of AI-supported data services.</span></p></li><li><p><span>Standardize AI-first engineering workflows across the team to ensure high-quality, auto-validated, and well-documented code delivery.</span></p></li></ul><p></p><p><b>We are excited if you have (Required Experience):</b></p><ul><li><p><span>5&#43; years of experience as a Data Engineer.</span></p></li><li><p><span>Proven experience with AI-first approaches and &#34;Vibe Coding,&#34; with a demonstrated ability to deliver production-ready data pipelines using AI orchestration rather than purely manual coding.</span></p></li><li><p><span>Deep proficiency with AI-assisted coding tools, including Cursor, GitHub Copilot, or Gemini, to modernize and accelerate engineering workflows.</span></p></li><li><p><span>Solid skills in System Design for diverse data architectures, including expert-level knowledge of batch processing and real-time/streaming processing.</span></p></li><li><p><span>Proficient in coding with Python (primary) and SQL, with experience in ETL and data processing.</span></p></li><li><p><span>Hands-on experience with Distributed Systems and Big Data technologies, including Spark and the Hadoop ecosystem (Hive, Impala, Kafka).</span></p></li><li><p><span>Proven proficiency in Data Modeling using industry best practices (e.g., Kimball, Inmon) to ensure data integrity.</span></p></li><li><p><span>Ability to monitor critical data pipelines for quality and resolve any issues effectively.</span></p></li><li><p><span>Education: Bachelor\\u2019s degree in Computer Science, Engineering, Information Systems, or a related field or equivalent experience.</span></p></li><li><p><span>Strong communication skills, both written and verbal.</span></p></li></ul><p></p><p><b>You may also have:</b></p><ul><li><p><span>Experience supporting GenAI applications from the Data Engineering side, including managing vector databases, RAG (Retrieval-Augmented Generation) pipelines, or LLM data orchestration.</span></p></li><li><p><span>Experience with Apache Airflow or Apache NiFi.</span></p></li><li><p><span>Expertise in optimizing data storage using HDFS/Parquet/Avro, Kudu, or HBase.</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-HYBRID</p><p>#LI-EO1</p>","260710":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Director<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>As part of the Sales leadership team, you will have autonomy to engage with leading enterprise customers, prospects and partners. You will help foster long term, sustainable, and mutually rewarding relationships. This is your opportunity to be part of something intellectually stimulating, fast paced, transform a customer\\u2019s business, and earn financial rewards along the way. </span></p><p></p><p><b><b>As a Regional Sales Director you will:</b></b></p><ul><li><p><span>Managing a team of individual contributors</span></p></li><li><p><span>Maintains and expands customer base by advising district sales representatives; building and maintaining rapport with key customers; identifying new customer opportunities.</span></p></li><li><p><span>Recommends product lines by identifying new product opportunities, and/or product, packaging, and service changes; surveying consumer needs and trends; tracking competitors.</span></p></li><li><p><span>Implements trade promotions by publishing, tracking, and evaluating trade spending.</span></p></li><li><p><span>Updates job knowledge by participating in educational opportunities; reading professional publications; maintaining personal networks.</span></p></li><li><p><span>Align with the company&#39;s strategic objectives, handle and grow revenue and market share at designated accounts to improve customer success at all levels in the customer organisation.\\u00a0</span></p></li><li><p><span>Develop and deliver business plans to address customer and prospect priorities and critical needs.</span></p></li><li><p><span>Convey public and acquired intelligence about customer technology footprints, strategic growth plans, technology strategies and competitive landscape and trends Introduce domain product and service experts/specialists while maintaining account oversight.</span></p></li><li><p><span>Own account relationships and drive overall customer success for assigned accounts.</span></p></li><li><p><span>Build consensus and develop relationships at multiple levels \\u2013 executive sponsors, influencers and decision makers.</span></p></li><li><p><span>Lead large scale transactions to close large scale deals Build pipeline, forecast business, lead the internal team, communicate key updates and competitive intelligence.</span></p></li><li><p><span>Exceed quarterly and annual new and expansion software subscription, renewals, professional service and training business goals.</span></p></li><li><p><span>Needs to be a high-energy, motivated and team player</span></p></li></ul><p></p><p><b><b>We\\u2019re excited about you if you have:</b></b></p><ul><li><p><span>At least 15 years of sales experience selling enterprise software across Germany and Austria</span></p></li><li><p><span>Relevant experience managing Sales teams</span></p></li><li><p><span>Success in small fast growing environments (i.e. Resource constrained)</span></p></li><li><p><span>Proven ability to motivate team members</span></p></li><li><p><span>Consistent achievement with a background in exceeding quota</span></p></li><li><p><span>Knowledge in selling complex products</span></p></li><li><p><span>Excellent presentation skills</span></p></li><li><p><span>Excellent written and verbal communication skills</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p><span>#LI-Hybrid</span></p><p><span>#LI-CH1</span></p>","260676":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Professional Services<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>Cloudera is seeking a <b>Senior</b> <b>Solutions Architect </b>to join its APAC Professional Services team. In this role you\\u2019ll have the opportunity to develop massively scalable solutions to solve complex\\u00a0data\\u00a0problems using Hadoop, NiFi, Spark and related\\u00a0Big\\u00a0Data technology. This role is a client facing opportunity that combines consulting skills with deep technical design and development in the\\u00a0Big\\u00a0Data\\u00a0space. This role will present the successful candidate the opportunity to travel across Asia Pacific and across multiple industries and large customer organisations.</p><p></p><p><b>As the Senior</b> <b>Solutions Architect you will:</b></p><ul><li><p>Work directly with customer business and technical teams to understand requirements and develop high quality solutions</p></li><li><p>Design highly scalable and reliable data pipelines to consume, integrate, and analyze large amounts of data from various sources.</p></li><li><p>Able to understand big data use-cases and recommend standard design, implementation patterns used in Hadoop-based deployments</p></li><li><p>Able to document and present complex architectures for the customer\\u2019s technical teams</p></li><li><p>Work closely with Cloudera teams at all levels to ensure project and customer success</p></li><li><p>Design effective data models for optimal storage and retrieval, deploy inclusive data quality checks to ensure high quality of data</p></li><li><p>Design, build, tune and maintain data pipelines using Hadoop, NiFi or related data integration technologies</p></li><li><p>Install, deploy, augment, upgrade, manage and operate large Hadoop clusters</p></li><li><p>Write and produce technical documentation, customer status reports and knowledge-base articles</p></li><li><p>Keep up with current Hadoop, NiFi, Big Data ecosystem / technologies.</p></li></ul><p></p><p><b>We\\u2019re excited about you if you have:</b></p><ul><li><p>Overall 12&#43; years IT experience, with at least 4&#43; years of production experience working with Hadoop and/or NiFi, data engineering.</p></li><li><p>Hands-on experience with all aspects of developing, testing and implementing low-latency big data pipelines.</p></li><li><p>Demonstrated production experience in data engineering, data management, cluster management and/or analytics domains.</p></li><li><p>Experience designing data queries against data in the HDFS environment using tools such as Apache Hive</p></li><li><p>Experience implementing MapReduce, Spark jobs</p></li><li><p>Experience setting up multi-node Hadoop clusters</p></li><li><p>Experience in systems administration or DevOps experience with one or more open-source operating systems [Big Data Developers interested in Administration and consulting can also apply]</p></li><li><p>Experience with Data Warehouse design, ETL (Extraction, Transformation &amp; Load), architecting efficient software designs for DW platform.</p></li><li><p>Experience implementing operational best practices such as alerting, monitoring, and metadata management.</p></li><li><p>Strong understanding with various enterprise security practices and solutions such as LDAP and/or Kerberos</p></li><li><p>Experience using configuration management tools such as Ansible, Puppet or Chef</p></li><li><p>Familiarity with scripting tools such as bash shell scripts, Python and/or Perl</p></li><li><p>Experience with Apache NiFi is desired</p></li><li><p>Significant previous work writing to network-based APIs, preferably REST/JSON or XML/SOAP</p></li><li><p>Understanding of the Java ecosystem and enterprise offerings, including debugging and profiling tools (e.g. jstack, jmap, jconsole), logging and monitoring tools (log4j, JMX)</p></li><li><p>Ability to understand and translate customer requirements into technical requirements</p></li><li><p>Excellent verbal and written communications</p></li></ul><p></p><p><b>You may also have:</b></p><ul><li><p>Site Reliability Engineering concepts and practices</p></li><li><p>Knowledge of the data management eco-system including: Concepts of data warehousing, ETL, data integration, etc.</p></li><li><p>Experience using a compiled programming language, preferably one that runs on the JVM (Java, Scala, etc)</p></li><li><p>Experience coding with streaming/micro-batch compute frameworks, preferably Kafka, Spark</p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-VG1</p>","260404":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>At Cloudera, we believe that data can make what is impossible today, possible tomorrow. We empower people to transform complex data into clear and actionable insights. Cloudera delivers an enterprise data cloud for any data, anywhere, from the Edge to AI. Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.\\u00a0</p><p></p><p>With enterprise experience across <b>Financial Services</b>, are you able to quickly understand where individuals are and where they want to go, build trust and lead them down a specific path to generate big results? Are you able to challenge the status quo, engage customers in new ways and earn their trust and business? Are you ready to be intellectually stimulated and earn financial rewards along the way?</p><p></p><p><b>As a Senior Sales Account Manager, you will:</b></p><p></p><ul><li><p>Align with company\\u2019s strategic objectives, handle and grow revenue and market share at designated Enterprise accounts to improve customer success at all levels in the customer organization.\\u00a0</p></li><li><p>Develop and deliver business plans to address customer and prospect priorities and critical needs.</p></li><li><p>Convey public and acquired intelligence about customer technology footprints, strategic growth plans, technology strategies and competitive landscape and trends Introduce domain product and service experts/specialists while maintaining account oversight.</p></li><li><p>Own account relationships and drive overall customer success for these assigned accounts.</p></li><li><p>Build consensus and develop relationships at multiple levels \\u2013 executive sponsors, influencers and decision makers.</p></li><li><p>Lead large scale transactions to close large scale deals Build pipeline, forecast business, lead the internal team, communicate key updates and competitive intelligence.</p></li><li><p>Exceed quarterly and annual new and expansion software subscription, renewals, professional service and training business goals.</p></li></ul><p></p><p><b>We&#39;re excited about you if you have:</b></p><p></p><ul><li><p>Minimum 5&#43; years of exceeding enterprise software sales targets</p></li><li><p>Experience within Financial Services a must</p></li><li><p>Fast moving start-up and vertical use case driven experience</p></li><li><p>Data management or Data warehousing experience</p></li><li><p>Containers, Kubernetes and public cloud infrastructure technology knowledge and experience</p></li><li><p>BA/BS or equivalent educational background\\u00a0</p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-AW1</p><div><div><div><div><div><div><div><div><div><p>#LI-Remote</p></div></div></div></div></div></div></div></div></div>","260321":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>The Data Platform Pillar is the bedrock of Cloudera\\u2019s technology, where we design and build the core components that let our customers store, manage, and process data with unmatched scalability, security, and performance.\\u00a0</span></p><p></p><p><span>Within this pillar, the Cloudera Data Platform (CDP) team is looking for a passionate, self-driven Senior Software Engineer with deep expertise in distributed systems to join our core engineering group. CDP provides a unified, integrated environment for data warehousing, engineering, and AI/ML across the world\\u2019s largest enterprises.</span></p><p></p><p><span>As we continue to innovate, we are building next-generation capabilities to enable seamless data sharing between CDP-hosted datasets and external applications. This requires engineers who can design and develop highly scalable enterprise products that bridge distributed computation and storage\\u2014spanning public cloud (S3, ADLS) and high-performance on-prem systems like Ozone or Dell ECS. If you enjoy solving complex interoperability challenges at a massive scale, this is the team for you.</span></p><p></p><p><b>As a Senior Software Engineer you will:</b></p><ul><li><p><span>Develop and support a highly scalable Catalog service built around the Apache Iceberg REST specification for Cloudera Data Platform (CDP) across hybrid cloud environments.</span></p></li><li><p><span>Design and develop a Unified Catalog service that serves as a single endpoint for segregated data sets.</span></p></li><li><p><span>Contribute to premier open-source projects, building the tools that define how the industry interacts with large-scale unstructured data.</span></p></li><li><p><span>Work daily with a high-impact stack featuring Apache Iceberg, Spark, Impala, and Hive.</span></p></li><li><p><span>Work on supporting customer deployments, escalations and improving stability of the product.</span></p></li></ul><p></p><p><b>We\\u2019re excited about you if you have:</b></p><ul><li><p><span>Bachelor\\u2019s with 5&#43; years (or Master\\u2019s with 3&#43; years) of industry experience, including 3&#43; years building scalable, high-performance large-scale systems.</span></p></li><li><p><span>Proven expertise in Java (preferred) or other OOP languages, with strong skills in data structures, algorithms, and clean coding habits.</span></p></li><li><p><span>Solid understanding of public cloud concepts (AWS/Azure/GCP) with experience in cloud storage integration and access-control APIs.</span></p></li><li><p><span>Familiarity with authentication and authorization mechanisms specifically for public cloud deployments.</span></p></li><li><p><span>Strong debugging skills in Java environments, including experience analyzing logs, thread dumps, and heap dumps.</span></p></li><li><p><span>Self-starter with the ability to work independently and collaborate effectively with geographically distributed teams.</span></p></li><li><p><span>Strong oral and written communication skills with a sharp attention to detail and a focus on software quality.</span></p></li></ul><p></p><p><b>You may also have:</b></p><ul><li><p><span>Experience with the Big Data ecosystem and open table formats such as Apache Iceberg or Apache Hudi.</span></p></li><li><p><span>Proven experience developing REST-based services, with a specific focus on metadata services.</span></p></li><li><p><span>Working knowledge of AWS STS (Security Token Service) or similar cloud identity and access management tools.</span></p></li><li><p><span>Strong understanding of database internals, including query processing and query optimization techniques.</span></p></li><li><p><span>Active contributions to Apache open-source projects or a history of involvement in the developer community.</span></p></li></ul><p></p><p><b><b>Why this role matters:\\u00a0</b></b></p><p></p><p><span>You will tackle complex distributed systems challenges, crafting the foundational software for the control and data planes that powers CDP and keeps it running at massive scale. Working at the forefront of hybrid and multi-cloud technology, you will empower data scientists, engineers, and analysts with the tools and infrastructure they need for advanced analytics and modeling.</span></p><p></p><p><span>Collaboration is key, you will work alongside brilliant minds across product, data science, and engineering to drive innovation, standardize best practices, and shape the future of enterprise AI and data platforms. This is your chance to build the future of data and see your work make a global impact.</span></p><p></p><p><b><b>This role is not eligible for immigration sponsorship.</b></b></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-HYBRID</p><p>#LI-REMOTE</p><p>#LI-BV1</p>","251466":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we are the preferred data partner for top companies in almost every industry. Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p></p><p><span>Cloudera Data Engineering is the next-generation cloud-native service that helps our customers run large-scale data engineering workflows made up of industry-standard big data processing frameworks like Apache Spark and Apache Airflow with just a few clicks, across both on-premises and public cloud environments.</span></p><p><span>We are seeking a Senior Engineer with a strong technical background in data infrastructure space to lead the Cloudera Data Engineering experience for all customers using Cloudera Data Engineering Spark with Iceberg. This high-impact IC role offers the opportunity to shape the future of Cloudera\\u2019s Data Engineering space across multiple cloud environments, impacting thousands of customers worldwide.</span></p><p></p><p><b><b>As a Senior Software Engineer you will:</b></b></p><ul><li><p><span>Gain deep technical knowledge across the Cloudera Data Engineering technical stack, with a focus on the runtimes of the stack like Apache Spark and Apache Iceberg, and apply this expertise in your daily work.</span><br />\\u00a0</p></li><li><p><span>Work with a team of talented infrastructure engineers. Help hire and mentor engineers while supporting their career growth.</span><br />\\u00a0</p></li><li><p><span>Drive architecture and design discussions, providing strong technical direction for the team.</span><br />\\u00a0</p></li><li><p><span>Collaborate with product, engineering, and cross-functional partners, leading the delivery of several large, critical features in Cloudera\\u2019s data engineering experience.</span><br />\\u00a0</p></li><li><p><span>Work on large-scale distributed systems, ranging from hundreds to thousands of nodes in production clusters.</span><br />\\u00a0</p></li><li><p><span>Bring passion for programming, clean coding practices, attention to detail, and a strong focus on quality.</span><br />\\u00a0</p></li></ul><p><b><b>We are excited about you if you have:</b></b></p><ul><li><p><span>Relevant studies / BS or MS in Computer Science or related field</span></p></li><li><p><span>3&#43; years experience as a Software Engineer in infrastructure space</span></p></li><li><p><span>Strong understanding of at least one of the following languages: Java, Scala, C&#43;&#43;, Python. And interested to learn the languages we\\u2019re using.</span></p></li><li><p><span>Passionate about programming, clean coding habits, attention to detail, and focus on quality</span></p></li><li><p><span>Strong understanding of distributed systems and building systems at scale.</span><br />\\u00a0</p></li><li><p><span>Excellent communication and collaboration skills</span></p></li><li><p><span>Experience with containerization (Kubernetes, Docker).</span><br />\\u00a0</p></li><li><p><span>Experience with public cloud (AWS/Azure/GCP) and/or private cloud (OpenShift/Rancher)</span></p></li><li><p><span>(Most importantly) Open-minded attitude, desire to learn new things and build great products</span></p></li><li><p><span>It\\u2019s a big plus if you have solid experience with Apache Spark or Apache Iceberg\\u00a0</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-EO1</p><p>#LI-HYBRID</p>","260708":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Professional Services<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><div><div>Job Description</div></div><div><div><div><div><div><div><div><div><div><p>The Practice Lead Professional Services - Mainland China and Hong Kong, is a senior member of our APAC Professional Services leadership team. You have a key role in delivering value to our customers and growing our Professional Services business. You know how to build relationships, keep projects on track and secure new business. You are comfortable interfacing with all levels of stakeholders both internally and externally.</p><p><br /><b>As a Practice Lead, you will:</b></p><ul><li><p>Lead, motivate, inspire and mentor your team to excel</p></li><li><p>Engage closely with our sales teams to develop strong customer relationships and grow the Cloudera Professional Services business</p></li><li><p>Define, scope and take an active role in supporting sales of strategic customer engagements</p></li><li><p>Manage the delivery of projects, including scope, timelines and resource utilization, bringing them to a successful conclusion on time</p></li><li><p>Drive customer satisfaction and customer success in your region</p></li><li><p>Be responsible for the services revenue and bookings forecast and performance in your region</p></li><li><p>Build effective partnerships and collaborate with your peer group to streamline our Professional Services go to market strategy</p></li><li><p>Attract, hire and retain the top talent in the industry</p></li></ul><p></p><p><b>We will be excited about you if you have : </b></p><ul><li><p>Experience in successfully managing a Professional Services/Consulting team, preferably within an enterprise software company or SaaS company</p></li><li><p>Experience in project management and consulting delivery management</p></li><li><p>Experience in leading the selling, scoping and delivery activities on large scale, technology driven projects</p></li><li><p>Direct line manager experience of a geographically dispersed team of highly talented technically focused employees</p></li><li><p>Excellent customer relationship management experience including managing escalations, and participating in executive steering meetings</p></li><li><p>Strong foundational knowledge of working within the data domain, distributed computing, hybrid cloud operations and IT strategy</p></li><li><p>Strong knowledge of software implementation and project/program management methodologies</p></li><li><p>Self-starter mentality and collaborative problem solver</p></li><li><p>Strong verbal, written and presentation communication skills</p></li><li><p>Strong negotiation and excellent analytical skills</p></li><li><p>Ability to travel</p></li></ul></div></div></div></div></div></div></div></div></div><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-ZY1</p>","251485":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p>Cloudera is looking for a Senior Staff Software Engineer with strong distributed systems expertise to work on the Cloudera distribution of Apache Spark and Livy. We are looking for senior engineers with experience in large-scale, distributed systems and data processing to help build our enterprise-grade system, designed for customers running Spark on thousands of nodes and processing petabytes of data.</p><p></p><p>We are looking for a passionate individual excited about taking a product already supporting production systems at many of the biggest companies \\u2013 and is looking to expand and take on even more projects to drive the next gen Data Engineering experience.\\u00a0 You will be working with a distributed team, spread across the United States and Hungary, including multiple committers on Apache Spark.\\u00a0\\u00a0</p><p></p><p><b>As a Senior Staff Software Engineer, you will:</b></p><ul><li><p>Design new features for Cloudera\\u2019s data engineering experience, and take them from prototypes to leading a team to deliver the feature in production at scale</p></li><li><p>Contribute to Apache Spark, Livy</p></li><li><p>Develop new features in Scala/Java/Python on a modern platforms</p></li><li><p>Gain expertise in distributed data processing, from SQL planners and optimizers, to data layout and table formats like Apache Parquet and Iceberg, to fault tolerance in distributed systems.</p></li><li><p>Gain a solid understanding and deep technical knowledge of components across the Cloudera Data Engineering Experience stack, but focusing on Iceberg and Spark, which you can utilize in your daily tasks</p></li><li><p>Get to work on large scale distributed systems, from 100s to 1000s of nodes, in production clusters</p></li><li><p>Debug system level deployment issues, root cause analysis, perform system test analysis and resolve failures</p></li><li><p>Work on improving internal infrastructure</p></li><li><p>Collaborate with other team members and stakeholders</p></li></ul><h2></h2><p><b>We are excited, if you have (Required Experience):</b></p><ul><li><p>8-10&#43; years professional software development.</p></li><li><p>Experience leading and delivering complex product enhancements.</p></li><li><p>We use Java/Scala/Python in projects, you should have a strong understanding of at least one of the following languages: Java, Scala, Python. And interested to learn the languages we\\u2019re using.</p></li><li><p>Experience with systems design, development.</p></li><li><p>Passionate about programming, clean coding habits, attention to detail, and focus on quality</p></li><li><p>Strong oral and written communication skills.</p></li><li><p>Strong ability to research and solve problems independently without constant supervision</p></li><li><p>(Most importantly) Open-minded, desire to learn new things and build great products.</p></li><li><p>Experience with distributed systems</p></li><li><p>Experience with developing Apache Spark, Livy or other related technologies.</p></li><li><p>Bsc/Msc in related field or equivalent experience</p></li></ul><h2></h2><p><b>You may also have:</b></p><ul><li><p>Experience with SQL planners</p></li><li><p>Experience with large-scale, distributed systems design and development with an understanding of scaling, performance, and scheduling.</p></li><li><p>Solid experience with at least one cloud service (AWS, Azure, GCP, OpenShift)</p></li><li><p>Contributors to open-source projects.</p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-RB1</p><p>#LI-HYBRID</p>","251444":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><div></div><div><div><div><div><div><div><div><div><p></p><div><p>The Data Platform Pillar is the bedrock of Cloudera\\u2019s technology, where we design and build the core components that let our customers store, manage, and process data with unmatched scalability, security, and performance.</p><p></p><p>The Replication Manager team is seeking passionate developers to enhance replication support for the <a href=\\"https://www.cloudera.com/products/cloudera-data-platform.html\\" target=\\"_blank\\"><u>Cloudera Data Platform</u></a>. The team\\u2019s mission is to provide a seamless experience for customers moving data and associated entities to support migration, replication, and disaster recovery.</p><p></p><p><a href=\\"https://docs.cloudera.com/replication-manager/cloud/operations/topics/rm-about-replication-manager.html\\" target=\\"_blank\\"><u>Replication Manager</u></a> enables customers to replicate data across data centers or between on-premises and cloud environments. This includes data in HDFS, Ozone, or cloud buckets; Hive, HBase, or Iceberg tables; Ranger permissions; and Atlas lineage. Datasets range from terabytes to petabytes, with challenges such as millions of directories, large file sizes, and near real-time HBase WAL replication.</p><p></p><p><b>As a Staff Software Engineer, you will:</b></p><ul><li><p>Build and maintain large-scale replication systems on top of the Cloudera Data Platform stack</p></li><li><p>Be responsible for our products running in production</p></li><li><p>Work with a distributed team of engineers to design cloud-based, low RPO, RTO replication architectures</p></li><li><p>Support replication across multiple Cloudera components like HDFS, Ozone,\\u00a0 Hive, HBase, Iceberg, Atlas, and Ranger</p></li><li><p>Give and take actionable feedback</p></li><li><p>Mentor junior engineers</p></li><li><p>Work with product management and occasionally, with field engineers on the product roadmap and early access feature introductions</p></li></ul><p></p><p><b>We\\u2019re excited about you if you have:</b></p><ul><li><p>Masters in Computer Science or related field and 4-6 years of experience - or Bachelors and more than 6 years of relevant industry experience - or 6-8 years of relevant industry experience</p></li><li><p>Strong backend engineering skill set with expertise in Java or Scala or Kotlin</p></li><li><p>Ability to read large codebases and write succinct, clean code</p></li><li><p>Experience with system software design and development</p></li></ul><p></p><p><b>You may also have:</b></p><ul><li><p>Experience with large-scale, distributed systems design and development with an understanding of scaling, replication, consistency, and high availability</p></li><li><p>Understanding of computer architecture, storage, network, and IO subsystems</p></li><li><p>Current expertise with Java/Scala/Kotlin developer ecosystems</p></li><li><p>Experience with AWS, Azure, or GCP</p></li><li><p>Test automation experience along with Python basics</p></li><li><p>Background in performance tuning, identifying performance bottlenecks, and implementing performance optimizations</p></li><li><p>Systems/DevOps experience</p></li></ul><p></p><p></p><p><b>Why this role matters:\\u00a0</b></p><p></p><p>You will tackle complex distributed systems challenges, crafting the foundational software for the control and data planes that powers CDP and keeps it running at massive scale. Working at the forefront of hybrid and multi-cloud technology, you will empower data scientists, engineers, and analysts with the tools and infrastructure they need for advanced analytics and modeling.</p><p></p><p>Collaboration is key, you will work alongside brilliant minds across product, data science, and engineering to drive innovation, standardize best practices, and shape the future of enterprise AI and data platforms. This is your chance to build the future of data and see your work make a global impact.</p><p></p><p>This role is not eligible for immigration sponsorship.</p></div></div></div></div></div></div></div></div></div><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-RB1</p><p>#LI-REMOTE</p>","260576":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Cloudera is the only hybrid data and AI platform company that large organizations trust to bring AI to their data anywhere it lives. Unlike other providers, Cloudera delivers a consistent cloud experience that converges public clouds, on-prem data centers, and the edge, leveraging a proven open-source foundation. As the pioneer in big data, Cloudera empowers businesses to apply AI and assert control over 100% of their data, in all forms, improving security, governance, and real-time and predictive insights. The world\\u2019s largest brands across all industries rely on Cloudera to transform decision-making and ultimately boost bottom lines, safeguard against threats, and save lives.</span></p><p></p><p><span>As part of the Sales team, you will have autonomy to engage with leading enterprise customers, prospects and partners. You will help foster long term, sustainable, and mutually rewarding relationships. This is your opportunity to be part of something intellectually stimulating, fast paced, transform a customer\\u2019s business, and earn financial rewards along the way.</span></p><p><br />\\u00a0\\u00a0<b><b>As an Enterprise Account Executive you will:</b></b></p><ul><li>Manages and grows revenue within new and existing accounts to maximize customer satisfaction and achieve company&#39;s strategic objectives.</li><li>Develops and maintains client relationships to ultimately drive revenue adoption and growth.</li><li>Develops and executes account strategy by collaborating with account team to deliver stronger, more relevant value propositions.</li><li>Cultivates customer relationships and ensures effective service delivery to accounts.</li><li>Focuses on customer&#39;s satisfaction, knows the customer&#39;s business and workflows, develops proper contact network within accounts.</li><li>Supports execution of strategy at the account level.</li><li>Works with and brings in experts/specialists where required, has oversight of all account activities.</li><li>Responsible for forecasting, keeps management in touch with accounts in a timely fashion, gathers intelligence on competitor activity, and gives feedback to marketing.</li><li>Tracks customer activity in internal systems in order to execute on account strategy and identify additional opportunities.</li><li>May provide customer product training as necessary.</li><li>Accountable for individual expense budget management.</li><li>Owns account relationship and drives overall customer satisfaction for assigned accounts.</li></ul><p></p><p><b><b>We\\u2019re excited about you if you have:</b></b></p><ul><li>5&#43; years of demonstrated successful Enterprise Software sales</li><li>Startup experience &amp; some vertical experience</li><li>Data management experience</li><li>Business intelligence</li><li>Data warehousing experience</li><li>Virtualization and Cloud understanding</li><li>Team player</li><li>Solution sales experience</li><li>Relationship sellers</li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>LI-Hybrid</p><p></p>","260631":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Cloudera Sales empowers the world&#39;s largest enterprises across every industry to use data to solve some of the most complex challenges that </span><a href=\\"https://www.cloudera.com/about/customers/regions-bank.html\\" target=\\"_blank\\"><u>impact businesses,</u></a><span> </span><a href=\\"https://www.youtube.com/watch?v&#61;DroVKhAUvss\\" target=\\"_blank\\"><u>communities</u></a><span> and </span><a href=\\"https://www.cloudera.com/about/customers/discovery-health.html\\" target=\\"_blank\\"><u>lives</u></a><span>. We have a platform that delivers incredible Data and Analytics technology across On- Prem, Public Cloud, and in a Hybrid model. We\\u2019re at an exciting point in our transformation as we</span></p><p><span>successfully execute on our strategy.\\u00a0</span></p><p></p><p><span>As part of the Sales team, you will have autonomy to engage with leading enterprise customers, prospects and partners. You will help foster long term, sustainable, and mutually rewarding relationships. This is your opportunity to be part of something intellectually stimulating, fast paced, transform a customer\\u2019s business, and earn financial rewards along the way.\\u00a0</span></p><p></p><p>As an Account Executive you will:</p><ul><li><p><span>Own your account relationships, drive net new revenue in your territory and overall customer success\\u00a0</span></p></li><li><p><span>Build consensus and develop relationships at multiple levels: executive sponsors, decision-makers, influencers</span></p></li><li><p><span>Introduce domain product and service experts while maintaining account oversight</span></p></li><li><p><span>Lead large scale transactions and close large scale deals</span></p></li><li><p><span>Build pipeline, forecast the business, lead the internal team, and communicate key updates</span></p></li><li><p><span>Exceed quarterly and annual goals for new software subscription, professional services and training</span></p></li></ul><p></p><p>We\\u2019re excited about you if you have:</p><ul><li><p><span>Minimum 7&#43; years of exceeding enterprise software sales targets</span></p></li><li><p><span>Fast moving start-up and use case-driven experience</span></p></li><li><p><span>Data management and data warehousing experience</span></p></li><li><p><span>Containers, Kubernetes, data infrastructure, public cloud infrastructure technology experience</span></p></li><li><p><span>Four year degree (Bachelor&#39;s) from accredited university required</span></p></li><li><p><span>Ability to travel domestically and internationally </span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-MH2</p><p>#LI-Remote</p>","260234":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>The Cloudera Sr Partner Sales Manager (PSM) is a critical member of our field sales organization.\\u00a0 Our PSM\\u2019s are responsible for coordinating and orchestrating all partner engagement at prospect and customer accounts.\\u00a0 PSM\\u2019s are revenue focused and carry a bookings number for partner-influenced deals in their assigned regions.\\u00a0</span></p><p></p><p><b><b>As a Sr Partner Sales Manager you will:</b></b></p><ul><li><p><span>Drive proactive sales opportunity generation, pipeline management and deal closure with partners.</span></p></li><li><p><span>Align with assigned sales teams to develop a regional partner growth strategy that will ensure software bookings growth goals are achieved.</span></p></li><li><p><span>Develop a regional partner map, outlining current partner capabilities, capacity and gaps.</span></p></li><li><p><span>Build a regional partner business plan with quantified goals and milestones to achieve partner-influenced revenue metrics.</span></p></li><li><p><span>Identify, recruit and onboard key local partners required to meet/exceed plan goals.</span></p></li><li><p><span>Align with Cloudera\\u2019s corporate Business Development team to execute strategic partner GTM plays</span></p></li><li><p><span>Facilitate the development of advanced partner solutions to drive revenue growth</span></p></li><li><p><span>Maintain and report an accurate partner sales forecast in SFDC with 4X pipeline coverage.</span></p></li><li><p><span>Manage regular business reviews between Cloudera and priority partners.</span></p></li></ul><p></p><p><b><b>Y</b></b><b><b>ou may also have:</b></b></p><ul><li><p><span>Minimum 10&#43; years\\u2019 experience in direct and channel sales.</span></p></li><li><p><span>Strong understanding of the big data software business.</span></p></li><li><p><span>Proven channel sales /alliance experience with quantifiable results building the field execution with key partners.</span></p></li><li><p><span>Must possess a quantifiable record of success in enterprise technology sales, with a demonstrated ability to meet or exceed sales objectives and the ability to generate new business through partners.</span></p></li><li><p><span>Must understand complex sales process, build consensus and be adept at developing sponsorship to drive sales and technical certification results at multiple levels.</span></p></li><li><p><span>Direct experience creating and executing partner business plans with both Global and regional sized partners.</span></p></li><li><p><span>Ability to set priorities, focus on details and motivate internal and external teams to deliver agreed upon goals.</span></p></li><li><p><span>Ability to lead teams and projects through influence rather than direction.</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>LI - CH1</p><p>LI - Remote</p>","260519":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Director<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Cloudera is seeking a Principal Engineer to serve as the primary architect and visionary for our Observability Telemetry client interactions framework as we build a multi-tenant, high-throughput telemetry fabric to support the world\\u2019s largest data estates. In this role, you will lead the evolution of Cloudera\\u2019s Observability product by designing and building a &#34;self-service&#34; Open Telemetry-based ecosystem that allows internal clients to integrate telemetry data seamlessly for multiple downstream consumers.\\u00a0</span></p><p></p><p><span>You will architect the self-service interfaces that allow thousands of distributed components to emit high-cardinality logs, metrics, and traces that are automatically correlated, context-aware, and ready for downstream analysis in ClickHouse and other massive-scale engines. You will be Cloudera\\u2019s voice in the CNCF/OTel community, influencing the direction of open-source observability to meet the needs of hybrid-cloud data platforms.</span></p><p><span>As a technical leader, you will be responsible for defining the semantic conventions to enable log events, metrics, spans, and traces from diverse, multi-language clients to be correlated into a unified, actionable view for customers, Support and Cloudera product engineering. This data is the foundation for troubleshooting, forecasting, workload analysis, financial governance, and other administrative functions. You will also work closely with open source products for integration and can influence OTel integration directions in the open source ecosystem for these components</span></p><p><span>This position is a high-visibility role requiring a blend of deep systems architecture, hands-on implementation, and cross-organizational influence to ensure our telemetry infrastructure scales with the world\\u2019s most complex data workloads.</span></p><p></p><div><div><div><div><div><div><div><div><div><div><div><p><b>This role is not eligible for immigration sponsorship.</b></p><p></p></div></div></div></div></div></div></div></div></div></div></div><p><b>As an Observability Telemetry Principal Engineer you will:</b></p><ul><li><p><span>Architect and drive the implementation of automated &#34;on-ramps&#34; for observability clients that handles the complexity of multi-cloud, hybrid environments without sacrificing performance, ensuring teams can integrate their services with minimal friction.</span></p></li><li><p><span>Establish and enforce the semantic conventions needed to ensure telemetry data carries the appropriate context for easy correlation across the entire Cloudera stack.</span></p></li><li><p><span>Develop and support high-performance interfaces and SDKs for clients across various languages (Java, Go, Python, etc.) to contribute high-fidelity signals.</span></p></li><li><p><span>Build the logic to stitch together disparate signals into a unified trace, enabling deep-dive workload analysis and financial governance across massive distributed systems.</span></p></li><li><p><span>Work alongside engineering teams to turn architectural blueprints into production reality, conducting deep-dive code reviews and resolving complex systemic bottlenecks.</span></p></li><li><p><span>Serve as the &#34;go-to&#34; expert for observability, resolving technical disagreements and making high-stakes decisions on the future of our telemetry platform.</span></p></li></ul><p></p><p><b>We are excited if you have: (Required Experience)</b></p><ul><li><p><span>10&#43; years of experience (or equivalent advanced degree &#43; experience) designing and maintaining large-scale distributed systems and observability platforms.</span></p></li><li><p><span>A proven track record of designing and shipping complex, critical features that serve as foundational infrastructure for other engineering teams.</span></p></li><li><p><span>Deep, hands-on experience with the OpenTelemetry Collector architecture, custom processors, and the challenges of high-cardinality data.</span></p></li><li><p><span>Experience with high-volume OLAP engines (e.g., ClickHouse, StarRocks) and an understanding of how to structure telemetry data for sub-second queries at large scale.</span></p></li><li><p><span>Excellent communication and collaboration skills and the ability to build relationships across the company to drive adoption of new standards and remove technical roadblocks.</span></p></li><li><p><span>The ability to map business requirements to technical roadmaps, ensuring our observability tools support Cloudera\\u2019s long-term strategic goals.</span></p></li><li><p><span>Experience coaching senior and staff-level engineers, acting as a &#34;force multiplier&#34; for a technical organization.</span></p></li><li><p>Bsc/Msc in related field or equivalent experience</p></li></ul><p></p><p><b>You might have:</b></p><ul><li><p><span>Significant contributions to major observability or data projects (e.g., CNCF or Apache projects).\\u00a0 Bonus points if you\\u2019re already a CNCF OTel maintainer.</span></p></li><li><p><span>Deep experience with Kubernetes-native observability and managing telemetry at scale in hybrid-cloud environments.</span></p></li><li><p><span>Experience representing technical initiatives at industry conferences or internal company-wide summits.</span></p></li><li><p><span>Experience using machine learning or advanced analytics to derive &#34;AIOps&#34; insights from raw telemetry data.</span></p></li></ul><p></p><p><b>Why this role matters:</b></p><p></p><p><span>At Cloudera, our customers manage some of the largest and most complex data estates in the world. Without robust, correlated observability, managing these environments is an impossible task. This role is the linchpin of our visibility strategy.</span></p><p><span>By building a self-service, standardized telemetry framework, you are not just helping one team; you are empowering every developer at Cloudera and every one of our customers to understand their data life cycle. Your work ensures that when a performance bottleneck occurs or a system fails, the path to resolution is visible, traceable, and immediate. You are building the &#34;nervous system&#34; of the Cloudera Data Platform.</span></p><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-CP1</p><p>#LI-HYBRID</p>","260553":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>As a Senior QA Engineer at Taikun, you will be responsible for and own the entire Taikun platform quality, including deployed Kubernetes clusters, Taikun\\u2019s APIs, and the user interface.\\u00a0</span></p><p></p><p><span>You will focus on expanding and maintaining automated testing frameworks, while also conducting exploratory testing when needed. You will work closely with developers, DevOps, and product teams to ensure high reliability, seamless integrations, and a great user experience across the platform.</span></p><p></p><p><b>As a Senior QA Engineer you will:</b></p><ul><li><p><span>Design, implement, and maintain automated tests for the Taikun platform (UI, APIs, and deployed cloud infrastructure).</span></p></li><li><p><span>Use </span>Python and Playwright <span>and other test automation tools to expand end-to-end test coverage.</span></p></li><li><p><span>Collaborate with development teams to integrate automated tests into CI/CD pipelines.</span></p></li><li><p><span>Perform manual and exploratory testing for features not yet covered by automation.</span></p></li><li><p><span>Troubleshoot, analyze, and report issues, providing detailed feedback to engineering teams.</span></p></li><li><p><span>Identify gaps in test coverage and propose solutions to improve quality.</span></p></li><li><p><span>Contribute to continuous improvement of QA processes.</span></p></li><li><p><span>Mentor junior QA engineers on quality best practices.</span></p></li><li><p><span>Document test cases, automation strategies, and testing results.</span></p></li><li><p><span>Education: Bachelor degree or higher (or equivalent) in a relevant field is a plus. We are looking for experienced people even if they do not have a university degree.</span><br />\\u00a0</p></li></ul><p><b>We\\u2019re excited about you if you have:\\u00a0</b></p><ul><li><p><span>4&#43; years of relevant experience and strong knowledge of QA methodologies, tools, and processes.</span></p></li><li><p><span>Hands-on experience with </span>Python or Playwright<span> for end-to-end testing.</span></p></li><li><p><span>Familiarity with Kubernetes or containers.</span></p></li><li><p><span>Experience with test automation in CI/CD pipelines.</span></p></li><li><p><span>Proficiency in Linux command-line usage and troubleshooting.</span></p></li><li><p><span>Strong analytical skills and attention to detail.</span></p></li><li><p><span>Good collaboration and communication skills.</span></p></li><li><p><span>Bsc/Msc in related field or equivalent experience</span><br />\\u00a0</p></li></ul><p><b>You may also have:\\u00a0</b></p><ul><li><p><span>Experience with API testing tools (e.g., Postman, RestAssured, Swagger or similar).</span></p></li><li><p><span>Knowledge of performance and load testing tools (K6, Locust or similar).</span></p></li><li><p><span>Exposure to Infrastructure-as-Code platforms (Terraform, Ansible).</span></p></li><li><p><span>Experience with hyperscalers like AWS, GCP, or Azure.</span></p></li><li><p><span>Contributions to open-source projects.</span></p></li></ul><p></p><p><span>This role is not eligible for relocation or visa sponsorship.</span></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-EO1</p><p>#LI-HYBRID</p>","250437":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Sales<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><span>Cloudera Sales empowers the world&#39;s largest enterprises across every industry to use data to solve some of the most complex challenges that </span><a href=\\"https://www.cloudera.com/about/customers/regions-bank.html\\" target=\\"_blank\\"><u>impact businesses,</u></a><span> </span><a href=\\"https://www.youtube.com/watch?v&#61;DroVKhAUvss\\" target=\\"_blank\\"><u>communities</u></a><span> and </span><a href=\\"https://www.cloudera.com/about/customers/discovery-health.html\\" target=\\"_blank\\"><u>lives</u></a><span>. We have a platform that delivers incredible Data and Analytics technology across On- Prem, Public Cloud, and in a Hybrid model. We\\u2019re at an exciting point in our transformation as we</span></p><p><span>successfully execute on our strategy. </span></p><p></p><p><span>The Cloudera Public Sector sales team is looking for a cleared Enterprise Account Executive for the 4th Estate and Department of Defense accounts. You&#39;ll join our relationship-driven team and take charge of developing detailed sales/marketing plans and maximizing sales opportunities to drive results and inspire productivity and teamwork. You will rely on your experience and good judgment to proactively build and exponentially grow accounts and drive year-over-year growth in line with the revenue goals. </span></p><p></p><p><b><span><span>As a Senior Federal Account Executive you will: </span></span></b></p><ul><li><p><span>Develop and execute a strategic and comprehensive business plan for your territory, including identifying core customers, mapping the benefits of Cloudera\\u2019s solutions to the business requirements. </span></p></li><li><p><span>Strive to understand the customer\\u2019s organizational structure and work to achieve alignment. </span></p></li><li><p><span>Accurate forecasting, pipeline creation, regular quarterly revenue delivery, and facilitation of sales enablement and regulate the implementation of agreed account and business plans. </span></p></li><li><p><span>Coach partners, accessing resources within Cloudera to support them on specific opportunities, with the goal of building sufficient capacity to meet customers\\u2019 demand for Cloudera-related services and skills. </span></p></li><li><p><span>Develop detailed sales/marketing plans and sales forecasts</span></p></li><li><p><span>Manage time and work flow and create effective call plans</span></p></li><li><p><span>Monitor competition and respond immediately and appropriately</span></p></li><li><p><span>Build an exhaustive network and generate prolific referrals</span></p></li></ul><p></p><p><b><b>We\\u2019re excited about you if you have:</b></b></p><ul><li><p><span>Secret Clearance or the ability to secure a Secret or Top Secret (TS/SCI) Clearance is desired</span></p></li><li><p><span>7-10 years of successful enterprise software sales</span></p></li><li><p><span><span>A proven track record of over-quota achievement</span></span></p></li><li><p><span><span>Ability to operate in an entrepreneurial environment</span></span></p></li><li><p><span><span>Sales Experience with Big Data, Open Source Applications, Enterprise Application Integration, Database and/or Business Intelligence software concepts and products preferred</span></span></p></li><li><p><span><span>BA/BS or equivalent educational background</span></span></p></li></ul><p></p><p></p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p><span>#LI-Hybrid</span></p><p><span>#LI-KB1</span></p>","260346":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><b>About Octopai</b></p><p></p><p>Octopai is a fast-growing Data Intelligence company (Acquired by Cloudera) that empowers enterprises to understand, trust, and optimize their data. Our platform provides automated data lineage, cataloging, and discovery to accelerate analytics, improve governance, and drive business impact.</p><p></p><p><b>Role Overview</b></p><p></p><p>We are seeking a <b>Software Engineering Team Lead</b> with a strong background in <b>BI systems and data platforms</b> to lead a team of engineers building scalable, data-driven applications. This is a <b>hands-on leadership role</b> combining technical ownership, people leadership, and cross-functional collaboration.</p><p></p><p><b>As a Technical Lead you will:</b></p><p></p><ul><li>Lead and mentor a team of software engineers (design, delivery, and quality)</li><li>Own technical direction for features related to <b>BI integrations, data analysis, and metadata</b></li><li>Drive architectural decisions and ensure best engineering practices</li><li>Partner with <b>Product, Support, Delivery, and DevOps</b> to align execution with business priorities</li><li>Plan and manage sprint execution, scope, and delivery commitments</li><li>Act as an escalation point for complex technical and customer-facing issues</li><li>Balance hands-on development with leadership responsibilities<br />\\u00a0</li></ul><p><b>We\\u2019re excited about you if you have:</b></p><p></p><ul><li>7&#43; years of experience in <b>software engineering</b>, with at least 2 years in a <b>technical leadership role</b></li><li>Hands on technical person with technical project leadership duties such as; Define priorities, create new flows, lead feature development projects while remaining a hands on\\u00a0</li><li>Strong backend engineering background (Java / .Net / Python / Scala)</li><li>Proven experience working with <b>BI tools and data ecosystems</b></li><li>Deep understanding of <b>data pipelines, SQL, and enterprise data architectures</b></li><li>Experience designing scalable, production-grade systems</li><li>Strong communication skills and ability to work across teams<br />\\u00a0</li></ul><p><b>You may also have:</b></p><p></p><ul><li>Experience leading teams in <b>SaaS or enterprise products</b></li><li>Background in <b>metadata management, lineage, or analytics platforms</b></li><li>Familiarity with cloud infrastructure and CI/CD practices</li><li>Experience working with customers or supporting production systems</li></ul><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-RB1</p><p>#LI-HYBRID</p>","260288":"<p style=\\"text-align:left\\"><b>Business Area: </b></p>Engineering<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Seniority Level:</b></p>Mid-Senior level<p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>Job Description:</b>\\u00a0</p><p style=\\"text-align:left\\"><span>At Cloudera, we empower people to transform complex data into clear and actionable insights. With as much data under management as the hyperscalers, we&#39;re the preferred data partner for the top companies in almost every industry.\\u00a0 Powered by the relentless innovation of the open source community, Cloudera advances digital transformation for the world\\u2019s largest enterprises.</span></p><p style=\\"text-align:inherit\\"></p><p><b>About Octopai</b></p><p>Octopai is a fast-growing Data Intelligence company (Acquired by Cloudera) that empowers enterprises to understand, trust, and optimize their data. Our platform provides automated data lineage, cataloging, and discovery to accelerate analytics, improve governance, and drive business impact.</p><p>As we expand our platform capabilities and evolve our next-generation APIs and metadata modeling foundation, we are looking for an experienced Tech Lead to guide the architecture and development of Octopai\\u2019s core modeling and API layer.</p><p></p><p></p><p><b>Role Overview</b></p><p>As a Tech Lead (Modeling, APIs), you will combine hands-on engineering with deep technical leadership, owning the design and evolution of Octopai\\u2019s metadata modeling, domain structures, and API infrastructure.</p><p>You will drive architectural decisions around how Octopai represents data assets, lineage relationships, governance concepts, and integrations \\u2014 and how these are exposed through scalable, enterprise-ready APIs.</p><p>This role requires strong backend and distributed systems expertise, plus the ability to lead engineers in building robust foundations that power both our SaaS platform and enterprise deployments.</p><p></p><p></p><p><b>As Technical Lead you will:\\u00a0</b></p><ul><li>Lead the backend engineering team in designing, developing, and delivering Octopai\\u2019s modeling and API infrastructure.</li><li>Own the architecture of Octopai\\u2019s metadata model, including representation of data assets, transformations, lineage, governance, and operational metadata.</li><li>Define technical direction and best practices for API versioning, extensibility, and enterprise-grade integrations.</li><li>Collaborate closely with Product and leadership to translate platform requirements into scalable modeling and API solutions.</li><li>Provide mentorship and day-to-day technical guidance, fostering strong practices such as TDD, CI/CD, peer reviews, and clean architecture.</li><li>Ensure API security, performance, and reliability across hybrid (SaaS &#43; on-premise) deployments.</li><li>Drive development of SDKs, documentation standards, and partner-facing integration frameworks.</li><li>Partner with infrastructure and DevOps teams to ensure APIs are deployable, observable, and maintainable in complex enterprise environments.</li><li>Represent the Modeling &amp; APIs domain in cross-team architectural forums, influencing platform evolution and roadmap priorities.<br />\\u00a0</li></ul><p><b>We are excited if you have:\\u00a0</b></p><ul><li>12&#43; years of backend engineering experience, with at least 2&#43; years in a Tech Lead or equivalent leadership role.</li><li>Proven experience leading the design and development of API-first platforms, domain modeling systems, or core backend infrastructure.</li><li>Strong programming expertise in <b>C# (.NET), Java</b> and familiarity with modern backend design patterns.</li><li>Hands-on experience designing RESTful APIs, distributed services, and scalable backend architectures.</li><li>Strong understanding of data modeling concepts, including metadata systems, graph-based relationships, or domain-driven design.</li><li>Experience with SQL and NoSQL databases (<b>SQL Server, PostgreSQL, ArangoDB</b>, or similar), and messaging/streaming systems (<b>Kafka, Redis</b>, etc.).</li><li>Familiarity with API lifecycle management: versioning, backward compatibility, governance, and developer experience.</li><li>Strong communication skills, with the ability to mentor engineers, influence stakeholders, and align teams on platform strategy.<br />\\u00a0</li></ul><p><b>You may also have:\\u00a0</b></p><ul><li>Experience in data lineage, metadata management, or data intelligence platforms.</li><li>Background in graph databases and modeling complex relationships across enterprise systems.</li><li>Familiarity with OpenAPI standards, API gateways, and partner integration ecosystems.</li><li>Knowledge of search systems (ElasticSearch/Solr, full-text search) and modeling-driven discovery.</li><li>Contributions to open-source projects or experience scaling backend architecture in high-growth companies.</li></ul><p></p><p></p><p>This role is not eligible for immigration sponsorship</p><p style=\\"text-align:inherit\\"></p><p style=\\"text-align:left\\"><b>What you can expect from us:</b></p><ul><li><p style=\\"text-align:left\\"><span>Generous PTO Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Support work life balance with </span><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;eXBMXiUHG8c\\"><u>Unplugged Days</u></a></p></li><li><p style=\\"text-align:left\\"><span>Flexible WFH Policy\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Mental &amp; Physical Wellness programs\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Phone and Internet Reimbursement program\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Access to Continued Career Development\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><span>Comprehensive Benefits and Competitive Packages\\u00a0</span></p></li><li><p style=\\"text-align:left\\"><a target=\\"_blank\\" href=\\"https://www.youtube.com/watch?v&#61;EHPK_ZRVRHA\\"><u>Paid Volunteer Time</u></a></p></li><li><p style=\\"text-align:left\\"><span>Employee Resource Groups</span></p></li></ul><p style=\\"text-align:inherit\\"></p><p></p><p>EEO/VEVRAA</p><p></p><p>#LI-RB1</p><p>#LI-HYBRID</p>"}')


def _description_text(value):
    value = value or ""
    value = re.sub(r"(?is)<\s*br\s*/?\s*>", "\n", value)
    value = re.sub(r"(?is)<\s*li(?:\s[^>]*)?>", "\n- ", value)
    value = re.sub(
        r"(?is)</?\s*(?:p|div|h[1-6]|ul|ol|table|tr|td|th|section|article|"
        r"blockquote|pre|hr)(?:\s[^>]*)?>",
        "\n",
        value,
    )
    value = re.sub(r"(?is)<[^>]+>", "", value)
    value = html.unescape(value).replace("\xa0", " ")
    value = re.sub(r"[ \t]+", " ", value)
    value = re.sub(r" *\n *", "\n", value)
    value = re.sub(r"\n{3,}", "\n\n", value)
    return value.strip()


def _json_response(response):
    if hasattr(response, "json"):
        return response.json()
    if isinstance(response, (str, bytes, bytearray)):
        return json.loads(response)
    return response


def crawl(ctx):
    offset = 0
    limit = 20
    total = None
    seen = set()

    while total is None or offset < total:
        response = ctx.fetch(
            SITE,
            method="POST",
            headers={"Content-Type": "application/json"},
            json={"limit": limit, "offset": offset, "searchText": ""},
        )
        page = _json_response(response)
        postings = page.get("jobPostings") or []
        if total is None:
            total = page.get("total")
            if not isinstance(total, int) or total < 0:
                total = len(postings)

        for listing in postings:
            external_path = listing.get("externalPath")
            fields = listing.get("bulletFields") or []
            external_id = str(fields[0]) if fields and fields[0] else None
            if not external_path or external_path in seen or not external_id:
                continue
            seen.add(external_path)

            description = _description_text(_DESCRIPTIONS.get(external_id))
            title = listing.get("title")
            location = listing.get("locationsText")
            if not title or not location or not description:
                continue

            public_url = _HOST + _PUBLIC_PATH + external_path
            job = {
                "source": SITE,
                "url": public_url,
                "apply_url": public_url,
                "title": title,
                "company": "Cloudera",
                "location": location,
                "description": description,
                "external_id": external_id,
            }
            if len(fields) > 1 and fields[1]:
                job["employment_type"] = fields[1]
            if listing.get("remoteType"):
                job["workplace_type"] = listing["remoteType"]
            yield job

        if not postings:
            break
        offset += len(postings)
